  public func duplicateBlock(_ block: OrgEditableBlock) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard block.isEditable,
          block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block cannot be duplicated"
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = await fileUndoSnapshot(for: source.file)
      let replacement = "\n" + block.rawText
      let updatedSource = try await Task.detached(priority: .userInitiated) {
        try Self.replacingSourceRange(
          in: source,
          startLine: block.endLineExclusive,
          endLineExclusive: block.endLineExclusive,
          replacement: replacement
        )
      }.value
      let currentRenderedBlocks = selectedRenderedBlocks
      try await replaceDocumentSourceRange(
        file: source.file,
        startLine: block.endLineExclusive,
        endLineExclusive: block.endLineExclusive,
        replacement: replacement
      )

      let updatedBlocks = await Task.detached(priority: .userInitiated) {
        Self.locallyInsertingRenderedBlocks(
          currentRenderedBlocks,
          atLine: block.endLineExclusive,
          replacement: replacement
        )
      }.value

      guard selectedEntrySource?.id == source.id else {
        await recordFileUndo(from: undoSnapshot)
        return
      }

      await recordFileUndo(from: undoSnapshot)
      invalidateCanonicalDocumentCache(for: source.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      selectedEntrySource = updatedSource
      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: updatedSource)
      selectedRenderedBlocks = updatedVisibleBlocks
      selectedBlockID = blockForSelectionLine(
        block.endLineExclusive + 1,
        mode: .nextOrNearest,
        in: updatedVisibleBlocks
      )?.id
      statusText = "Duplicated block in \(relativePath(source.file))"
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Duplicate failed"
    }
  }

  @discardableResult
  public func deleteBlock(_ block: OrgEditableBlock) async -> Bool {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return false
    }
    guard block.isEditable,
          block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      statusText = "Block cannot be deleted"
      return false
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = await fileUndoSnapshot(for: source.file)
      let deletionRange = try await Task.detached(priority: .userInitiated) {
        try Self.deletionRange(for: block, in: source)
      }.value
      if source.isSubtree, block.startLine == source.startLine {
        try await deleteDocumentSourceRangeCleaningAdjacentBlank(
          file: source.file,
          startLine: deletionRange.startLine,
          endLineExclusive: deletionRange.endLineExclusive,
          allowDestructiveReplacement: true
        )
        await recordFileUndo(from: undoSnapshot)
        invalidateCanonicalDocumentCache(for: source.file)
        transientDraftBlock = nil
        resetBlockEditing()
        isEditingEntry = false
        selectedEntrySourceMode = .page
        if selectedLocation != nil {
          await reloadSelectedEntrySource()
        } else {
          selectedEntrySource = nil
          selectedRenderedBlocks = []
          selectedEntryHTML = nil
        }
        statusText = "Deleted entry in \(relativePath(source.file))"
        scheduleAgendaRefresh(preserveSelection: true)
        return true
      }

      let deletion = try await Task.detached(priority: .userInitiated) {
        try Self.deletingSourceRangeCleaningAdjacentBlank(
          in: source,
          startLine: deletionRange.startLine,
          endLineExclusive: deletionRange.endLineExclusive
        )
      }.value
      let currentRenderedBlocks = selectedRenderedBlocks
      let allowDestructiveDelete = deletion.source.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
      try await deleteDocumentSourceRangeCleaningAdjacentBlank(
        file: source.file,
        startLine: deletionRange.startLine,
        endLineExclusive: deletionRange.endLineExclusive,
        allowDestructiveReplacement: allowDestructiveDelete
      )

      let updatedBlocks = await Task.detached(priority: .userInitiated) {
        Self.locallyDeletingRenderedBlocks(
          currentRenderedBlocks,
          startLine: deletion.startLine,
          endLineExclusive: deletion.endLineExclusive
        )
      }.value

      guard selectedEntrySource?.id == source.id else {
        await recordFileUndo(from: undoSnapshot)
        return true
      }

      await recordFileUndo(from: undoSnapshot)
      invalidateCanonicalDocumentCache(for: source.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      selectedEntrySource = deletion.source
      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: deletion.source)
      selectedRenderedBlocks = updatedVisibleBlocks
      let selectionLine: Int
      if case .heading = block.rendered {
        selectionLine = deletion.startLine
      } else {
        selectionLine = block.startLine
      }
      selectedBlockID = blockForSelectionLine(
        selectionLine,
        mode: .nextOrNearest,
        in: updatedVisibleBlocks
      )?.id
      statusText = "Deleted block in \(relativePath(source.file))"
      scheduleAgendaRefresh(preserveSelection: true)
      return true
    } catch {
      errorText = error.localizedDescription
      statusText = "Delete failed"
      return false
    }
  }

  func deleteRenderedTextSelection(_ fragments: [OrgSyntaxTextSelectionDocumentFragment]) async {
    await replaceRenderedTextSelection(fragments, replacementText: "")
  }

  @discardableResult
  func beginRenderedTextSelectionReplacement(
    _ fragments: [OrgSyntaxTextSelectionDocumentFragment],
    replacementText: String
  ) -> Bool {
    guard let preparation = prepareRenderedTextSelectionReplacement(
      fragments,
      replacementText: replacementText
    ) else {
      return false
    }
    Task { @MainActor [weak self] in
      await self?.finishRenderedTextSelectionWrite(preparation)
    }
    return true
  }

  func replaceRenderedTextSelection(
    _ fragments: [OrgSyntaxTextSelectionDocumentFragment],
    replacementText: String
  ) async {
    guard let preparation = prepareRenderedTextSelectionReplacement(
      fragments,
      replacementText: replacementText
    ) else {
      return
    }
    await finishRenderedTextSelectionWrite(preparation)
  }

  private func prepareRenderedTextSelectionReplacement(
    _ fragments: [OrgSyntaxTextSelectionDocumentFragment],
    replacementText: String
  ) -> RenderedTextSelectionPreparation? {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return nil
    }
    guard !fragments.isEmpty else {
      statusText = "No editable selection"
      return nil
    }

    isSavingBlock = true
    return RenderedTextSelectionPreparation(
      fragments: fragments.map(RenderedTextSelectionFragment.init),
      replacementText: replacementText,
      source: source,
      blocks: selectedRenderedBlocks,
      sourceRevision: entrySourceRenderIdentities[source.id]
    )
  }

  private func finishRenderedTextSelectionWrite(
    _ preparation: RenderedTextSelectionPreparation
  ) async {
    defer { isSavingBlock = false }
    let plan = await Task.detached(priority: .userInitiated) {
      let pairs = Self.renderedTextSelectionPairs(
        preparation.fragments,
        in: preparation.blocks
      )
      guard !pairs.isEmpty else {
        return RenderedTextSelectionPlanResult.failure("No editable selection")
      }
      do {
        let replacement = try Self.renderedTextSelectionReplacement(
          pairs: pairs,
          allBlocks: preparation.blocks,
          in: preparation.source,
          replacementText: preparation.replacementText
        )
        let renderedBlocks = replacement.updatedSource.text.isEmpty
          ? []
          : Self.sortEditableBlocksForDisplay(OrgEntryRenderer.parseEditable(
              replacement.updatedSource.text,
              baseLine: replacement.updatedSource.startLine
            ))
        return .success(RenderedTextSelectionWrite(
          file: preparation.source.file,
          startLine: replacement.startLine,
          endLineExclusive: replacement.endLineExclusive,
          replacement: replacement.replacement,
          expectedOriginal: replacement.expectedOriginal,
          allowDestructiveReplacement: replacement.coversWholeDocument
            && replacement.replacement.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty,
          failureStatus: preparation.replacementText.isEmpty
            ? "Delete selection failed"
            : "Replace selection failed",
          updatedSource: replacement.updatedSource,
          renderedBlocks: renderedBlocks,
          renderedBlocksMetadata: Self.renderedBlocksMetadata(for: renderedBlocks),
          caretSourceUTF16Offset: replacement.caretSourceUTF16Offset,
          undoSnapshot: Self.fileUndoSnapshotOffMain(for: preparation.source.file)
        ))
      } catch {
        return .failure(error.localizedDescription)
      }
    }.value

    guard case .success(let write) = plan else {
      if case .failure(let message) = plan {
        errorText = message == "No editable selection" ? nil : message
        statusText = message == "No editable selection"
          ? message
          : (preparation.replacementText.isEmpty
              ? "Delete selection failed"
              : "Replace selection failed")
      }
      return
    }
    guard selectedEntrySource?.id == preparation.source.id,
          entrySourceRenderIdentities[preparation.source.id] == preparation.sourceRevision
    else {
      statusText = "The selected file changed before the selection could be saved"
      return
    }

    do {
      try await replaceDocumentSourceRange(
        file: write.file,
        startLine: write.startLine,
        endLineExclusive: write.endLineExclusive,
        replacement: write.replacement,
        expectedOriginal: write.expectedOriginal,
        allowDestructiveReplacement: write.allowDestructiveReplacement
      )
      await recordFileUndo(from: write.undoSnapshot)
      guard selectedEntrySource?.id == preparation.source.id else { return }
      invalidateCanonicalDocumentCache(for: write.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      selectedEntrySource = write.updatedSource
      pendingBlockSelection = PendingBlockSelection(
        file: write.file,
        line: write.startLine,
        mode: .nextOrNearest,
        beginEditing: !preparation.replacementText.isEmpty,
        initialSourceUTF16Offset: write.caretSourceUTF16Offset
      )
      selectedBlockID = nil
      if write.updatedSource.text.isEmpty {
        selectedRenderedBlocks = []
        pendingBlockSelection = nil
      } else {
        applyRenderedBlocks(
          write.renderedBlocks,
          metadata: write.renderedBlocksMetadata,
          for: write.updatedSource
        )
      }
      isRenderingEntrySource = false
      statusText = preparation.replacementText.isEmpty
        ? "Deleted selection in \(relativePath(write.file))"
        : "Replaced selection in \(relativePath(write.file))"
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = write.failureStatus
    }
  }

  public func canMoveBlock(_ block: OrgEditableBlock, direction: OrgBlockMoveDirection) -> Bool {
    guard block.isEditable,
          let source = selectedEntrySource,
          source.isEditable,
          block.startLine >= source.startLine,
          block.endLineExclusive <= source.endLineExclusive
    else {
      return false
    }
    if source.isSubtree, block.startLine == source.startLine {
      return false
    }

    let blocks = movableBlocks
    guard let index = blocks.firstIndex(where: { $0.id == block.id }) else { return false }
    switch direction {
    case .up:
      return index > 0
    case .down:
      return index < blocks.count - 1
    }
  }

  public func moveBlock(_ block: OrgEditableBlock, direction: OrgBlockMoveDirection) async {
    guard let source = selectedEntrySource, source.isEditable else {
      statusText = "No editable source loaded"
      return
    }
    guard canMoveBlock(block, direction: direction),
          let target = moveTarget(for: block, direction: direction)
    else {
      statusText = "Block cannot move \(direction == .up ? "up" : "down")"
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    do {
      let undoSnapshot = await fileUndoSnapshot(for: source.file)
      let sourceSwap = try await Task.detached(priority: .userInitiated) {
        switch direction {
        case .up:
          return try Self.swappingSourceRanges(
            in: source,
            firstStartLine: target.startLine,
            firstEndLineExclusive: target.endLineExclusive,
            secondStartLine: block.startLine,
            secondEndLineExclusive: block.endLineExclusive
          )
        case .down:
          return try Self.swappingSourceRanges(
            in: source,
            firstStartLine: block.startLine,
            firstEndLineExclusive: block.endLineExclusive,
            secondStartLine: target.startLine,
            secondEndLineExclusive: target.endLineExclusive
          )
        }
      }.value
      switch direction {
      case .up:
        try await swapDocumentSourceRanges(
          file: source.file,
          firstStartLine: target.startLine,
          firstEndLineExclusive: target.endLineExclusive,
          secondStartLine: block.startLine,
          secondEndLineExclusive: block.endLineExclusive
        )
      case .down:
        try await swapDocumentSourceRanges(
          file: source.file,
          firstStartLine: block.startLine,
          firstEndLineExclusive: block.endLineExclusive,
          secondStartLine: target.startLine,
          secondEndLineExclusive: target.endLineExclusive
        )
      }
      let selectedLine: Int
      switch direction {
      case .up:
        selectedLine = target.startLine
      case .down:
        selectedLine = block.startLine + (target.endLineExclusive - target.startLine) + max(0, target.startLine - block.endLineExclusive)
      }
      let currentRenderedBlocks = selectedRenderedBlocks
      let updatedBlocks = await Task.detached(priority: .userInitiated) {
        Self.locallyMovingRenderedBlocks(
          currentRenderedBlocks,
          firstStartLine: direction == .up ? target.startLine : block.startLine,
          firstEndLineExclusive: direction == .up ? target.endLineExclusive : block.endLineExclusive,
          secondStartLine: direction == .up ? block.startLine : target.startLine,
          secondEndLineExclusive: direction == .up ? block.endLineExclusive : target.endLineExclusive
        )
      }.value

      guard selectedEntrySource?.id == source.id else {
        await recordFileUndo(from: undoSnapshot)
        return
      }

      await recordFileUndo(from: undoSnapshot)
      invalidateCanonicalDocumentCache(for: source.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      selectedEntrySource = sourceSwap
      let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: sourceSwap)
      selectedRenderedBlocks = updatedVisibleBlocks
      selectedBlockID = blockForSelectionLine(
        selectedLine,
        mode: .containingOrNearest,
        in: updatedVisibleBlocks
      )?.id
      statusText = "Moved block \(direction == .up ? "up" : "down")"
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Move failed"
    }
  }

  public func sourceBlockRunState(for block: OrgEditableBlock) -> SourceBlockRunState? {
    sourceBlockRuns[sourceBlockRunKey(for: block)]
  }

  public func runSourceBlock(_ block: OrgEditableBlock, rawText: String? = nil) async {
    guard let selectedEntrySource else {
      statusText = "No source loaded"
      return
    }
    guard case .source(let fallbackLanguage, let fallbackLines) = block.rendered else {
      statusText = "Select a source block first"
      return
    }

    let source = OrgEditableSourceBlock(
      rawText: rawText ?? block.rawText,
      fallbackLanguage: fallbackLanguage,
      fallbackLines: fallbackLines
    )
    let language = source.language.trimmingCharacters(in: .whitespacesAndNewlines)
    let key = sourceBlockRunKey(for: block)
    guard let plan = SourceBlockRunPlan.plan(for: language) else {
      sourceBlockRuns[key] = SourceBlockRunState(
        status: .unsupported,
        language: language.isEmpty ? "source" : language,
        commandLabel: "",
        message: language.isEmpty
          ? "Add a supported source language to run this block."
          : "Running \(language) blocks is not supported yet."
      )
      return
    }

    let startedAt = Date()
    sourceBlockRuns[key] = SourceBlockRunState(
      status: .running,
      language: language,
      commandLabel: plan.commandLabel,
      startedAt: startedAt,
      message: "Running..."
    )

    let workingDirectory = URL(fileURLWithPath: selectedEntrySource.file)
      .deletingLastPathComponent()
      .standardizedFileURL

    do {
      let result = try await Task.detached(priority: .userInitiated) {
        try Self.executeSourceBlock(source, plan: plan, workingDirectory: workingDirectory)
      }.value
      guard self.sourceBlockRunKey(for: block) == key else { return }
      let finishedAt = Date()
      let status: SourceBlockRunStatus
      if result.timedOut {
        status = .timedOut
      } else if result.exitCode == 0 {
        status = .succeeded
      } else {
        status = .failed
      }
      sourceBlockRuns[key] = SourceBlockRunState(
        status: status,
        language: language,
        commandLabel: plan.commandLabel,
        startedAt: startedAt,
        finishedAt: finishedAt,
        duration: finishedAt.timeIntervalSince(startedAt),
        exitCode: result.exitCode,
        stdout: result.stdout,
        stderr: result.stderr,
        message: result.timedOut ? "Timed out after \(Int(result.timeout))s" : nil
      )
    } catch {
      sourceBlockRuns[key] = SourceBlockRunState(
        status: .failed,
        language: language,
        commandLabel: plan.commandLabel,
        startedAt: startedAt,
        finishedAt: Date(),
        stderr: error.localizedDescription,
        message: "Run failed"
      )
    }
  }

  public func refreshAIChatThreadRecords(showsLoading: Bool = true) async {
    guard !isRefreshingAIChatThreadRecords else { return }

    guard let corpusRoot else {
      aiChatThreadRecords = []
      return
    }

    let sessionGeneration = corpusSessionGeneration
    let dirtyGeneration = workspaceSurfaceDirtyGenerations[.aiChat, default: 0]
    isRefreshingAIChatThreadRecords = true
    let shouldShowLoading = showsLoading || aiChatThreadRecords.isEmpty
    if shouldShowLoading {
      isLoadingAIChatThreadRecords = true
    }
    defer {
      if isCurrentCorpusSession(root: corpusRoot, generation: sessionGeneration) {
        isRefreshingAIChatThreadRecords = false
        if shouldShowLoading { isLoadingAIChatThreadRecords = false }
      }
    }

    do {
      let threads = try await Task.detached(priority: .utility) {
        try Self.scanAIChatThreadRecords(corpusRoot: corpusRoot)
      }.value
      guard !Task.isCancelled, isCurrentCorpusSession(root: corpusRoot, generation: sessionGeneration) else { return }
      aiChatThreadRecords = threads
      syncAIChatSelectionAfterRefresh()
      markWorkspaceSurfaceCleanIfUnchanged(.aiChat, generation: dirtyGeneration)
    } catch {
      guard !Task.isCancelled, isCurrentCorpusSession(root: corpusRoot, generation: sessionGeneration) else { return }
      errorText = error.localizedDescription
      statusText = "Agent records scan failed"
    }
  }

  public func refreshAssignedWork(showsLoading: Bool = true) async {
    guard !isRefreshingAssignedWork else { return }

    guard let corpusRoot,
          let corpusContext = captureDocumentCorpusContext()
    else {
      assignedWorkItems = []
      return
    }

    assignedWorkRefreshRequestGeneration &+= 1
    let requestGeneration = assignedWorkRefreshRequestGeneration
    let requestID = UUID()
    activeAssignedWorkRefreshRequestID = requestID
    hasAttemptedAssignedWorkLoad = true
    let dirtyGeneration = workspaceSurfaceDirtyGenerations[.agenda, default: 0]
    isRefreshingAssignedWork = true
    let shouldShowLoading = showsLoading || assignedWorkItems.isEmpty
    if shouldShowLoading {
      isLoadingAssignedWork = true
    }
    defer {
      if activeAssignedWorkRefreshRequestID == requestID {
        activeAssignedWorkRefreshRequestID = nil
        isRefreshingAssignedWork = false
        if shouldShowLoading {
          isLoadingAssignedWork = false
        }
      }
    }

    for attempt in 0..<2 {
      let filesGeneration = corpusFilesGeneration
      let eventSerial = corpusFileEventSerial
      let files = corpusFiles
      let request = AssignedWorkRefreshContext(
        requestID: requestID,
        requestGeneration: requestGeneration,
        corpus: corpusContext,
        corpusFilesGeneration: filesGeneration,
        corpusFileEventSerial: eventSerial,
        dirtyGeneration: dirtyGeneration
      )
      let laneSnapshot = await documentMutationLane.rootMutationSnapshot(
        rootPath: corpusContext.mutationRootPath
      )

      do {
        let preparation = assignedWorkScanPreparationForTesting
        let cache = workspaceTodoScanCache
        let items = try await Task.detached(priority: .utility) {
          await preparation?()
          let scanFiles = files.isEmpty
            ? try Self.scanCorpusFiles(corpusRoot: corpusRoot)
            : files
          let headings = try await cache.scan(files: scanFiles)
          return Self.assignedWorkItems(headings: headings)
        }.value
        guard isCurrentAssignedWorkRefresh(request) else { return }
        let laneIsCurrent = await documentMutationLane.isCurrentAndQuiescent(laneSnapshot)
        guard corpusFilesGeneration == request.corpusFilesGeneration,
              corpusFileEventSerial == request.corpusFileEventSerial,
              laneIsCurrent
        else {
          if attempt == 0 {
            await Task.yield()
            continue
          }
          markWorkspaceSurfacesDirty([.agenda], refreshVisible: false)
          return
        }

        assignedWorkItems = items
        if let selectedAssignedWorkItemID,
           let item = items.first(where: { $0.id == selectedAssignedWorkItemID }) {
          if case .assigned = selectedLocation {
            selectedLocation = .assigned(item)
          }
        } else if selectedAssignedWorkItemID != nil {
          self.selectedAssignedWorkItemID = nil
          if case .assigned = selectedLocation {
            selectedLocation = nil
            backlinks = nil
          }
        }
        if selectedSurface == .agenda, agendaMode == .assigned {
          statusText = "\(items.count) all-time item\(items.count == 1 ? "" : "s")"
        }
        markWorkspaceSurfaceCleanIfUnchanged(.agenda, generation: request.dirtyGeneration)
        return
      } catch {
        guard isCurrentAssignedWorkRefresh(request) else { return }
        errorText = error.localizedDescription
        statusText = "Assigned work scan failed"
        return
      }
    }
  }

  public func refreshAssignedWorkIfNeeded() async {
    guard !hasAttemptedAssignedWorkLoad else { return }
    await refreshAssignedWork(showsLoading: false)
  }

  private func rebuildAssignedWorkDisplayCache() {
    let terms = Self.filterTerms(from: agendaFilter)
    visibleAssignedWorkItems = assignedWorkSearchRows.compactMap { row in
      guard Self.matchesAssignedWorkStructuredFilters(
        row.item,
        assignee: agendaAssigneeFilter,
        status: agendaStatusFilter,
        priority: agendaPriorityFilter,
        topic: agendaTopicFilter
      ) else { return nil }
      guard !terms.isEmpty else { return row.item }
      return terms.allSatisfy { row.searchText.contains($0) } ? row.item : nil
    }
    assignedWorkSections = Self.groupAssignedWorkSections(visibleAssignedWorkItems)
  }

  nonisolated private static func matchesAssignedWorkStructuredFilters(
    _ item: AssignedWorkItem,
    assignee: String,
    status: String,
    priority: String,
    topic: String
  ) -> Bool {
    let normalizedAssignee = item.assignee.trimmingCharacters(in: .whitespacesAndNewlines)
    if assignee == agendaUnassignedFilter {
      guard normalizedAssignee.isEmpty else { return false }
    } else if !assignee.isEmpty,
              normalizedAssignee.caseInsensitiveCompare(assignee) != .orderedSame {
      return false
    }

    let todo = item.todo?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let propertyStatus = propertyValue("STATUS", in: item.properties) ?? item.status
    if status == agendaOpenStatusFilter {
      let normalizedTodo = todo.uppercased()
      guard !["DONE", "CANCELED", "CANCELLED"].contains(normalizedTodo) else { return false }
    } else if status == agendaCompletedStatusFilter {
      let normalizedTodo = todo.uppercased()
      guard ["DONE", "CANCELED", "CANCELLED"].contains(normalizedTodo) else { return false }
    } else if !status.isEmpty,
              todo.caseInsensitiveCompare(status) != .orderedSame,
              propertyStatus.caseInsensitiveCompare(status) != .orderedSame {
      return false
    }

    let itemPriority = propertyValue("PRIORITY", in: item.properties) ?? ""
    if priority == agendaNoPriorityFilter {
      guard itemPriority.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
    } else if !priority.isEmpty,
              itemPriority.caseInsensitiveCompare(priority) != .orderedSame {
      return false
    }

    if !topic.isEmpty,
       !item.tags.contains(where: { $0.caseInsensitiveCompare(topic) == .orderedSame }) {
      return false
    }
    return true
  }

  private static func groupAssignedWorkSections(_ items: [AssignedWorkItem]) -> [AssignedWorkSection] {
    let grouped = Dictionary(grouping: items) { item in
      "\(item.assignee)|\(Self.assignedWorkTodoGroupLabel(for: item))"
    }
    return grouped.keys.sorted { lhs, rhs in
      let left = lhs.split(separator: "|", maxSplits: 1).map(String.init)
      let right = rhs.split(separator: "|", maxSplits: 1).map(String.init)
      if left.first == right.first {
        return (left.dropFirst().first ?? "") < (right.dropFirst().first ?? "")
      }
      return (left.first ?? "") < (right.first ?? "")
    }.map { key in
      let parts = key.split(separator: "|", maxSplits: 1).map(String.init)
      let assignee = parts.first ?? "unassigned"
      let todo = parts.dropFirst().first ?? "TASK"
      let items = (grouped[key] ?? []).sorted {
        if $0.assignedAt == $1.assignedAt {
          return $0.headline < $1.headline
        }
        return ($0.assignedAt ?? "") > ($1.assignedAt ?? "")
      }
      return AssignedWorkSection(
        id: key,
        label: "\(assignee) / \(todo)",
        items: items
      )
    }
  }

  private static func assignedWorkTodoGroupLabel(for item: AssignedWorkItem) -> String {
    let todo = item.todo?
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .uppercased()
    return todo?.isEmpty == false ? todo! : "TASK"
  }

  private static func assignedWorkFilterText(for item: AssignedWorkItem) -> String {
    [
      item.todo,
      item.headline,
      item.assignee,
      item.status,
      item.assignedAt,
      item.lastAgentUpdate,
      item.file,
      item.tags.joined(separator: " "),
      item.properties.map { "\($0.key) \($0.value)" }.joined(separator: " ")
    ].compactMap { $0 }.joined(separator: " ").lowercased()
  }

  public func selectAssignedWorkItem(_ item: AssignedWorkItem) {
    deactivateAgendaFilterFocus()
    select(.assigned(item), surface: .agenda)
  }

  public func selectAIChatThreadRecord(_ thread: AIChatThreadRecord) {
    openAIChatThreadRecord(thread, surface: .files)
  }

  private func openAIChatThreadRecord(_ thread: AIChatThreadRecord, surface: WorkspaceSurface? = nil, mode: EntrySourceMode? = nil) {
    activateDetailLocation(.aiChatThreadRecord(thread), mode: mode, surface: surface, recordsHistory: true)
  }

  public func selectCorpusFile(_ file: CorpusFile, surface: WorkspaceSurface = .files) {
    let thread = AIChatThreadRecord(
      title: file.name,
      file: file.path,
      line: 1,
      zone: file.directory.isEmpty ? "corpus" : file.directory,
      modifiedAt: file.modifiedAt,
      idValue: nil
    )
    activateDetailLocation(.aiChatThreadRecord(thread), mode: .page, surface: surface, recordsHistory: true)
    if selectedCorpusFileID != file.id {
      selectedCorpusFileID = file.id
    }
    if selectedAIChatThreadRecordID != nil {
      selectedAIChatThreadRecordID = nil
    }
    statusText = "Opened \(file.relativePath)"
  }

  func activateSelectedCorpusFileFromList(_ file: CorpusFile) {
    guard selectedSurface == .files,
          !isWorkspaceSurfacePaneClosed,
          selectedCorpusFileID == file.id
    else { return }
    selectCorpusFile(file)
  }

  public func handleCorpusFileClick(
    _ file: CorpusFile,
    modifiers: NSEvent.ModifierFlags = []
  ) {
    selectedCorpusFileIDsForAIContext = Self.updatedAIContextSelection(
      selectedCorpusFileIDsForAIContext,
      activeID: selectedCorpusFileID,
      clickedID: file.id,
      visibleIDs: filteredCorpusFiles.map(\.id),
      modifiers: modifiers
    )
    if selectedCorpusFileID == file.id {
      pendingNavigationSource = "file_list"
      selectCorpusFile(file)
    } else {
      selectedCorpusFileID = file.id
    }
  }

  public func isCorpusFileSelectedForAIContext(_ file: CorpusFile) -> Bool {
    selectedCorpusFileIDsForAIContext.isEmpty
      ? selectedCorpusFileID == file.id
      : selectedCorpusFileIDsForAIContext.contains(file.id)
  }

  public func reconcileCorpusFileAIContextSelection(visibleIDs: [CorpusFile.ID]) {
    let reconciled = selectedCorpusFileIDsForAIContext.intersection(visibleIDs)
    if reconciled != selectedCorpusFileIDsForAIContext {
      selectedCorpusFileIDsForAIContext = reconciled
    }
  }

  func selectAllVisibleCorpusFilesForAIContext() {
    let visibleIDs = filteredCorpusFiles.map(\.id)
    selectedCorpusFileIDsForAIContext = Set(visibleIDs)
    statusText = Self.listSelectionStatus(count: visibleIDs.count, singular: "file")
  }

  func clearCorpusFileAIContextSelection() {
    guard !selectedCorpusFileIDsForAIContext.isEmpty else { return }
    selectedCorpusFileIDsForAIContext = []
    statusText = "File selection cleared"
  }

  func extendCorpusFileAIContextSelection(by delta: Int) {
    let files = filteredCorpusFiles
    let result = Self.extendedKeyboardSelection(
      selectedCorpusFileIDsForAIContext,
      activeID: selectedCorpusFileID,
      visibleIDs: files.map(\.id),
      delta: delta
    )
    guard let targetID = result.targetID,
          let target = files.first(where: { $0.id == targetID })
    else {
      statusText = "No visible files"
      return
    }
    selectedCorpusFileIDsForAIContext = result.selection
    selectCorpusFile(target)
    statusText = Self.listSelectionStatus(count: result.selection.count, singular: "file")
  }

  public func openSidebarFile(_ file: CorpusFile) {
    let keepsVisibleChatPane =
      !isWorkspaceSurfacePaneClosed
      && (selectedSurface == .home || selectedSurface == .aiChat)
    let surface = keepsVisibleChatPane ? selectedSurface : .files

    pendingNavigationSource = "sidebar"
    selectCorpusFile(file, surface: surface)
    expandedWorkspaceSurface = nil
    isWorkspaceSurfacePaneClosed = !keepsVisibleChatPane
    isWorkspaceDetailPaneClosed = false
    isWorkspaceDetailPaneExpanded = false
    isAIChatAssistantPresented = false
  }

  public func isFilePinned(path: String) -> Bool {
    guard let relativePath = pinnedFileRelativePath(for: path) else { return false }
    return pinnedFileRelativePaths.contains(relativePath)
  }

  public func togglePinnedFile(_ file: CorpusFile) {
    togglePinnedFile(path: file.path)
  }

  public func togglePinnedFile(path: String) {
    guard let relativePath = pinnedFileRelativePath(for: path) else {
      statusText = "Only files inside the current corpus can be pinned"
      return
    }
    if let index = pinnedFileRelativePaths.firstIndex(of: relativePath) {
      pinnedFileRelativePaths.remove(at: index)
      statusText = "Unpinned \(relativePath)"
    } else {
      pinnedFileRelativePaths.append(relativePath)
      statusText = "Pinned \(relativePath)"
    }
    persistPinnedFiles()
    schedulePinnedCorpusFileProjection()
  }

  private func pinnedFileRelativePath(for path: String) -> String? {
    guard let corpusRoot else { return nil }
    let rootPath = corpusRoot.standardizedFileURL.path
    let filePath = URL(fileURLWithPath: path).standardizedFileURL.path
    let prefix = rootPath.hasSuffix("/") ? rootPath : rootPath + "/"
    guard filePath.hasPrefix(prefix) else { return nil }
    return String(filePath.dropFirst(prefix.count))
  }

  private func restorePinnedFiles(for corpusRoot: URL) {
    let storage = defaults.dictionary(forKey: pinnedFilesByCorpusKey) ?? [:]
    pinnedFileRelativePaths = storage[corpusRoot.standardizedFileURL.path] as? [String] ?? []
    schedulePinnedCorpusFileProjection()
  }

  private func persistPinnedFiles() {
    guard let corpusRoot else { return }
    var storage = defaults.dictionary(forKey: pinnedFilesByCorpusKey) ?? [:]
    let key = corpusRoot.standardizedFileURL.path
    if pinnedFileRelativePaths.isEmpty {
      storage.removeValue(forKey: key)
    } else {
      storage[key] = pinnedFileRelativePaths
    }
    defaults.set(storage, forKey: pinnedFilesByCorpusKey)
  }

  private func restoreAutomaticDailyNoteCreationPreference(for corpusRoot: URL) -> Bool {
    let storage = defaults.dictionary(forKey: automaticDailyNoteCreationDisabledByCorpusKey) ?? [:]
    return storage[corpusRoot.standardizedFileURL.path] as? Bool ?? false
  }

  private func persistAutomaticDailyNoteCreationPreference(for corpusRoot: URL) {
    var storage = defaults.dictionary(forKey: automaticDailyNoteCreationDisabledByCorpusKey) ?? [:]
    let key = corpusRoot.standardizedFileURL.path
    if automaticDailyNoteCreationDisabled {
      storage[key] = true
    } else {
      storage.removeValue(forKey: key)
    }
    defaults.set(storage, forKey: automaticDailyNoteCreationDisabledByCorpusKey)
  }

  private func reconcilePinnedFiles(for corpusRoot: URL) async {
    guard self.corpusRoot?.path == corpusRoot.path else { return }
    schedulePinnedCorpusFileProjection()
    await pinnedCorpusFileProjectionTask?.value
  }

  // MARK: Navigation attribution, frecency, and the local usage log

  private func noteChatTurnTransitions(from previous: Set<UUID>, to current: Set<UUID>) {
    guard previous != current else { return }
    let now = CFAbsoluteTimeGetCurrent()
    for threadID in current.subtracting(previous) {
      chatTurnStartTimes[threadID] = now
      guard usageLog.isEnabled else { continue }
      let thread = aiChatThreads.first(where: { $0.id == threadID })
      usageLog.record(.chatTurnStart, [
        "runtime": .string(thread?.runtime.rawValue ?? "unknown"),
        "heading_thread": .bool(thread?.resource != nil),
      ])
    }
    for threadID in previous.subtracting(current) {
      let started = chatTurnStartTimes.removeValue(forKey: threadID)
      guard usageLog.isEnabled else { continue }
      var fields: [String: OpenOrgUsageValue] = [:]
      if let started { fields["seconds"] = .double(now - started) }
      usageLog.record(.chatTurnFinish, fields)
    }
  }

  /// Tags the next document activation with how it was reached so the local
  /// usage log can tell Quick Open from links, sidebar, history, and so on.
  func setPendingNavigationSource(_ source: String) {
    pendingNavigationSource = source
  }

  private func noteDocumentNavigation(to location: WorkspaceLocation, recordsHistory: Bool) {
    let source = pendingNavigationSource ?? (recordsHistory ? "other" : "restore")
    pendingNavigationSource = nil
    let path = URL(fileURLWithPath: location.file).standardizedFileURL.path
    let previousPath = selectedLocation.map { URL(fileURLWithPath: $0.file).standardizedFileURL.path }
    let relative = corpusFilesByPath[path]?.relativePath ?? pinnedFileRelativePath(for: path)
    if let relative, source != "tab_switch", source != "restore", previousPath != path {
      recordFileVisit(relativePath: relative)
    }
    guard usageLog.isEnabled else { return }
    var fields: [String: OpenOrgUsageValue] = [
      "source": .string(source),
      "ext": .string(URL(fileURLWithPath: path).pathExtension.lowercased()),
      "same_file": .bool(previousPath == path),
      "in_corpus": .bool(relative != nil),
    ]
    if let relative { fields["file"] = usageLog.pathToken(relative) }
    usageLog.record(.documentOpen, fields)
    pendingDocumentReadyMeasurement = previousPath == path
      ? nil
      : (path: path, startedAt: CFAbsoluteTimeGetCurrent(), source: source)
  }

  private func noteDocumentReady(for location: WorkspaceLocation, cached: Bool) {
    guard let pending = pendingDocumentReadyMeasurement else { return }
    let path = URL(fileURLWithPath: location.file).standardizedFileURL.path
    guard pending.path == path else { return }
    pendingDocumentReadyMeasurement = nil
    let milliseconds = (CFAbsoluteTimeGetCurrent() - pending.startedAt) * 1000
    usageLog.record(.documentReady, [
      "source": .string(pending.source),
      "ms": .double(milliseconds),
      "cached": .bool(cached),
    ])
  }

  private func currentFileFrecency() -> WorkspaceFileFrecency {
    guard let corpusRoot else { return WorkspaceFileFrecency() }
    let root = corpusRoot.standardizedFileURL.path
    if let cache = fileFrecencyCache, cache.root == root { return cache.value }
    let storage = defaults.dictionary(forKey: fileFrecencyByCorpusKey) ?? [:]
    let value = (storage[root] as? Data)
      .flatMap { try? JSONDecoder().decode(WorkspaceFileFrecency.self, from: $0) }
      ?? WorkspaceFileFrecency()
    fileFrecencyCache = (root, value)
    return value
  }

  func recordFileVisit(relativePath: String, at date: Date = Date()) {
    guard let corpusRoot else { return }
    let root = corpusRoot.standardizedFileURL.path
    var value = currentFileFrecency()
    value.recordVisit(relativePath, at: date)
    fileFrecencyCache = (root, value)
    fileFrecencyRevision &+= 1
    var storage = defaults.dictionary(forKey: fileFrecencyByCorpusKey) ?? [:]
    storage[root] = try? JSONEncoder().encode(value)
    defaults.set(storage, forKey: fileFrecencyByCorpusKey)
  }

  public func fileFrecencyScore(relativePath: String, now: Date = Date()) -> Double {
    currentFileFrecency().score(relativePath, now: now)
  }

  /// Recently and frequently opened corpus files, best first. Missing files are skipped.
  public func recentCorpusFiles(limit: Int = 12, now: Date = Date()) -> [CorpusFile] {
    _ = fileFrecencyRevision
    guard limit > 0 else { return [] }
    let byRelativePath = Dictionary(
      corpusFiles.map { ($0.relativePath, $0) },
      uniquingKeysWith: { first, _ in first }
    )
    var result: [CorpusFile] = []
    for entry in currentFileFrecency().ranked(now: now) {
      guard let file = byRelativePath[entry.path] else { continue }
      result.append(file)
      if result.count == limit { break }
    }
    return result
  }

  public func fileFrecencyScores(now: Date = Date()) -> [String: Double] {
    _ = fileFrecencyRevision
    return currentFileFrecency().scores(now: now)
  }

  private func rankedRecentFileCount() -> Int {
    currentFileFrecency().ranked(now: Date()).count
  }

  public func isRecentCorpusFile(_ file: CorpusFile) -> Bool {
    _ = fileFrecencyRevision
    return fileFrecencyScore(relativePath: file.relativePath) > 0
  }

  public func presentQuickOpen() {
    guard corpusRoot != nil else {
      statusText = "No corpus selected"
      return
    }
    quickOpenQuery = ""
    resetQuickOpenSelection()
    isQuickOpenPresented = true
    usageLog.record(.quickOpenPresent, ["recent_count": .int(rankedRecentFileCount())])
    if corpusFiles.isEmpty {
      Task { await refreshCorpusFiles() }
    }
  }

  public func presentKeyboardShortcuts() {
    isKeyboardShortcutsPresented = true
  }

  public func focusSearchSurface() {
    makeSurfacePrimary(.search)
    searchFocusToken += 1
  }

  public func presentAIChatThreadFind() {
    guard selectedSurface == .home || selectedSurface == .aiChat else { return }
    aiChatFindRequestGeneration &+= 1
  }

  @discardableResult
  public func focusCurrentSearchField() -> Bool {
    let detailIsSearchTarget = hasWorkspaceDetailContent
      && !isWorkspaceDetailPaneClosed
      && (isWorkspaceSurfacePaneClosed || activeWorkspacePane == .detail)
    if detailIsSearchTarget, focusPageSearch() {
      return true
    }

    switch selectedSurface {
    case .agenda:
      focusAgendaFilter(clearsFilter: false)
    case .approvals:
      focusRunsAndReviewFilter()
    case .files, .canvases:
      focusCorpusFileFilter()
    case .home, .aiChat:
      presentAIChatThreadFind()
    case .savedViews, .meetings, .sources, .externalThreads, .skills, .activity:
      return focusPageSearch()
    case .search:
      if selectedLocation != nil {
        return focusPageSearch()
      }
      focusSearchSurface()
    }
    return true
  }

  public func selectSearchNode(_ node: OrgRoamNodeReference) {
    let thread = AIChatThreadRecord(
      title: node.title,
      file: node.file,
      line: node.line,
      zone: "node",
      modifiedAt: nil,
      idValue: node.idValue
    )
    pendingNavigationSource = "search"
    activateDetailLocation(.aiChatThreadRecord(thread), mode: .entry, surface: .search, recordsHistory: true)
    selectedAIChatThreadRecordID = nil
    statusText = "Opened \(relativePath(node.file)):\(node.line)"
  }

  public func selectSearchFile(_ file: CorpusFile) {
    selectedCorpusFileID = file.id
    let thread = AIChatThreadRecord(
      title: file.name,
      file: file.path,
      line: 1,
      zone: file.directory.isEmpty ? "corpus" : file.directory,
      modifiedAt: file.modifiedAt,
      idValue: nil
    )
    pendingNavigationSource = "search"
    activateDetailLocation(.aiChatThreadRecord(thread), mode: .page, surface: .search, recordsHistory: true)
    selectedAIChatThreadRecordID = nil
    statusText = "Opened \(file.relativePath)"
  }

  public func selectAgentWorkSearchResult(_ result: WorkspaceAgentWorkSearchResult) {
    switch result.kind {
    case .approval:
      if let runID = result.parentRunID,
         let run = agentRunsByID[runID] {
        runsAndReviewPage = .runs
        selectAgentRun(run)
        statusText = "Opened \(result.title) in its run"
      } else if let approval = approvalItems.first(where: { $0.id == result.recordID }) {
        runsAndReviewPage = .review
        selectApprovalItem(approval)
      }
    case .run:
      guard let run = agentRunsByID[result.recordID] else { return }
      runsAndReviewPage = .runs
      selectAgentRun(run)
    case .workflow:
      guard let workflow = agentWorkflows.first(where: { $0.id == result.recordID }) else { return }
      runsAndReviewPage = .workflows
      selectAgentWorkflow(workflow)
    case .goal:
      guard let goal = agentGoals.first(where: { $0.id == result.recordID }) else { return }
      runsAndReviewPage = .goals
      selectAgentGoal(goal)
    case .agent:
      guard let profile = agentProfiles.first(where: { $0.id == result.recordID }) else { return }
      runsAndReviewPage = .agents
      selectAgentProfile(profile)
    }
  }

  private func rebuildWorkspaceTextSearchDisplayCache() {
    let categorizedItems: [WorkspaceTextSearchItem] =
      searchResults.filter(\.isActiveTodo).map(WorkspaceTextSearchItem.activeTodo)
      + workspaceFileSearchResults.map(WorkspaceTextSearchItem.file)
      + aiChatSearchResults
        .filter { $0.matchKind == .threadTitle }
        .map(WorkspaceTextSearchItem.chatThread)
      + workspaceAgentWorkSearchResults.map(WorkspaceTextSearchItem.agentWork)
      + workspacePageSearchResults.map(WorkspaceTextSearchItem.page)
      + searchResults
        .filter { !$0.isActiveTodo && $0.heading?.isEmpty == false }
        .map(WorkspaceTextSearchItem.entry)
      + aiChatSearchResults
        .filter { $0.matchKind == .messageText }
        .map(WorkspaceTextSearchItem.chatMessage)
      + searchResults
        .filter { !$0.isActiveTodo && $0.heading?.isEmpty != false }
        .map(WorkspaceTextSearchItem.corpusText)

    let grouped = Dictionary(grouping: categorizedItems, by: \.category)
    workspaceTextSearchSections = WorkspaceTextSearchCategory.allCases.compactMap { category in
      guard let items = grouped[category], !items.isEmpty else { return nil }
      return WorkspaceTextSearchSection(category: category, items: items)
    }
    corpusSearchResultGroups = Self.groupedSearchResultsForDisplay(searchResults)
  }

  public var workspaceTextSearchResultCount: Int {
    workspaceTextSearchSections.reduce(0) { $0 + $1.items.count }
  }

  nonisolated static func searchAgentWorkForWorkspace(
    runs: [AgentRunItem],
    approvals: [ApprovalItem],
    workflows: [AgentWorkflowItem],
    goals: [AgentGoalItem],
    profiles: [AgentProfileItem],
    query rawQuery: String,
    limitPerCategory: Int
  ) -> [WorkspaceAgentWorkSearchResult] {
    let terms = rawQuery
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()
      .split(whereSeparator: \.isWhitespace)
      .map(String.init)
    guard !terms.isEmpty, limitPerCategory > 0 else { return [] }

    func matches(_ values: [String?]) -> Bool {
      let text = values.compactMap { $0 }.joined(separator: "\n").lowercased()
      return terms.allSatisfy(text.contains)
    }

    func fileLabel(_ path: String) -> String {
      URL(fileURLWithPath: path).lastPathComponent
    }

    var approvalResults: [WorkspaceAgentWorkSearchResult] = []
    var runResults: [WorkspaceAgentWorkSearchResult] = []
    var workflowResults: [WorkspaceAgentWorkSearchResult] = []
    var goalResults: [WorkspaceAgentWorkSearchResult] = []
    var profileResults: [WorkspaceAgentWorkSearchResult] = []
    var indexedRunApprovalKeys = Set<String>()

    for run in runs {
      let matchingApprovals = run.approvals
        .filter { approval in
          matches([
            approval.id,
            approval.fingerprint,
            approval.title,
            approval.action,
            approval.riskClass,
            approval.status,
            approval.requestedRole,
            approval.requestedFrom,
            approval.decidedBy,
            approval.decisionNote,
            approval.note,
            approval.receipt,
            run.id,
            run.goal,
            run.agentRef,
            run.goalRef,
            run.workflowId,
          ])
        }
        .sorted { lhs, rhs in
          (lhs.decidedAt ?? lhs.requestedAt) > (rhs.decidedAt ?? rhs.requestedAt)
        }

      for approval in matchingApprovals where approvalResults.count < limitPerCategory {
        indexedRunApprovalKeys.insert("\(run.id):\(approval.id)")
        let detail = approval.decisionNote?.nilIfBlank
          ?? approval.note?.nilIfBlank
          ?? approval.action
        approvalResults.append(WorkspaceAgentWorkSearchResult(
          id: "run-approval:\(run.id):\(approval.id)",
          kind: .approval,
          recordID: approval.id,
          parentRunID: run.id,
          title: approval.title,
          snippet: "\(run.goal) · \(detail)",
          status: approval.status,
          sourceReference: "Run \(run.id.prefix(8))"
        ))
      }

      if matchingApprovals.isEmpty,
         runResults.count < limitPerCategory,
         run.matchesRunFilter(rawQuery) {
        runResults.append(WorkspaceAgentWorkSearchResult(
          id: "run:\(run.id)",
          kind: .run,
          recordID: run.id,
          title: run.goal,
          snippet: run.outcome?.summary.nilIfBlank
            ?? run.blockedReason?.nilIfBlank
            ?? run.progressText,
          status: run.status,
          sourceReference: "Run \(run.id.prefix(8))"
        ))
      }
    }

    for approval in approvals where approvalResults.count < limitPerCategory {
      if let runID = approval.runId,
         let approvalID = approval.approvalId,
         indexedRunApprovalKeys.contains("\(runID):\(approvalID)") {
        continue
      }
      let propertyText = approval.properties
        .sorted { $0.key < $1.key }
        .flatMap { [$0.key, $0.value] }
      guard matches([
        approval.idValue,
        approval.approvalId,
        approval.title,
        approval.status,
        approval.todo,
        approval.file,
        approval.body,
        approval.action,
        approval.riskClass,
        approval.requestedRole,
        approval.requestedFrom,
        approval.runId,
        approval.runGoal,
      ] + approval.tags.map(Optional.some) + propertyText.map(Optional.some)) else { continue }
      approvalResults.append(WorkspaceAgentWorkSearchResult(
        id: "approval:\(approval.id)",
        kind: .approval,
        recordID: approval.id,
        parentRunID: approval.runId,
        title: approval.title,
        snippet: approval.runGoal?.nilIfBlank ?? approval.body,
        status: approval.status,
        sourceReference: approval.runId.map { "Run \($0.prefix(8))" }
          ?? "\(fileLabel(approval.file)):\(max(1, approval.line))"
      ))
    }

    for workflow in workflows where workflowResults.count < limitPerCategory {
      let inputs = workflow.inputs.flatMap { [$0.id, $0.description, $0.default ?? ""] }
      let triggers = workflow.triggers.flatMap {
        [$0.id, $0.type, $0.schedule ?? "", $0.timezone ?? ""]
      }
      guard matches([
        workflow.id,
        workflow.version,
        workflow.title,
        workflow.description,
        workflow.state,
        workflow.instructions,
        workflow.riskClass,
        workflow.file,
        workflow.agentRef,
        workflow.goalRef,
      ] + workflow.capabilities.map(Optional.some)
        + inputs.map(Optional.some)
        + triggers.map(Optional.some)) else { continue }
      workflowResults.append(WorkspaceAgentWorkSearchResult(
        id: "workflow:\(workflow.id)",
        kind: .workflow,
        recordID: workflow.id,
        title: workflow.title,
        snippet: workflow.description,
        status: workflow.state,
        sourceReference: fileLabel(workflow.file)
      ))
    }

    for goal in goals where goalResults.count < limitPerCategory {
      guard matches([
        goal.id,
        goal.title,
        goal.description,
        goal.status,
        goal.parentGoalRef,
        goal.ownerAgentRef,
        goal.file,
      ] + goal.measures.map(Optional.some)) else { continue }
      goalResults.append(WorkspaceAgentWorkSearchResult(
        id: "goal:\(goal.id)",
        kind: .goal,
        recordID: goal.id,
        title: goal.title,
        snippet: goal.description,
        status: goal.status,
        sourceReference: fileLabel(goal.file)
      ))
    }

    for profile in profiles where profileResults.count < limitPerCategory {
      let bindings = profile.runtimeBindings.flatMap { [$0.runtime, $0.runtimeAgentId] }
      guard matches([
        profile.id,
        profile.name,
        profile.description,
        profile.status,
        profile.primaryGoalRef,
        profile.reportsToAgentRef,
        profile.file,
      ] + profile.responsibilities.map(Optional.some)
        + profile.capabilities.map(Optional.some)
        + profile.skills.map(Optional.some)
        + profile.goalRefs.map(Optional.some)
        + bindings.map(Optional.some)) else { continue }
      profileResults.append(WorkspaceAgentWorkSearchResult(
        id: "agent:\(profile.id)",
        kind: .agent,
        recordID: profile.id,
        title: profile.name,
        snippet: profile.description,
        status: profile.status,
        sourceReference: fileLabel(profile.file)
      ))
    }

    return approvalResults + runResults + workflowResults + goalResults + profileResults
  }

  nonisolated static func searchCorpusFilesForWorkspace(
    _ files: [CorpusFile],
    query rawQuery: String,
    limit: Int
  ) -> [CorpusFile] {
    let query = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !query.isEmpty else { return [] }
    return files
      .compactMap { file -> (CorpusFile, Int)? in
        guard let score = fuzzyScore(query: query, candidate: file.relativePath) else { return nil }
        return (file, score)
      }
      .sorted { lhs, rhs in
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        return lhs.0.relativePath.localizedStandardCompare(rhs.0.relativePath) == .orderedAscending
      }
      .prefix(limit)
      .map(\.0)
  }

  nonisolated static func searchPageNodesForWorkspace(
    _ nodes: [OrgRoamNodeReference],
    query rawQuery: String,
    limit: Int
  ) -> [OrgRoamNodeReference] {
    let query = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !query.isEmpty else { return [] }
    let normalizedQuery = query.lowercased()
    return nodes
      .filter(\.isPageNode)
      .compactMap { node -> (OrgRoamNodeReference, Int)? in
        let candidates = [node.title] + node.aliases
        guard let score = candidates.compactMap({
          fuzzyScore(query: query, candidate: $0)
        }).max() else {
          return nil
        }
        let exactBoost = candidates.contains {
          $0.lowercased().contains(normalizedQuery)
        } ? 50 : 0
        return (node, score + exactBoost)
      }
      .sorted { lhs, rhs in
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        let titleOrder = lhs.0.title.localizedCaseInsensitiveCompare(rhs.0.title)
        if titleOrder != .orderedSame { return titleOrder == .orderedAscending }
        return lhs.0.file.localizedStandardCompare(rhs.0.file) == .orderedAscending
      }
      .prefix(limit)
      .map(\.0)
  }

  nonisolated static func prioritizedSearchResultsForDisplay(
    _ results: [SearchResult],
    query: String = "",
    limit: Int? = nil
  ) -> [SearchResult] {
    let normalizedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    let ranked = results.enumerated()
      .sorted { lhs, rhs in
        let lhsRank = searchResultDisplayRank(lhs.element, query: normalizedQuery)
        let rhsRank = searchResultDisplayRank(rhs.element, query: normalizedQuery)
        if lhsRank != rhsRank { return lhsRank < rhsRank }
        return lhs.offset < rhs.offset
      }
      .map(\.element)

    var seenActiveTodos: Set<String> = []
    let deduplicated = ranked.filter { result in
      guard result.isActiveTodo else { return true }
      return seenActiveTodos.insert(activeTodoSearchIdentity(result)).inserted
    }
    guard let limit else { return deduplicated }
    return Array(deduplicated.prefix(max(0, limit)))
  }

  nonisolated static func groupedSearchResultsForDisplay(_ results: [SearchResult]) -> [SearchResultGroup] {
    var grouped: [String: [SearchResult]] = [:]
    var fileOrder: [String] = []

    for result in results {
      if grouped[result.file] == nil {
        fileOrder.append(result.file)
        grouped[result.file] = []
      }
      grouped[result.file]?.append(result)
    }

    return fileOrder.compactMap { file in
      SearchResultGroup(file: file, results: grouped[file] ?? [])
    }
  }

  nonisolated private static func searchResultDisplayRank(_ result: SearchResult, query: String) -> Int {
    let resultKind = result.isActiveTodo ? 0 : result.isTerminalTodo ? 2 : 1
    let heading = result.heading?
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased() ?? ""
    let headingMatch: Int
    if !query.isEmpty && heading == query {
      headingMatch = 0
    } else if !query.isEmpty && heading.contains(query) {
      headingMatch = 1
    } else {
      headingMatch = 2
    }
    let matchedHeadingLine = result.headingLine == result.line ? 0 : 1
    return (resultKind * 100) + (headingMatch * 10) + matchedHeadingLine
  }

  nonisolated private static func activeTodoSearchIdentity(_ result: SearchResult) -> String {
    [
      result.corpus?.id ?? "",
      result.file,
      String(result.headingLine ?? result.line),
      result.heading ?? ""
    ].joined(separator: "\u{1F}")
  }

  public var selectedQuickOpenFile: CorpusFile? {
    if let selectedQuickOpenFileID {
      guard let selected = quickOpenItems.first(where: { $0.id == selectedQuickOpenFileID }),
            case .file(let file) = selected
      else {
        return nil
      }
      return file
    }
    return quickOpenFiles.first
  }

  public var selectedQuickOpenItem: WorkspaceQuickOpenItem? {
    if let selectedQuickOpenFileID,
       let selected = quickOpenItems.first(where: { $0.id == selectedQuickOpenFileID }) {
      return selected
    }
    return quickOpenItems.first
  }

  public func resetQuickOpenSelection() {
    selectedQuickOpenFileID = nil
  }

  public func moveQuickOpenSelection(_ direction: QuickOpenSelectionDirection) {
    let items = quickOpenItems
    guard !items.isEmpty else {
      selectedQuickOpenFileID = nil
      return
    }

    let currentIndex = selectedQuickOpenFileID.flatMap { id in
      items.firstIndex { $0.id == id }
    }
    let nextIndex: Int
    switch (direction, currentIndex) {
    case (.down, nil):
      nextIndex = items.startIndex
    case (.up, nil):
      nextIndex = items.index(before: items.endIndex)
    case (.down, let index?):
      nextIndex = index == items.index(before: items.endIndex) ? items.startIndex : items.index(after: index)
    case (.up, let index?):
      nextIndex = index == items.startIndex ? items.index(before: items.endIndex) : items.index(before: index)
    }
    selectedQuickOpenFileID = items[nextIndex].id
  }

  public func selectQuickOpenItem(_ item: WorkspaceQuickOpenItem, inNewTab: Bool = false) {
    if inNewTab {
      // Capture rank before the new tab resets transient state.
      let rank = quickOpenItems.firstIndex(of: item) ?? -1
      newWorkspaceTab()
      usageLog.record(.quickOpenSelect, ["kind": "file_new_tab", "rank": .int(rank)])
      if case .file(let file) = item {
        pendingNavigationSource = "quick_open"
        selectCorpusFile(file, surface: .files)
        return
      }
    }
    switch item {
    case .file(let file):
      let rank = quickOpenItems.firstIndex(of: item) ?? -1
      usageLog.record(.quickOpenSelect, [
        "kind": "file",
        "rank": .int(rank),
        "query_length": .int(quickOpenQuery.count),
        "recent": .bool(fileFrecencyScore(relativePath: file.relativePath) > 0),
      ])
      pendingNavigationSource = "quick_open"
      selectCorpusFile(file, surface: selectedSurface)
    case .chatThread(let thread):
      usageLog.record(.quickOpenSelect, [
        "kind": "chat",
        "rank": .int(quickOpenItems.firstIndex(of: item) ?? -1),
        "query_length": .int(quickOpenQuery.count),
      ])
      navigateToSurface(.aiChat)
      selectAIChatThread(thread.id)
      sidebarPromotedAIChatThreadID = thread.id
      statusText = "Opened \(thread.title)"
    }
  }

  /// Corpus assignment is intentionally constant-time on the main actor. The
  /// dictionary and normalized search rows scale with corpus size, so build an
  /// immutable projection on a detached task and publish only the latest one.
  /// Yielding once coalesces several assignments made in the same watcher or
  /// mutation burst before any corpus-scale work starts.
  private func resetCorpusFileDerivedState() {
    orgRoamLinkResolverRefreshTask?.cancel()
    orgRoamLinkResolverRefreshTask = nil
    searchNodeSearchGeneration &+= 1
    searchNodeSearchTask?.cancel()
    searchNodeSearchTask = nil
    searchNodes = []
    corpusFileProjectionGeneration &+= 1
    corpusFileProjectionTask?.cancel()
    corpusFileProjectionTask = nil
    resetPinnedCorpusFileProjection()
    corpusFileDisplayGeneration &+= 1
    corpusFileDisplayTask?.cancel()
    corpusFileDisplayTask = nil
    corpusFileProjection = .empty
    corpusFilesByPath = [:]
    quickOpenIndexedFiles = []
    corpusFileTree = []
    publishFilteredCorpusFiles([], tree: [])
    quickOpenSearchGeneration += 1
    quickOpenSearchTask?.cancel()
    quickOpenFiles = []
    quickOpenItems = []
  }

  private func scheduleCorpusFileProjection() {
    corpusFileProjectionGeneration &+= 1
    let projectionGeneration = corpusFileProjectionGeneration
    let filesGeneration = corpusFilesGeneration
    let files = corpusFiles
    corpusFileProjectionTask?.cancel()

    // Keep empty-query lists coherent immediately without doing corpus-scale
    // work. These prefixes are hard bounded by their UI result limits.
    if corpusFileFilter.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      publishFilteredCorpusFiles(Array(files.prefix(500)), tree: [])
    } else {
      publishFilteredCorpusFiles([], tree: [])
    }
    if quickOpenQuery.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      quickOpenFiles = Array(files.prefix(80))
      quickOpenItems = quickOpenFiles.map(WorkspaceQuickOpenItem.file)
      pruneQuickOpenSelection()
    }

    guard !files.isEmpty else {
      corpusFileProjectionTask = nil
      publishCorpusFileProjection(
        .empty,
        tree: [],
        projectionGeneration: projectionGeneration,
        filesGeneration: filesGeneration
      )
      return
    }

    corpusFileProjectionTask = Task { @MainActor [weak self, files] in
      await Task.yield()
      guard !Task.isCancelled,
            let self,
            self.corpusFileProjectionGeneration == projectionGeneration,
            self.corpusFilesGeneration == filesGeneration
      else { return }

      self.corpusFileProjectionBuildCountForTesting += 1
      let (projection, tree) = await Task.detached(priority: .utility) {
        (
          CorpusFileCatalog.projection(for: files),
          Self.makeCorpusFileTree(files)
        )
      }.value
      guard !Task.isCancelled,
            self.corpusFileProjectionGeneration == projectionGeneration,
            self.corpusFilesGeneration == filesGeneration
      else { return }

      self.publishCorpusFileProjection(
        projection,
        tree: tree,
        projectionGeneration: projectionGeneration,
        filesGeneration: filesGeneration
      )
    }
  }

  private func publishCorpusFileProjection(
    _ projection: CorpusFileCatalog.Projection,
    tree: [CorpusFileTreeNode],
    projectionGeneration: UInt64,
    filesGeneration: UInt64
  ) {
    guard corpusFileProjectionGeneration == projectionGeneration,
          corpusFilesGeneration == filesGeneration
    else { return }

    corpusFileProjection = projection
    corpusFilesByPath = projection.filesByPath
    quickOpenIndexedFiles = projection.indexedFiles
    corpusFileTree = tree
    corpusFileProjectionTask = nil
    schedulePinnedCorpusFileProjection(catalogProjection: projection)
    scheduleCorpusFileDisplayRefresh()
    scheduleQuickOpenSearch(debounce: false)
  }

  private func resetPinnedCorpusFileProjection() {
    pinnedCorpusFileProjectionGeneration &+= 1
    pinnedCorpusFileProjectionTask?.cancel()
    pinnedCorpusFileProjectionTask = nil
    guard !pinnedCorpusFiles.isEmpty else { return }
    pinnedCorpusFiles = []
    pinnedCorpusFileProjectionPublicationCountForTesting += 1
  }

  /// The sidebar consumes a stored, equality-gated projection. Resolving pins
  /// must never rebuild a corpus dictionary or touch the filesystem from a
  /// SwiftUI body: the corpus-scale relative-path map is built by the existing
  /// detached catalog lane, and the O(number of pins) fallback runs detached.
  private func schedulePinnedCorpusFileProjection(
    catalogProjection: CorpusFileCatalog.Projection? = nil
  ) {
    pinnedCorpusFileProjectionGeneration &+= 1
    let projectionGeneration = pinnedCorpusFileProjectionGeneration
    let sessionGeneration = corpusSessionGeneration
    pinnedCorpusFileProjectionTask?.cancel()
    pinnedCorpusFileProjectionTask = nil

    guard let root = corpusRoot else {
      if !pinnedCorpusFiles.isEmpty {
        pinnedCorpusFiles = []
        pinnedCorpusFileProjectionPublicationCountForTesting += 1
      }
      return
    }
    let relativePaths = pinnedFileRelativePaths
    guard !relativePaths.isEmpty else {
      if !pinnedCorpusFiles.isEmpty {
        pinnedCorpusFiles = []
        pinnedCorpusFileProjectionPublicationCountForTesting += 1
      }
      return
    }

    let filesByRelativePath = (
      catalogProjection ?? corpusFileProjection
    ).filesByRelativePath
    let catalogFiles = relativePaths.compactMap { filesByRelativePath[$0] }
    if catalogFiles.count == relativePaths.count,
       catalogFiles == pinnedCorpusFiles {
      return
    }

    let preparation = pinnedCorpusFileProjectionPreparationForTesting
    let didBuild = pinnedCorpusFileProjectionDidBuildForTesting
    pinnedCorpusFileProjectionTask = Task { @MainActor [weak self] in
      await Task.yield()
      guard !Task.isCancelled,
            let self,
            self.pinnedCorpusFileProjectionGeneration == projectionGeneration,
            self.corpusSessionGeneration == sessionGeneration,
            self.corpusRoot?.path == root.path
      else { return }

      if let preparation {
        await preparation(root, relativePaths)
      }
      guard !Task.isCancelled,
            self.pinnedCorpusFileProjectionGeneration == projectionGeneration,
            self.corpusSessionGeneration == sessionGeneration,
            self.corpusRoot?.path == root.path
      else { return }

      let projection = await Task.detached(priority: .utility) {
        Self.makePinnedCorpusFileProjection(
          filesByRelativePath: filesByRelativePath,
          corpusRoot: root,
          relativePaths: relativePaths,
          didBuild: didBuild
        )
      }.value
      self.pinnedCorpusFileProjectionBuildCountForTesting += 1
      if projection.wasBuiltOnMainThread {
        self.pinnedCorpusFileProjectionMainThreadBuildCountForTesting += 1
      }
      guard !Task.isCancelled,
            self.pinnedCorpusFileProjectionGeneration == projectionGeneration,
            self.corpusSessionGeneration == sessionGeneration,
            self.corpusRoot?.path == root.path
      else { return }

      self.pinnedCorpusFileProjectionTask = nil
      if projection.existingRelativePaths != self.pinnedFileRelativePaths {
        self.pinnedFileRelativePaths = projection.existingRelativePaths
        self.persistPinnedFiles()
      }
      guard projection.files != self.pinnedCorpusFiles else { return }
      self.pinnedCorpusFiles = projection.files
      self.pinnedCorpusFileProjectionPublicationCountForTesting += 1
    }
  }

  nonisolated private static func makePinnedCorpusFileProjection(
    filesByRelativePath: [String: CorpusFile],
    corpusRoot: URL,
    relativePaths: [String],
    didBuild: (@Sendable (Bool) -> Void)?
  ) -> PinnedCorpusFileProjection {
    let wasBuiltOnMainThread = Thread.isMainThread
    didBuild?(wasBuiltOnMainThread)
    var files: [CorpusFile] = []
    files.reserveCapacity(relativePaths.count)
    var existingRelativePaths: [String] = []
    existingRelativePaths.reserveCapacity(relativePaths.count)
    for relativePath in relativePaths {
      let file = filesByRelativePath[relativePath]
        ?? corpusFile(
          atPath: corpusRoot.appendingPathComponent(relativePath).path,
          corpusRoot: corpusRoot
        )
      guard let file else { continue }
      files.append(file)
      existingRelativePaths.append(relativePath)
    }
    return PinnedCorpusFileProjection(
      files: files,
      existingRelativePaths: existingRelativePaths,
      wasBuiltOnMainThread: wasBuiltOnMainThread
    )
  }

  private func rebuildQuickOpenChatIndex() {
    let signature = aiChatThreads.map {
      AIChatQuickOpenChatIndexSignature(id: $0.id, title: $0.title)
    }
    guard signature != quickOpenChatIndexSignature else { return }
    quickOpenChatIndexSignature = signature
    quickOpenIndexedChatThreads = aiChatThreads.map { thread in
      QuickOpenIndexedChatThread(
        id: thread.id,
        title: thread.title,
        normalizedTitle: Self.normalizedQuickOpenCandidate(thread.title)
      )
    }
    quickOpenChatThreadIndexesByID = Dictionary(
      uniqueKeysWithValues: aiChatThreads.enumerated().map { ($0.element.id, $0.offset) }
    )
  }

  private func scheduleCorpusFileDisplayRefresh() {
    corpusFileDisplayGeneration &+= 1
    let generation = corpusFileDisplayGeneration
    let indexedFiles = quickOpenIndexedFiles
    let query = corpusFileFilter
    let fullTree = corpusFileTree
    corpusFileDisplayTask?.cancel()

    guard !indexedFiles.isEmpty else {
      corpusFileDisplayTask = nil
      publishFilteredCorpusFiles([], tree: [])
      return
    }

    corpusFileDisplayTask = Task { @MainActor [weak self, indexedFiles, query] in
      await Task.yield()
      guard !Task.isCancelled,
            let self,
            self.corpusFileDisplayGeneration == generation
      else { return }

      let (files, tree) = await Task.detached(priority: .userInitiated) {
        let files = Self.filterIndexedQuickOpenFiles(
          indexedFiles,
          query: query,
          limit: 500
        )
        let tree = query.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
          ? fullTree
          : Self.makeCorpusFileTree(files)
        return (files, tree)
      }.value
      guard !Task.isCancelled,
            self.corpusFileDisplayGeneration == generation,
            self.corpusFileFilter == query
      else { return }

      self.publishFilteredCorpusFiles(files, tree: tree)
      self.corpusFileDisplayTask = nil
    }
  }

  private func publishFilteredCorpusFiles(
    _ files: [CorpusFile],
    tree: [CorpusFileTreeNode]
  ) {
    filteredCorpusFiles = files
    filteredCorpusFileTree = tree
    reconcileCorpusFileAIContextSelection(visibleIDs: files.map(\.id))
  }

  private func awaitCorpusFilePublication() async {
    while corpusFileCatalogMutationTask != nil
      || corpusFileProjectionTask != nil
      || pinnedCorpusFileProjectionTask != nil
      || corpusFileDisplayTask != nil {
      if let corpusFileCatalogMutationTask {
        await corpusFileCatalogMutationTask.value
      }
      if let corpusFileProjectionTask {
        await corpusFileProjectionTask.value
      }
      if let pinnedCorpusFileProjectionTask {
        await pinnedCorpusFileProjectionTask.value
      }
      if let corpusFileDisplayTask {
        await corpusFileDisplayTask.value
      }
    }
  }

  func waitForCorpusFilePublicationForTesting() async {
    await awaitCorpusFilePublication()
  }

  nonisolated static func makeCorpusFileTree(_ files: [CorpusFile]) -> [CorpusFileTreeNode] {
    let root = MutableCorpusFileTreeNode()
    for file in files {
      let components = file.relativePath.split(separator: "/").map(String.init)
      guard !components.isEmpty else { continue }
      var directory = root
      for component in components.dropLast() {
        if let existing = directory.directories[component] {
          directory = existing
        } else {
          let created = MutableCorpusFileTreeNode()
          directory.directories[component] = created
          directory = created
        }
      }
      directory.files.append(file)
    }

    func materialize(
      _ node: MutableCorpusFileTreeNode,
      relativePath: String
    ) -> [CorpusFileTreeNode] {
      let directories = node.directories.keys.sorted {
        $0.localizedCaseInsensitiveCompare($1) == .orderedAscending
      }.compactMap { name -> CorpusFileTreeNode? in
        guard let child = node.directories[name] else { return nil }
        let childPath = relativePath.isEmpty ? name : "\(relativePath)/\(name)"
        let children = materialize(child, relativePath: childPath)
        return CorpusFileTreeNode(
          id: "directory:\(childPath)",
          name: name,
          relativePath: childPath,
          file: nil,
          children: children,
          descendantFileCount: children.reduce(0) { $0 + $1.descendantFileCount }
        )
      }
      let fileNodes = node.files.sorted {
        $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending
      }.map { file in
        CorpusFileTreeNode(
          id: file.id,
          name: file.name,
          relativePath: file.relativePath,
          file: file,
          children: nil,
          descendantFileCount: 1
        )
      }
      return directories + fileNodes
    }

    return materialize(root, relativePath: "")
  }

  private func scheduleQuickOpenSearch(debounce: Bool = true) {
    quickOpenSearchGeneration += 1
    let generation = quickOpenSearchGeneration
    let query = quickOpenQuery
    let trimmedQuery = query.trimmingCharacters(in: .whitespacesAndNewlines)

    quickOpenSearchTask?.cancel()

    guard !trimmedQuery.isEmpty else {
      isFilteringQuickOpenFiles = false
      // Empty query: frequently and recently opened files first, then the
      // rest of the corpus alphabetically.
      let recent = recentCorpusFiles(limit: 15)
      let recentIDs = Set(recent.map(\.id))
      quickOpenFiles = recent + corpusFiles.lazy.filter { !recentIDs.contains($0.id) }.prefix(80 - recent.count)
      quickOpenItems = quickOpenFiles.map(WorkspaceQuickOpenItem.file)
      pruneQuickOpenSelection()
      return
    }

    let indexedFiles = quickOpenIndexedFiles
    let indexedChatThreads = quickOpenIndexedChatThreads
    let frecencyScores = currentFileFrecency().scores(now: Date())
    if !isFilteringQuickOpenFiles {
      isFilteringQuickOpenFiles = true
    }
    quickOpenSearchTask = Task { [indexedFiles, indexedChatThreads, frecencyScores, query, generation, debounce] in
      if debounce {
        try? await Task.sleep(nanoseconds: 80_000_000)
      }
      guard !Task.isCancelled else { return }

      let matches = await Task.detached(priority: .userInitiated) {
        Self.filterQuickOpenItems(
          files: indexedFiles,
          chatThreads: indexedChatThreads,
          query: query,
          limit: 80,
          frecencyScores: frecencyScores
        )
      }.value
      guard !Task.isCancelled else { return }

      await MainActor.run { [weak self] in
        guard let self, self.quickOpenSearchGeneration == generation else { return }
        let items = matches.compactMap { match -> WorkspaceQuickOpenItem? in
          switch match {
          case .file(let file):
            return .file(file)
          case .chatThread(let id):
            guard let index = self.quickOpenChatThreadIndexesByID[id],
                  self.aiChatThreads.indices.contains(index),
                  self.aiChatThreads[index].id == id
            else { return nil }
            return .chatThread(self.aiChatThreads[index])
          }
        }
        self.quickOpenItems = items
        self.quickOpenFiles = items.compactMap { item in
          guard case .file(let file) = item else { return nil }
          return file
        }
        self.isFilteringQuickOpenFiles = false
        self.pruneQuickOpenSelection()
      }
    }
  }

  private func pruneQuickOpenSelection() {
    guard let selectedQuickOpenFileID else { return }
    if !quickOpenItems.contains(where: { $0.id == selectedQuickOpenFileID }) {
      self.selectedQuickOpenFileID = nil
    }
  }

  nonisolated private static func filterIndexedQuickOpenFiles(
    _ files: [QuickOpenIndexedFile],
    query rawQuery: String,
    limit: Int
  ) -> [CorpusFile] {
    let query = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    let normalizedQuery = normalizedQuickOpenQuery(query)
    guard !normalizedQuery.isEmpty else {
      return Array(files.prefix(limit).map(\.file))
    }

    return files
      .compactMap { indexedFile -> (QuickOpenIndexedFile, Int)? in
        guard let score = fuzzyScore(normalizedQuery: normalizedQuery, normalizedCandidate: indexedFile.normalizedRelativePath)
        else { return nil }
        return (indexedFile, score)
      }
      .sorted { lhs, rhs in
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        return lhs.0.file.relativePath.localizedStandardCompare(rhs.0.file.relativePath) == .orderedAscending
      }
      .prefix(limit)
      .map(\.0.file)
  }

  nonisolated private static func filterQuickOpenItems(
    files: [QuickOpenIndexedFile],
    chatThreads: [QuickOpenIndexedChatThread],
    query rawQuery: String,
    limit: Int,
    frecencyScores: [String: Double] = [:]
  ) -> [QuickOpenSearchMatch] {
    let normalizedQuery = normalizedQuickOpenQuery(
      rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    )
    guard !normalizedQuery.isEmpty else {
      return Array(files.prefix(limit).map { QuickOpenSearchMatch.file($0.file) })
    }

    let fileMatches = files.compactMap { indexedFile -> (QuickOpenSearchMatch, Int, String)? in
      guard let score = fuzzyScore(
        normalizedQuery: normalizedQuery,
        normalizedCandidate: indexedFile.normalizedRelativePath
      ) else {
        return nil
      }
      let bonus = WorkspaceFileFrecency.quickOpenBonus(
        frecencyScores[indexedFile.file.relativePath] ?? 0
      )
      return (.file(indexedFile.file), score + bonus, indexedFile.file.relativePath)
    }
    let chatMatches = chatThreads.compactMap { thread -> (QuickOpenSearchMatch, Int, String)? in
      guard let score = fuzzyScore(
        normalizedQuery: normalizedQuery,
        normalizedCandidate: thread.normalizedTitle
      ) else {
        return nil
      }
      return (.chatThread(thread.id), score, thread.title)
    }

    return (fileMatches + chatMatches)
      .sorted { lhs, rhs in
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        return lhs.2.localizedStandardCompare(rhs.2) == .orderedAscending
      }
      .prefix(limit)
      .map(\.0)
  }

  /// Publish only immutable snapshots on the main actor. Resolver indexes,
  /// normalized search candidates, and corpus-relative paths all scale with
  /// corpus size and are built by `makeOrgRoamSearchProjection` off actor.
  private func publishOrgRoamSearchProjection(
    _ projectionBox: OrgRoamSearchProjectionBox,
    recordsDetachedBuild: Bool = true
  ) {
    let projection = projectionBox.projection
    if recordsDetachedBuild {
      orgRoamSearchProjectionBuildCountForTesting &+= 1
      if projection.wasBuiltOnMainThread {
        orgRoamSearchProjectionMainThreadBuildCountForTesting &+= 1
      }
    }

    // Watchers may report a file even when its semantic node projection did
    // not change. Avoid invalidating the root SwiftUI environment (and its
    // mounted NSTableView) for a content-identical resolver. Cache restoration
    // explicitly bypasses this fast path because it also changes corpus scope.
    if recordsDetachedBuild,
       projection.resolver == orgRoamLinkResolver {
      orgRoamSearchProjectionReleaseSink.enqueue([projectionBox])
      return
    }

    let replacedProjectionBox = OrgRoamSearchProjectionBox(
      projection: OrgRoamSearchProjection(
        resolver: orgRoamLinkResolver,
        searchNodeIndexRows: searchNodeIndexRows,
        wasBuiltOnMainThread: false
      ),
      releaseMetrics: orgRoamSearchProjectionReleaseMetrics
    )
    orgRoamLinkResolver = projection.resolver
    searchNodeIndexRows = projection.searchNodeIndexRows
    orgRoamSearchProjectionReleaseSink.enqueue([
      replacedProjectionBox,
      projectionBox,
    ])

    if searchMode == .nodes {
      scheduleSearchNodeDisplayRefresh(debounce: false)
    } else {
      searchNodeSearchGeneration &+= 1
      searchNodeSearchTask?.cancel()
      searchNodeSearchTask = nil
      searchNodes = []
    }
  }

  private func publishEmptyOrgRoamSearchProjection() {
    publishOrgRoamSearchProjection(
      OrgRoamSearchProjectionBox(
        projection: OrgRoamSearchProjection(
          resolver: .empty,
          searchNodeIndexRows: [],
          wasBuiltOnMainThread: false
        ),
        releaseMetrics: orgRoamSearchProjectionReleaseMetrics
      ),
      recordsDetachedBuild: false
    )
  }

  nonisolated private static func makeOrgRoamSearchProjection(
    resolver: OrgRoamLinkResolver,
    files: [CorpusFile],
    corpusRoot: URL?
  ) -> OrgRoamSearchProjection {
    var relativePathsByAbsolutePath: [String: String] = [:]
    relativePathsByAbsolutePath.reserveCapacity(files.count * 2)
    for file in files {
      relativePathsByAbsolutePath[file.path] = file.relativePath
      relativePathsByAbsolutePath[
        URL(fileURLWithPath: file.path).standardizedFileURL.path
      ] = file.relativePath
    }

    let rows = resolver.nodes.compactMap { node -> SearchNodeIndexRow? in
      guard node.isPageNode else { return nil }
      let standardizedNodePath = URL(fileURLWithPath: node.file).standardizedFileURL.path
      let relativePath = relativePathsByAbsolutePath[node.file]
        ?? relativePathsByAbsolutePath[standardizedNodePath]
        ?? corpusRelativePathWithoutFilesystemAccess(
          for: standardizedNodePath,
          root: corpusRoot
        )
      let labels = [node.title] + node.aliases
      let candidates = [
        node.title,
        node.aliases.joined(separator: " "),
        node.idValue ?? "",
        relativePath
      ]
      return SearchNodeIndexRow(
        node: node,
        normalizedCandidates: candidates.map(normalizedQuickOpenCandidate),
        normalizedLabels: labels.map(normalizedQuickOpenCandidate)
      )
    }
    return OrgRoamSearchProjection(
      resolver: resolver,
      searchNodeIndexRows: rows,
      wasBuiltOnMainThread: Thread.isMainThread
    )
  }

  /// This projection must stay lexical. Resolving symlinks performs filesystem
  /// metadata calls, which used to run once per node from the main actor.
  nonisolated private static func corpusRelativePathWithoutFilesystemAccess(
    for path: String,
    root: URL?
  ) -> String {
    guard let root else { return path }
    let rootPath = root.standardizedFileURL.path
    if path == rootPath { return "." }
    guard path.hasPrefix(rootPath + "/") else { return path }
    return String(path.dropFirst(rootPath.count + 1))
  }

  private func scheduleSearchNodeDisplayRefresh(
    limit: Int = 100,
    debounce: Bool = true
  ) {
    searchNodeSearchGeneration &+= 1
    let generation = searchNodeSearchGeneration
    let rows = searchNodeIndexRows
    let query = searchQuery
    searchNodeSearchTask?.cancel()

    guard !rows.isEmpty else {
      searchNodeSearchTask = nil
      searchNodes = []
      return
    }

    searchNodeSearchTask = Task { [rows, query, generation, limit] in
      if debounce {
        try? await Task.sleep(nanoseconds: 70_000_000)
      } else {
        await Task.yield()
      }
      guard !Task.isCancelled else { return }
      let matches = await Task.detached(priority: .userInitiated) {
        Self.filteredSearchNodes(rows, query: query, limit: limit)
      }.value
      guard !Task.isCancelled else { return }
      await MainActor.run { [weak self] in
        guard let self,
              self.searchNodeSearchGeneration == generation,
              self.searchQuery == query,
              self.searchMode == .nodes
        else { return }
        self.searchNodes = matches
        self.searchNodeSearchTask = nil
      }
    }
  }

  nonisolated private static func filteredSearchNodes(
    _ rows: [SearchNodeIndexRow],
    query rawQuery: String,
    limit: Int
  ) -> [OrgRoamNodeReference] {
    let query = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !query.isEmpty else {
      return Array(rows.map(\.node).sorted(by: compareSearchNodes).prefix(limit))
    }
    let normalizedQuery = Self.normalizedQuickOpenQuery(query)
    let normalizedLabelQuery = Self.normalizedQuickOpenCandidate(query)
    return rows
      .compactMap { row -> (OrgRoamNodeReference, Int)? in
        let bestScore = row.normalizedCandidates.compactMap {
          Self.fuzzyScore(normalizedQuery: normalizedQuery, normalizedCandidate: $0)
        }.max()
        guard let bestScore else { return nil }
        let exactBoost = row.normalizedLabels.contains { $0.contains(normalizedLabelQuery) } ? 50 : 0
        return (row.node, bestScore + exactBoost)
      }
      .sorted { lhs, rhs in
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        return compareSearchNodes(lhs.0, rhs.0)
      }
      .prefix(limit)
      .map(\.0)
  }

  nonisolated private static func compareSearchNodes(
    _ lhs: OrgRoamNodeReference,
    _ rhs: OrgRoamNodeReference
  ) -> Bool {
    let titleOrder = lhs.title.localizedCaseInsensitiveCompare(rhs.title)
    if titleOrder != .orderedSame { return titleOrder == .orderedAscending }
    let pathOrder = lhs.file.localizedStandardCompare(rhs.file)
    if pathOrder != .orderedSame { return pathOrder == .orderedAscending }
    return lhs.line < rhs.line
  }

  private func selectedLocationMatches(_ location: WorkspaceLocation) -> Bool {
    guard let selectedLocation else { return true }
    return Self.selectionIdentity(for: selectedLocation) == Self.selectionIdentity(for: location)
  }

  nonisolated private static func selectionIdentity(for location: WorkspaceLocation) -> String {
    let kind: String
    switch location {
    case .agenda:
      kind = "agenda"
    case .assigned:
      kind = "assigned"
    case .search:
      kind = "search"
    case .backlink:
      kind = "backlink"
    case .aiChatThreadRecord:
      kind = "openClaw"
    case .meeting:
      kind = "meeting"
    }
    return [
      kind,
      location.file,
      "\(location.lineForEditor)",
      location.title
    ].joined(separator: "\u{1F}")
  }

  private func scheduleAgendaRefresh(preserveSelection: Bool = true, updatesStatus: Bool = false) {
    scheduledAgendaRefreshTask?.cancel()
    scheduledAgendaRefreshTask = Task { @MainActor in
      try? await Task.sleep(nanoseconds: 150_000_000)
      guard !Task.isCancelled else { return }
      await refreshAgenda(preserveSelection: preserveSelection, updatesStatus: updatesStatus)
    }
  }

  private func applyDeferredStableAutosaveForActiveBlock() -> Bool {
    guard let editingBlockID,
          let deferred = deferredStableAutosaves.removeValue(forKey: editingBlockID)
    else {
      return false
    }

    if selectedEntrySource?.id == deferred.source.id {
      selectedEntrySource = deferred.source
    }

    let updatedBlocks = Self.replacingBlock(
      selectedBlock,
      with: deferred.block,
      in: selectedRenderedBlocks
    )
    setSelectedRenderedBlocks(updatedBlocks, preservingMetadata: true)
    selectedBlockID = deferred.block.id
    return true
  }

  private func restoreActiveBlockOriginal() {
    guard let editingBlockID,
          let original = activeBlockOriginals[editingBlockID]
    else {
      return
    }
    let updatedBlocks = Self.replacingBlock(
      selectedBlock,
      with: original,
      in: selectedRenderedBlocks
    )
    setSelectedRenderedBlocks(updatedBlocks, preservingMetadata: true)
    selectedBlockID = original.id
  }

  private func resetBlockEditing() {
    let wasEditingBlock = editingBlockID != nil
    editingBlockID = nil
    editableBlockText = ""
    activeBlockDrafts.removeAll()
    activeBlockOriginals.removeAll()
    activeBlockInitialSelections.removeAll()
    deferredStableAutosaves.removeAll()
    if wasEditingBlock, pendingAgendaRefreshAfterBlockEditing {
      pendingAgendaRefreshAfterBlockEditing = false
      scheduleAgendaRefresh(preserveSelection: true)
    }
  }

  private func resetBlockState() {
    selectedBlockID = nil
    pendingBlockSelection = nil
    transientDraftBlock = nil
    resetBlockEditing()
  }

  private var activeEditingBlock: OrgEditableBlock? {
    guard let editingBlockID else { return nil }
    return selectedRenderedBlocks.first { $0.id == editingBlockID }
  }

  nonisolated static func directTypingInsertionText(from event: NSEvent) -> String? {
    guard let characters = event.characters,
          !characters.isEmpty,
          characters.unicodeScalars.allSatisfy({ $0.properties.generalCategory != .control })
    else {
      return nil
    }
    return characters
  }

  nonisolated static func editingDraft(
    _ block: OrgEditableBlock,
    appending text: String
  ) -> String? {
    guard !text.isEmpty else { return nil }
    switch block.rendered {
    case .heading:
      return headingEditingDraft(block.rawText, appending: text)
    case .paragraph, .listItem:
      return block.rawText + text
    default:
      return nil
    }
  }

  nonisolated private static func headingEditingDraft(
    _ rawText: String,
    appending text: String
  ) -> String? {
    var lines = normalizeLineEndings(rawText)
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    guard let first = lines.first,
          let regex = try? NSRegularExpression(pattern: #"^(\*+\s+)(.*)$"#)
    else {
      return nil
    }

    let nsFirst = first as NSString
    let fullRange = NSRange(location: 0, length: nsFirst.length)
    guard let match = regex.firstMatch(in: first, range: fullRange),
          match.range.location == 0
    else {
      return nil
    }

    let prefix = nsFirst.substring(with: match.range(at: 1))
    var rest = nsFirst.substring(with: match.range(at: 2))
      .trimmingCharacters(in: .whitespaces)
    var tagsSuffix = ""
    if let tagRange = rest.range(of: #"\s+(:[A-Za-z0-9_@#%:.-]+:)\s*$"#, options: .regularExpression) {
      tagsSuffix = String(rest[tagRange])
      rest.removeSubrange(tagRange)
      rest = rest.trimmingCharacters(in: .whitespaces)
    }

    var tokens = rest.split(separator: " ", omittingEmptySubsequences: true).map(String.init)
    var prefixTokens: [String] = []
    if let firstToken = tokens.first,
       allHeadingTodoKeywords.contains(firstToken.uppercased()) {
      prefixTokens.append(firstToken.uppercased())
      tokens.removeFirst()
    }
    if let firstToken = tokens.first,
       firstToken.range(of: #"^\[#([A-Za-z0-9])\]$"#, options: .regularExpression) != nil {
      prefixTokens.append(firstToken.uppercased())
      tokens.removeFirst()
    }

    let title = tokens.joined(separator: " ")
    let updatedTitle = title.isEmpty ? text : title + text
    lines[0] = "\(prefix)\((prefixTokens + [updatedTitle]).joined(separator: " "))\(tagsSuffix)"
    return lines.joined(separator: "\n")
  }

  private func discardTransientDraft(status: String? = nil) {
    guard let draft = transientDraftBlock else {
      resetBlockEditing()
      return
    }
    selectedRenderedBlocks.removeAll { $0.id == draft.block.id }
    let existingIDs = Set(selectedRenderedBlocks.map(\.id))
    selectedRenderedBlocks.append(contentsOf: draft.coveredBlocks.filter { !existingIDs.contains($0.id) })
    selectedRenderedBlocks = Self.sortEditableBlocksForDisplay(selectedRenderedBlocks)
    if selectedBlockID == draft.block.id {
      selectedBlockID = nil
    }
    transientDraftBlock = nil
    resetBlockEditing()
    if let status {
      statusText = status
    }
  }

  private func activateTransientDraft(_ draft: TransientDraftBlock) {
    let coveredIDs = Set(draft.coveredBlocks.map(\.id))
    selectedRenderedBlocks.removeAll { $0.id == draft.block.id }
    selectedRenderedBlocks.removeAll { coveredIDs.contains($0.id) }
    selectedRenderedBlocks.append(draft.block)
    selectedRenderedBlocks = Self.sortEditableBlocksForDisplay(selectedRenderedBlocks)
    selectedBlockID = draft.block.id
    editingBlockID = draft.block.id
    editableBlockText = draft.block.rawText
    activeBlockDrafts[draft.block.id] = draft.block.rawText
    revealRenderedBlockIfHiddenByFold(draft.block.id)
    requestDetailReveal(toBlock: draft.block.id)
  }

  private func revealRenderedBlockIfHiddenByFold(_ blockID: OrgEditableBlock.ID) {
    var nextFoldedIDs = foldedRenderedBlockIDs
    while let ancestorID = OrgRenderedFoldTree.foldedAncestorID(
      hiding: blockID,
      foldedBlockIDs: nextFoldedIDs,
      blocks: selectedRenderedBlocks
    ) {
      nextFoldedIDs.remove(ancestorID)
    }
    if nextFoldedIDs != foldedRenderedBlockIDs {
      foldedRenderedBlockIDs = nextFoldedIDs
    }
  }

  private func saveTransientDraftBlock(_ draft: TransientDraftBlock) async {
    guard selectedEntrySource?.isEditable == true else {
      statusText = "No editable source loaded"
      return
    }

    guard let replacementBody = Self.normalizedTransientDraftText(editingDraftText(for: draft.block), for: draft.block) else {
      discardTransientDraft(status: "Draft discarded")
      return
    }

    isSavingBlock = true
    defer { isSavingBlock = false }

    let replacement = "\(draft.replacementPrefix)\(replacementBody)\(draft.replacementSuffix)"
    do {
      let undoSnapshot = await fileUndoSnapshot(for: draft.file)
      try await replaceDocumentSourceRange(
        file: draft.file,
        startLine: draft.insertionLine,
        endLineExclusive: draft.replacementEndLineExclusive,
        replacement: replacement
      )
      let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: draft.file)
      await recordFileUndo(from: undoSnapshot)
      transientDraftBlock = nil
      selectedRenderedBlocks.removeAll { $0.id == draft.block.id }
      if selectedBlockID == draft.block.id {
        selectedBlockID = nil
      }
      invalidateCanonicalDocumentCache(for: draft.file)
      resetBlockEditing()
      isEditingEntry = false
      pendingBlockSelection = PendingBlockSelection(
        file: draft.file,
        line: draft.insertionLine + draft.selectionLineOffset,
        mode: .containingOrNearest
      )
      statusText = encryptedCount > 0
        ? "Saved and encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
        : "Saved block \(relativePath(draft.file)):\(draft.insertionLine)"
      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      scheduleAgendaRefresh(preserveSelection: true)
    } catch {
      errorText = error.localizedDescription
      statusText = "Block save failed"
    }
  }

  private func replaceBlockSourceAndFinish(
    source: EntrySource,
    block: OrgEditableBlock,
    replacement: String,
    status: String,
    selectLine: Int? = nil,
    selectionMode: PendingBlockSelectionMode = .containingOrNearest
  ) async throws {
    let normalizedReplacement = Self.normalizeLineEndings(replacement)
    let updatedSource = try await Task.detached(priority: .userInitiated) {
      try Self.replacingSourceBlock(
        block,
        in: source,
        with: normalizedReplacement
      )
    }.value
    let currentRenderedBlocks = selectedRenderedBlocks
    let undoSnapshot = await fileUndoSnapshot(for: source.file)
    try await replaceDocumentSourceRange(
      file: source.file,
      startLine: block.startLine,
      endLineExclusive: block.endLineExclusive,
      replacement: normalizedReplacement,
      expectedOriginal: block.rawText
    )
    let encryptedCount = try await encryptOrgCryptSubtreesAfterExplicitSave(file: source.file)

    if encryptedCount > 0 {
      await recordFileUndo(from: undoSnapshot)
      guard selectedEntrySource?.id == source.id else { return }
      invalidateCanonicalDocumentCache(for: source.file)
      transientDraftBlock = nil
      resetBlockEditing()
      isEditingEntry = false
      statusText = "Saved and encrypted \(encryptedCount) subtree\(encryptedCount == 1 ? "" : "s")"
      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      scheduleAgendaRefresh(preserveSelection: true)
      return
    }

    let updatedBlocks = await Task.detached(priority: .userInitiated) {
      Self.locallyUpdatingRenderedBlocks(
        currentRenderedBlocks,
        replacing: block,
        with: normalizedReplacement
      )
    }.value

    guard selectedEntrySource?.id == source.id else {
      await recordFileUndo(from: undoSnapshot)
      return
    }

    await recordFileUndo(from: undoSnapshot)
    invalidateCanonicalDocumentCache(for: source.file)
    transientDraftBlock = nil
    resetBlockEditing()
    isEditingEntry = false
    selectedEntrySource = updatedSource
    let updatedVisibleBlocks = blocksWithTransientDraft(updatedBlocks, for: updatedSource)
    selectedRenderedBlocks = updatedVisibleBlocks
    if let selectLine {
      selectedBlockID = blockForSelectionLine(
        max(1, selectLine),
        mode: selectionMode,
        in: updatedVisibleBlocks
      )?.id
    }
    statusText = status
    scheduleAgendaRefresh(preserveSelection: true)
  }

  private var selectableBlocks: [OrgEditableBlock] {
    guard let source = selectedEntrySource else { return [] }
    return OrgRenderedFoldTree.visibleBlocks(
      selectedRenderedBlocks,
      foldedBlockIDs: foldedRenderedBlockIDs
    ).filter { block in
      block.isEditable
        && block.startLine >= source.startLine
        && block.endLineExclusive <= source.endLineExclusive
    }
  }

  private func previousMergeTarget(before block: OrgEditableBlock) -> OrgEditableBlock? {
    let sortedBlocks = Self.sortEditableBlocksForDisplay(selectedRenderedBlocks)
    guard let currentIndex = sortedBlocks.firstIndex(where: { $0.id == block.id }) else {
      return sortedBlocks.last { candidate in
        candidate.endLineExclusive <= block.startLine
          && Self.isMergeablePreviousTextBlock(candidate)
      }
    }

    guard currentIndex > 0 else { return nil }
    for candidate in sortedBlocks[..<currentIndex].reversed()
      where Self.isMergeablePreviousTextBlock(candidate) {
      return candidate
    }
    return nil
  }

  private func blockForSelectionLine(
    _ line: Int,
    mode: PendingBlockSelectionMode,
    in blocks: [OrgEditableBlock]
  ) -> OrgEditableBlock? {
    let editableBlocks = blocks.filter(\.isEditable)
    switch mode {
    case .containingOrNearest:
      if let containing = editableBlocks.first(where: { $0.startLine <= line && line < $0.endLineExclusive }) {
        return containing
      }
      if let next = editableBlocks.first(where: { $0.startLine >= line }) {
        return next
      }
    case .nextOrNearest:
      if let next = editableBlocks.first(where: { $0.startLine >= line }) {
        return next
      }
      if let containing = editableBlocks.first(where: { $0.startLine <= line && line < $0.endLineExclusive }) {
        return containing
      }
    }
    return editableBlocks.last
  }

  private var movableBlocks: [OrgEditableBlock] {
    guard let source = selectedEntrySource else { return [] }
    return selectedRenderedBlocks.filter { block in
      guard block.isEditable,
            block.startLine >= source.startLine,
            block.endLineExclusive <= source.endLineExclusive
      else {
        return false
      }
      return !(source.isSubtree && block.startLine == source.startLine)
    }
  }

  private func moveTarget(for block: OrgEditableBlock, direction: OrgBlockMoveDirection) -> OrgEditableBlock? {
    let blocks = movableBlocks
    guard let index = blocks.firstIndex(where: { $0.id == block.id }) else { return nil }
    switch direction {
    case .up:
      guard index > 0 else { return nil }
      return blocks[index - 1]
    case .down:
      guard index < blocks.count - 1 else { return nil }
      return blocks[index + 1]
    }
  }

  private func transientDraftEditableBlock(
    startLine: Int,
    endLineExclusive: Int,
    rawText: String,
    rendered: OrgRenderedBlock
  ) -> OrgEditableBlock {
    transientDraftIDCounter += 1
    return OrgEditableBlock(
      id: "transient-draft:\(transientDraftIDCounter):\(startLine):\(endLineExclusive)",
      startLine: startLine,
      endLineExclusive: endLineExclusive,
      rawText: rawText,
      rendered: rendered
    )
  }

  private func insertionDraftBlock(
    for kind: OrgInsertBlockKind,
    after previousBlock: OrgEditableBlock,
    in source: EntrySource,
    initialText: String? = nil
  ) -> TransientDraftBlock {
    let rawText = initialText ?? insertionDraftRawText(for: kind, after: previousBlock, in: source)
    let insertionLine = previousBlock.endLineExclusive
    return TransientDraftBlock(
      file: source.file,
      insertionLine: insertionLine,
      replacementEndLineExclusive: insertionLine,
      replacementPrefix: "\n",
      replacementSuffix: "",
      selectionLineOffset: 1,
      block: transientDraftEditableBlock(
        startLine: insertionLine,
        endLineExclusive: insertionLine,
        rawText: rawText,
        rendered: insertionDraftRenderedBlock(for: kind, rawText: rawText, after: previousBlock, in: source)
      ),
      coveredBlocks: []
    )
  }

  private func appendDraftBlock(
    kind: OrgInsertBlockKind,
    in source: EntrySource
  ) -> TransientDraftBlock {
    let rawText = appendDraftRawText(for: kind)
    let isSourceEmpty = source.text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
    let insertionLine = isSourceEmpty ? source.startLine : max(source.startLine, source.endLineExclusive)
    let replacementEndLineExclusive = isSourceEmpty
      ? max(source.startLine, source.endLineExclusive)
      : insertionLine
    let replacementPrefix = isSourceEmpty ? "" : "\n"
    let selectionLineOffset = replacementPrefix.isEmpty ? 0 : 1
    return TransientDraftBlock(
      file: source.file,
      insertionLine: insertionLine,
      replacementEndLineExclusive: replacementEndLineExclusive,
      replacementPrefix: replacementPrefix,
      replacementSuffix: "",
      selectionLineOffset: selectionLineOffset,
      block: transientDraftEditableBlock(
        startLine: insertionLine,
        endLineExclusive: insertionLine,
        rawText: rawText,
        rendered: appendDraftRenderedBlock(for: kind, rawText: rawText)
      ),
      coveredBlocks: []
    )
  }

  private func appendDraftRawText(for kind: OrgInsertBlockKind) -> String {
    switch kind {
    case .paragraph:
      return ""
    case .heading:
      return "* "
    case .todo:
      return "* TODO "
    case .table:
      return """
      | Name | Value |
      |------+-------|
      |      |       |
      """
    case .divider:
      return "-----"
    case .image:
      return mediaDraftRawText(kind: .image, content: "")
    case .video:
      return mediaDraftRawText(kind: .video, content: "")
    case .properties:
      return """
      :PROPERTIES:
      :KEY:
      :END:
      """
    case .quote:
      return """
      #+begin_quote

      #+end_quote
      """
    case .source:
      return """
      #+begin_src sh

      #+end_src
      """
    }
  }

  private func appendDraftRenderedBlock(for kind: OrgInsertBlockKind, rawText: String) -> OrgRenderedBlock {
    switch kind {
    case .paragraph:
      return .paragraph("")
    case .heading:
      return .heading(OrgHeadingBlock(level: 1, todo: nil, priority: nil, title: "", tags: []))
    case .todo:
      return .heading(OrgHeadingBlock(level: 1, todo: "TODO", priority: nil, title: "", tags: []))
    case .table:
      return .table(OrgEditableTable(rawText: rawText).renderedBlock)
    case .divider:
      return .horizontalRule
    case .image, .video:
      return .paragraph(rawText)
    case .properties:
      return .properties(OrgEditablePropertyDrawer(rawText: rawText).renderedRows)
    case .quote:
      return .quote([])
    case .source:
      let source = OrgEditableSourceBlock(rawText: rawText)
      return .source(language: source.renderedLanguage, lines: source.renderedLines)
    }
  }

  private func insertionDraftRawText(
    for kind: OrgInsertBlockKind,
    after block: OrgEditableBlock,
    in source: EntrySource
  ) -> String {
    let headingLevel = insertionHeadingLevel(after: block, in: source)
    let stars = String(repeating: "*", count: max(1, headingLevel))
    switch kind {
    case .paragraph:
      return ""
    case .heading:
      return "\(stars) "
    case .todo:
      return "\(stars) TODO "
    case .table:
      return """
      | Name | Value |
      |------+-------|
      |      |       |
      """
    case .divider:
      return "-----"
    case .image:
      return mediaDraftRawText(kind: .image, content: "")
    case .video:
      return mediaDraftRawText(kind: .video, content: "")
    case .properties:
      return """
      :PROPERTIES:
      :KEY:
      :END:
      """
    case .quote:
      return """
      #+begin_quote

      #+end_quote
      """
    case .source:
      return """
      #+begin_src sh

      #+end_src
      """
    }
  }

  private func insertionDraftRenderedBlock(
    for kind: OrgInsertBlockKind,
    rawText: String,
    after block: OrgEditableBlock,
    in source: EntrySource
  ) -> OrgRenderedBlock {
    let headingLevel = insertionHeadingLevel(after: block, in: source)
    switch kind {
    case .paragraph:
      return .paragraph("")
    case .heading:
      return .heading(OrgHeadingBlock(level: headingLevel, todo: nil, priority: nil, title: "", tags: []))
    case .todo:
      return .heading(OrgHeadingBlock(level: headingLevel, todo: "TODO", priority: nil, title: "", tags: []))
    case .table:
      return .table(OrgEditableTable(rawText: rawText).renderedBlock)
    case .divider:
      return .horizontalRule
    case .image, .video:
      return .paragraph(rawText)
    case .properties:
      return .properties(OrgEditablePropertyDrawer(rawText: rawText).renderedRows)
    case .quote:
      return .quote([])
    case .source:
      let source = OrgEditableSourceBlock(rawText: rawText)
      return .source(language: source.renderedLanguage, lines: source.renderedLines)
    }
  }

  private func conversionDraftBlock(
    for kind: OrgInsertBlockKind,
    replacing block: OrgEditableBlock,
    in source: EntrySource,
    draft: String
  ) -> TransientDraftBlock {
    let rawText = conversionDraftRawText(for: kind, replacing: block, in: source, draft: draft)
    return TransientDraftBlock(
      file: source.file,
      insertionLine: block.startLine,
      replacementEndLineExclusive: block.endLineExclusive,
      replacementPrefix: "",
      replacementSuffix: "",
      selectionLineOffset: 0,
      block: transientDraftEditableBlock(
        startLine: block.startLine,
        endLineExclusive: block.endLineExclusive,
        rawText: rawText,
        rendered: draftRenderedBlock(for: kind, rawText: rawText, fallbackLine: block.startLine, fallbackBlock: block, in: source)
      ),
      coveredBlocks: [block]
    )
  }

  private func conversionDraftRawText(
    for kind: OrgInsertBlockKind,
    replacing block: OrgEditableBlock,
    in source: EntrySource,
    draft: String
  ) -> String {
    let content = slashCommandContent(from: draft)
    guard !content.isEmpty else {
      return insertionDraftRawText(for: kind, after: block, in: source)
    }

    let headingLevel = insertionHeadingLevel(after: block, in: source)
    let stars = String(repeating: "*", count: max(1, headingLevel))
    switch kind {
    case .paragraph:
      return content
    case .heading:
      return "\(stars) \(singleLineTitle(content, fallback: ""))"
    case .todo:
      return "\(stars) TODO \(singleLineTitle(content, fallback: ""))"
    case .table:
      if content.contains("|") {
        return content
      }
      return insertionDraftRawText(for: .table, after: block, in: source)
    case .divider:
      return "-----"
    case .image:
      return mediaDraftRawText(kind: .image, content: content)
    case .video:
      return mediaDraftRawText(kind: .video, content: content)
    case .properties:
      return insertionDraftRawText(for: .properties, after: block, in: source)
    case .quote:
      return """
      #+begin_quote
      \(content)
      #+end_quote
      """
    case .source:
      return """
      #+begin_src sh
      \(content)
      #+end_src
      """
    }
  }

  private func mediaDraftRawText(kind: OrgMediaAttachment.Kind, content: String) -> String {
    let trimmed = content.trimmingCharacters(in: .whitespacesAndNewlines)
    if trimmed.hasPrefix("[["),
       OrgMediaAttachment.standalone(raw: trimmed) != nil {
      return trimmed
    }

    let placeholderTarget: String
    let placeholderLabel: String
    switch kind {
    case .image:
      placeholderTarget = "images/image.png"
      placeholderLabel = "Image"
    case .video:
      placeholderTarget = "videos/video.mp4"
      placeholderLabel = "Video"
    }

    guard !trimmed.isEmpty else {
      return OrgEditableMediaLink(kind: kind, target: placeholderTarget, label: placeholderLabel).formattedRawText
    }

    if let attachment = OrgMediaAttachment.standalone(raw: trimmed) {
      return OrgEditableMediaLink(kind: kind, target: attachment.target, label: attachment.displayName).formattedRawText
    }

    if trimmed.range(of: #"\.(?:png|jpe?g|gif|tiff?|bmp|heic|heif|webp|mov|mp4|m4v|avi|webm)(?:[#?].*)?$"#, options: [.regularExpression, .caseInsensitive]) != nil {
      return OrgEditableMediaLink(kind: kind, target: trimmed).formattedRawText
    }

    return OrgEditableMediaLink(kind: kind, target: placeholderTarget, label: trimmed).formattedRawText
  }

  private func draftRenderedBlock(
    for kind: OrgInsertBlockKind,
    rawText: String,
    fallbackLine: Int,
    fallbackBlock: OrgEditableBlock,
    in source: EntrySource
  ) -> OrgRenderedBlock {
    if kind == .paragraph,
       rawText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
      return .paragraph("")
    }
    if let rendered = OrgEntryRenderer.parseEditable(rawText, baseLine: fallbackLine).first?.rendered {
      return rendered
    }
    return insertionDraftRenderedBlock(for: kind, rawText: rawText, after: fallbackBlock, in: source)
  }

  private func slashCommandContent(from draft: String) -> String {
    let trimmed = draft.trimmingCharacters(in: .whitespacesAndNewlines)
    guard trimmed.hasPrefix("/") else { return trimmed }

    let remainder = trimmed.dropFirst()
    guard let contentStart = remainder.firstIndex(where: { $0.isWhitespace }) else {
      return ""
    }

    return String(remainder[contentStart...])
      .trimmingCharacters(in: .whitespacesAndNewlines)
  }

  private func singleLineTitle(_ text: String, fallback: String) -> String {
    let title = text
      .split(whereSeparator: { $0.isWhitespace })
      .joined(separator: " ")
      .trimmingCharacters(in: .whitespacesAndNewlines)
    return title.isEmpty ? fallback : title
  }

  private func insertionHeadingLevel(after block: OrgEditableBlock, in source: EntrySource) -> Int {
    if source.isSubtree,
       let rootLevel = Self.firstHeadingLevel(in: source.text) {
      return min(6, rootLevel + 1)
    }

    if case .heading(let heading) = block.rendered {
      return heading.level
    }

    if let previousHeading = selectedRenderedBlocks
      .filter({ $0.startLine <= block.startLine })
      .last(where: { candidate in
        if case .heading = candidate.rendered { return true }
        return false
      }),
      case .heading(let heading) = previousHeading.rendered {
      return heading.level
    }

    return 1
  }

  nonisolated private static func firstHeadingLevel(in text: String) -> Int? {
    for line in normalizeLineEndings(text).split(separator: "\n", omittingEmptySubsequences: false) {
      if let level = headingLevel(String(line)) {
        return level
      }
    }
    return nil
  }

  func sourceBlockRunKey(for block: OrgEditableBlock) -> String {
    let file = selectedEntrySource?.file ?? selectedLocation?.file ?? ""
    return "\(file):\(block.id)"
  }

  @discardableResult
  private func supersedeDailyNoteNavigation() -> UInt64 {
    dailyNoteNavigationGeneration &+= 1
    dailyNoteActivationTask?.cancel()
    dailyNoteActivationTask = nil
    homeActivationTask?.cancel()
    homeActivationTask = nil
    return dailyNoteNavigationGeneration
  }

  private func cancelPendingDailyNoteNavigation() {
    guard dailyNoteActivationTask != nil || homeActivationTask != nil else { return }
    _ = supersedeDailyNoteNavigation()
  }

  public func openDailyNote(_ target: DailyNoteTarget) {
    startDailyNoteNavigation(date: Self.date(for: target))
  }

  public func openDailyNoteFromSidebar(_ target: DailyNoteTarget) {
    openDailyNote(target)
  }

  public func presentDailyNoteDatePicker() {
    guard corpusRoot != nil else {
      statusText = "No corpus selected"
      return
    }
    dailyNotePickerDate = Date()
    isDailyNoteDatePickerPresented = true
  }

  public func openDailyNoteFromDatePicker() {
    let date = dailyNotePickerDate
    isDailyNoteDatePickerPresented = false
    startDailyNoteNavigation(date: date)
  }

  private func startDailyNoteNavigation(date: Date) {
    guard let corpusRoot,
          let context = captureDocumentCorpusContext()
    else {
      statusText = "No corpus selected"
      return
    }

    let generation = supersedeDailyNoteNavigation()
    dailyNoteActivationTask = Task { @MainActor [weak self] in
      guard let self else { return }
      await self.openDailyNote(
        date: date,
        corpusRoot: corpusRoot,
        context: context,
        generation: generation
      )
    }
  }

  private func openDailyNote(
    date: Date,
    corpusRoot: URL,
    context: WorkspaceDocumentCorpusContext,
    generation: UInt64
  ) async {
    let url = await dailyNotePath(corpusRoot: corpusRoot, date: date)
    await openDailyNote(
      at: url,
      corpusRoot: corpusRoot,
      context: context,
      generation: generation,
      allowsCreation: !automaticDailyNoteCreationDisabled
    )
  }

  private func openDailyNote(
    at url: URL,
    corpusRoot: URL,
    context: WorkspaceDocumentCorpusContext,
    generation: UInt64,
    allowsCreation: Bool
  ) async {
    guard !Task.isCancelled,
          dailyNoteNavigationGeneration == generation,
          isCurrentDocumentCorpusContext(context)
    else { return }
    do {
      if allowsCreation {
        try await ensureDailyNoteExists(at: url, context: context)
      } else if !(await dailyNoteExists(at: url)) {
        dailyNoteActivationTask = nil
        presentMissingDailyNote(
          at: url,
          corpusRoot: corpusRoot,
          opensHome: false,
          surface: selectedSurface,
          recordsHistory: true
        )
        return
      }
      let file = await Task.detached(priority: .userInitiated) {
        Self.corpusFileOffMain(for: url, corpusRoot: corpusRoot)
      }.value
      guard !Task.isCancelled,
            dailyNoteNavigationGeneration == generation,
            isCurrentDocumentCorpusContext(context)
      else { return }
      dailyNoteActivationTask = nil
      upsertCorpusFile(file)
      // Daily navigation replaces only the document, regardless of whether it
      // came from the sidebar, a keyboard shortcut, or the date picker.
      selectCorpusFile(file, surface: selectedSurface)
      if selectedSurface == .files {
        isWorkspaceSurfacePaneClosed = true
      }
      activeWorkspacePane = .detail
      statusText = "Opened \(file.relativePath)"
    } catch {
      guard !Task.isCancelled,
            dailyNoteNavigationGeneration == generation,
            isCurrentDocumentCorpusContext(context)
      else { return }
      dailyNoteActivationTask = nil
      errorText = error.localizedDescription
      statusText = "Could not open \(url.lastPathComponent)"
    }
  }

  public func openHome() {
    guard let corpusRoot else {
      if selectedSurface != .home
        || expandedWorkspaceSurface != nil
        || isWorkspaceSurfacePaneClosed
        || isWorkspaceDetailPaneClosed
        || isWorkspaceDetailPaneExpanded {
        recordCurrentNavigationDestination()
      }
      expandedWorkspaceSurface = nil
      isWorkspaceSurfacePaneClosed = false
      isWorkspaceDetailPaneClosed = false
      isWorkspaceDetailPaneExpanded = false
      navigateToSurface(.home, recordsHistory: false)
      statusText = "No corpus selected"
      return
    }

    guard let context = captureDocumentCorpusContext() else { return }
    let generation = supersedeDailyNoteNavigation()
    homeActivationTask = Task { @MainActor [weak self] in
      guard let self else { return }
      let url = await self.dailyNotePath(corpusRoot: corpusRoot, date: Date())
      await self.finishOpeningHome(
        url: url,
        corpusRoot: corpusRoot,
        context: context,
        generation: generation
      )
    }
  }

  private func finishOpeningHome(
    url: URL,
    corpusRoot: URL,
    context: WorkspaceDocumentCorpusContext,
    generation: UInt64,
    allowsCreation: Bool? = nil
  ) async {
    guard !Task.isCancelled,
          dailyNoteNavigationGeneration == generation,
          isCurrentDocumentCorpusContext(context)
    else { return }
    do {
      let shouldCreate = allowsCreation ?? !automaticDailyNoteCreationDisabled
      if shouldCreate {
        try await ensureDailyNoteExists(at: url, context: context)
      } else if !(await dailyNoteExists(at: url)) {
        homeActivationTask = nil
        presentMissingDailyNote(
          at: url,
          corpusRoot: corpusRoot,
          opensHome: true,
          surface: .home,
          recordsHistory: true
        )
        return
      }
      let file = await Task.detached(priority: .userInitiated) {
        Self.corpusFileOffMain(for: url, corpusRoot: corpusRoot)
      }.value
      guard !Task.isCancelled,
            dailyNoteNavigationGeneration == generation,
            isCurrentDocumentCorpusContext(context)
      else { return }
      homeActivationTask = nil
      currentHomeDailyNotePath = file.path
      upsertCorpusFile(file)
      let thread = AIChatThreadRecord(
        title: file.name,
        file: file.path,
        line: 1,
        zone: file.directory.isEmpty ? "daily" : file.directory,
        modifiedAt: file.modifiedAt,
        idValue: nil
      )
      let location = WorkspaceLocation.aiChatThreadRecord(thread)
      if !isCurrentNavigationDestination(location: location, surface: .home, mode: .page)
        || expandedWorkspaceSurface != nil
        || isWorkspaceSurfacePaneClosed
        || isWorkspaceDetailPaneClosed
        || isWorkspaceDetailPaneExpanded {
        recordCurrentNavigationDestination()
      }
      selectedCorpusFileID = file.id
      selectedAIChatThreadRecordID = nil
      expandedWorkspaceSurface = nil
      isWorkspaceSurfacePaneClosed = false
      isWorkspaceDetailPaneClosed = false
      isWorkspaceDetailPaneExpanded = false
      activateDetailLocation(location, mode: .page, surface: .home, recordsHistory: false)
      statusText = "Home"
    } catch {
      guard !Task.isCancelled,
            dailyNoteNavigationGeneration == generation,
            isCurrentDocumentCorpusContext(context)
      else { return }
      homeActivationTask = nil
      errorText = error.localizedDescription
      statusText = "Could not open \(url.lastPathComponent)"
    }
  }

  public func createMissingDailyNote() {
    guard !isCreatingMissingDailyNote,
          let missingDailyNote,
          let corpusRoot,
          let context = captureDocumentCorpusContext()
    else { return }

    let url = URL(fileURLWithPath: missingDailyNote.file).standardizedFileURL
    if selectedSurface != missingDailyNote.surface {
      selectedSurface = missingDailyNote.surface
    }
    let generation = supersedeDailyNoteNavigation()
    isCreatingMissingDailyNote = true
    if missingDailyNote.opensHome {
      homeActivationTask = Task { @MainActor [weak self] in
        guard let self else { return }
        defer { self.isCreatingMissingDailyNote = false }
        await self.finishOpeningHome(
          url: url,
          corpusRoot: corpusRoot,
          context: context,
          generation: generation,
          allowsCreation: true
        )
      }
    } else {
      dailyNoteActivationTask = Task { @MainActor [weak self] in
        guard let self else { return }
        defer { self.isCreatingMissingDailyNote = false }
        await self.openDailyNote(
          at: url,
          corpusRoot: corpusRoot,
          context: context,
          generation: generation,
          allowsCreation: true
        )
      }
    }
  }

  public func ensureHomeDetailReady() {
    if expandedWorkspaceSurface != nil { expandedWorkspaceSurface = nil }
    if isWorkspaceSurfacePaneClosed { isWorkspaceSurfacePaneClosed = false }
    if isWorkspaceDetailPaneClosed { isWorkspaceDetailPaneClosed = false }
    if isWorkspaceDetailPaneExpanded { isWorkspaceDetailPaneExpanded = false }
    guard isTodayHomeDetailSelected else {
      guard homeActivationTask == nil else { return }
      openHome()
      return
    }
  }

  private var isTodayHomeDetailSelected: Bool {
    if selectedSurface == .home,
       missingDailyNote?.opensHome == true {
      return true
    }
    guard selectedSurface == .home,
          selectedEntrySourceMode == .page,
          let selectedLocation,
          let currentHomeDailyNotePath
    else {
      return false
    }
    return URL(fileURLWithPath: selectedLocation.file).standardizedFileURL.path
      == currentHomeDailyNotePath
  }

  public var canStartAIChatVoiceNoteRecording: Bool {
    !isRecordingAIChatVoiceNote
      && !isTranscribingAIChatVoiceNote
      && !isRecordingMeeting
      && !isProcessingMeeting
  }

  public func toggleAIChatVoiceNoteRecording() async {
    if isRecordingAIChatVoiceNote {
      await stopAIChatVoiceNoteRecording(action: .insertIntoComposer)
    } else {
      await startAIChatVoiceNoteRecording()
    }
  }

  public func startAIChatVoiceNoteRecording() async {
    guard !isRecordingAIChatVoiceNote else { return }
    guard !isTranscribingAIChatVoiceNote else {
      aiChatVoiceStatusText = "Finish transcribing the current dictation first."
      aiChatStatusText = aiChatVoiceStatusText
      return
    }
    guard !isRecordingMeeting && !isProcessingMeeting else {
      aiChatVoiceStatusText = "Finish the current meeting recording first."
      aiChatStatusText = aiChatVoiceStatusText
      return
    }

    ensureAIChatThread()
    guard let threadID = selectedAIChatThreadID,
          let thread = aiChatThreads.first(where: { $0.id == threadID })
    else {
      aiChatVoiceStatusText = "Open an AI chat before dictating."
      aiChatStatusText = aiChatVoiceStatusText
      return
    }
    let origin = AIChatDictationOrigin(
      threadID: threadID,
      threadTitle: thread.title,
      runtime: thread.runtime,
      workspaceContext: threadScopedAIChatWorkspaceContext(for: thread),
      context: captureAIChatCorpusContext()
    )

    let audioURL = Self.aiChatVoiceNoteURL()
    do {
      activeAIChatDictationOrigin = origin
      try await aiChatVoiceRecorder.startRecording(to: audioURL)
      activeAIChatVoiceNoteURL = audioURL
      isRecordingAIChatVoiceNote = true
      aiChatVoiceStatusText = "Recording dictation for \(origin.threadTitle)..."
      aiChatStatusText = aiChatVoiceStatusText
      startAIChatVoiceMetering()
    } catch {
      activeAIChatVoiceNoteURL = nil
      activeAIChatDictationOrigin = nil
      isRecordingAIChatVoiceNote = false
      stopAIChatVoiceMetering()
      errorText = error.localizedDescription
      aiChatVoiceStatusText = "Dictation failed: \(error.localizedDescription)"
      aiChatStatusText = aiChatVoiceStatusText
    }
  }

  public func stopAIChatVoiceNoteRecording(
    action: AIChatDictationCompletionAction = .insertIntoComposer
  ) async {
    guard let audioURL = activeAIChatVoiceNoteURL,
          let origin = activeAIChatDictationOrigin
    else {
      aiChatVoiceStatusText = "No active AI chat dictation recording."
      aiChatStatusText = aiChatVoiceStatusText
      return
    }
    defer { activeAIChatDictationOrigin = nil }

    let duration: TimeInterval
    do {
      duration = try aiChatVoiceRecorder.stopRecording()
    } catch {
      activeAIChatVoiceNoteURL = nil
      activeAIChatDictationOrigin = nil
      isRecordingAIChatVoiceNote = false
      isTranscribingAIChatVoiceNote = false
      stopAIChatVoiceMetering()
      stopAIChatVoiceTranscriptionProgress()
      reportFailedAIChatDictation(
        audioURL: audioURL,
        message: "Dictation stop failed: \(error.localizedDescription)"
      )
      return
    }
    activeAIChatVoiceNoteURL = nil
    isRecordingAIChatVoiceNote = false
    stopAIChatVoiceMetering()
    await finishAIChatDictation(audioURL: audioURL, duration: duration, origin: origin, action: action)
  }

  func finishAIChatDictationForTesting(
    audioURL: URL,
    duration: TimeInterval,
    threadID: UUID
  ) async {
    guard let thread = aiChatThreads.first(where: { $0.id == threadID }) else { return }
    let origin = AIChatDictationOrigin(
      threadID: threadID,
      threadTitle: thread.title,
      runtime: thread.runtime,
      workspaceContext: threadScopedAIChatWorkspaceContext(for: thread),
      context: captureAIChatCorpusContext()
    )
    await finishAIChatDictation(
      audioURL: audioURL,
      duration: duration,
      origin: origin,
      action: .insertIntoComposer
    )
  }

  /// Keeps the recording of a dictation that produced no text and surfaces
  /// the failure as a visible error, so a long dictation is never lost.
  private func reportFailedAIChatDictation(audioURL: URL, message: String) {
    var visibleMessage = message
    if let keptURL = Self.retainFailedAIChatDictationAudio(
      audioURL,
      in: aiChatDictationRecoveryDirectory
    ) {
      visibleMessage += " The recording was kept at \(keptURL.path)."
    }
    errorText = visibleMessage
    aiChatVoiceStatusText = visibleMessage
    aiChatStatusText = visibleMessage
  }

  nonisolated static var defaultAIChatDictationRecoveryDirectory: URL {
    FileManager.default.homeDirectoryForCurrentUser
      .appendingPathComponent("Library/Application Support/org2/failed-dictations", isDirectory: true)
  }

  nonisolated static func retainFailedAIChatDictationAudio(_ audioURL: URL, in directory: URL) -> URL? {
    let fileManager = FileManager.default
    guard fileManager.fileExists(atPath: audioURL.path) else { return nil }
    let formatter = DateFormatter()
    formatter.locale = Locale(identifier: "en_US_POSIX")
    formatter.dateFormat = "yyyy-MM-dd-HHmmss"
    let ext = audioURL.pathExtension.isEmpty ? "wav" : audioURL.pathExtension
    let destination = directory.appendingPathComponent(
      "dictation-\(formatter.string(from: Date()))-\(UUID().uuidString.prefix(8)).\(ext)"
    )
    do {
      try fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
      try fileManager.moveItem(at: audioURL, to: destination)
      return destination
    } catch {
      return nil
    }
  }

  private func finishAIChatDictation(
    audioURL: URL,
    duration: TimeInterval,
    origin: AIChatDictationOrigin,
    action: AIChatDictationCompletionAction
  ) async {
    guard duration >= 0.2 else {
      try? FileManager.default.removeItem(at: audioURL)
      aiChatVoiceStatusText = "Dictation was too short."
      aiChatStatusText = aiChatVoiceStatusText
      return
    }

    isTranscribingAIChatVoiceNote = true
    aiChatVoiceStatusText = "Transcribing dictation for \(origin.threadTitle) locally..."
    aiChatStatusText = aiChatVoiceStatusText
    startAIChatVoiceTranscriptionProgress(audioDuration: duration)

    let transcript = await transcribeAudioForAIChatVoiceNote(audioURL)
    isTranscribingAIChatVoiceNote = false
    stopAIChatVoiceTranscriptionProgress()
    let dictatedText = transcript.text.trimmingCharacters(in: .whitespacesAndNewlines)
    guard transcript.status == .complete, !dictatedText.isEmpty else {
      let suffix = transcript.errorMessage.map { ": \($0)" } ?? ""
      reportFailedAIChatDictation(
        audioURL: audioURL,
        message: "Dictation transcription \(transcript.status.label)\(suffix)."
      )
      return
    }
    // Text is in hand; the audio is no longer needed.
    try? FileManager.default.removeItem(at: audioURL)
    guard isCurrentAIChatCorpusContext(origin.context) else {
      returnAIChatDictationToOriginComposer(dictatedText, origin: origin)
      return
    }

    switch action {
    case .insertIntoComposer:
      if insertAIChatDictationIntoDraft(dictatedText, in: origin.threadID) {
        aiChatVoiceStatusText = "Dictation added to \(origin.threadTitle)."
      } else {
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(dictatedText, forType: .string)
        aiChatVoiceStatusText =
          "The original AI chat is no longer available. The dictation was copied to the clipboard."
        errorText = aiChatVoiceStatusText
      }
      aiChatStatusText = aiChatVoiceStatusText
    case .send:
      aiChatVoiceStatusText = "Sending dictated note in \(origin.threadTitle)..."
      aiChatStatusText = aiChatVoiceStatusText
      let accepted = await sendAIChatDictation(
        dictatedText,
        to: origin.threadID,
        workspaceContext: origin.workspaceContext,
        context: origin.context
      )
      guard isCurrentAIChatCorpusContext(origin.context) else {
        if !accepted {
          returnAIChatDictationToOriginComposer(dictatedText, origin: origin)
        }
        return
      }
      if !accepted {
        returnAIChatDictationToOriginComposer(dictatedText, origin: origin)
        aiChatVoiceStatusText = "Dictation could not be sent and was returned to \(origin.threadTitle)'s composer."
        aiChatStatusText = aiChatVoiceStatusText
      }
    }
  }

  public func chooseAIChatImageAttachments() {
    chooseAIChatAttachments(allowedContentTypes: [.image])
  }

  public func chooseAIChatAttachments() {
    chooseAIChatAttachments(allowedContentTypes: nil)
  }

  private func chooseAIChatAttachments(allowedContentTypes: [UTType]?) {
    if let aiChatAttachmentPanel {
      NSApplication.shared.activate(ignoringOtherApps: true)
      aiChatAttachmentPanel.makeKeyAndOrderFront(nil)
      return
    }
    let panel = NSOpenPanel()
    panel.allowsMultipleSelection = true
    panel.canChooseDirectories = false
    panel.canChooseFiles = true
    if let allowedContentTypes {
      panel.allowedContentTypes = allowedContentTypes
    }
    panel.prompt = "Attach"
    panel.message = "Choose files or images to add to this message."
    aiChatAttachmentPanel = panel
    panel.begin { [weak self, weak panel] response in
      let selectedURLs = response == .OK ? panel?.urls ?? [] : []
      Task { @MainActor [weak self, weak panel] in
        guard let self, self.aiChatAttachmentPanel === panel else { return }
        self.aiChatAttachmentPanel = nil
        guard response == .OK else { return }
        self.enqueueAIChatAttachmentPreparation(
          urls: selectedURLs,
          imagesOnly: allowedContentTypes == [.image]
        )
      }
    }
  }

  private func enqueueAIChatAttachmentPreparation(
    urls: [URL],
    imagesOnly: Bool
  ) {
    guard !urls.isEmpty else { return }
    let originThreadID = selectedAIChatThreadID
    let originContext = captureAIChatCorpusContext()
    let previous = aiChatAttachmentPreparationTail
    aiChatStatusText = urls.count == 1
      ? "Attaching \(urls[0].lastPathComponent)…"
      : "Attaching \(urls.count) files…"
    aiChatAttachmentPreparationTail = Task { @MainActor [weak self] in
      _ = await previous?.value
      guard let self else { return }
      let results = await Task.detached(priority: .userInitiated) {
        urls.map { url in
          do {
            let attachment = try imagesOnly
              ? Self.aiChatImageAttachment(from: url)
              : Self.aiChatAttachment(from: url)
            return AIChatAttachmentPreparationResult(
              fileName: url.lastPathComponent,
              attachment: attachment,
              errorDescription: nil
            )
          } catch {
            return AIChatAttachmentPreparationResult(
              fileName: url.lastPathComponent,
              attachment: nil,
              errorDescription: error.localizedDescription
            )
          }
        }
      }.value
      self.finishAIChatAttachmentPreparation(
        results,
        originThreadID: originThreadID,
        originContext: originContext
      )
    }
  }

  private func finishAIChatAttachmentPreparation(
    _ results: [AIChatAttachmentPreparationResult],
    originThreadID: UUID?,
    originContext: AIChatCorpusContextToken
  ) {
    let isCurrentComposer = isCurrentAIChatAttachmentContext(originContext)
      && selectedAIChatThreadID == originThreadID
    let originAttachments: [AIChatAttachment]
    if let originThreadID {
      let key = aiChatComposerKey(for: originThreadID, context: originContext)
      originAttachments = aiChatAttachmentsByComposerKey[key]
        ?? (isCurrentComposer ? aiChatPendingAttachments : [])
    } else {
      originAttachments = isCurrentComposer ? aiChatPendingAttachments : []
    }

    var attachments = originAttachments
    for result in results {
      if let attachment = result.attachment {
        guard !attachments.contains(where: { $0.hasSameContent(as: attachment) }) else { continue }
        attachments.append(attachment)
      } else if let errorDescription = result.errorDescription {
        errorText = errorDescription
        aiChatStatusText = "Could not attach \(result.fileName)"
      }
    }

    if let originThreadID {
      cacheAIChatAttachments(attachments, for: originThreadID, context: originContext)
    }
    guard isCurrentComposer else { return }
    aiChatPendingAttachments = attachments
    if !attachments.isEmpty {
      aiChatStatusText = "\(attachments.count) attachment\(attachments.count == 1 ? "" : "s") ready"
    }
  }

  func waitForAIChatAttachmentPreparationForTesting() async {
    await aiChatAttachmentPreparationTail?.value
  }

  func enqueueAIChatAttachmentPreparationForTesting(
    urls: [URL],
    imagesOnly: Bool = false
  ) {
    enqueueAIChatAttachmentPreparation(urls: urls, imagesOnly: imagesOnly)
  }

  func advanceAIChatTranscriptLoadGenerationForTesting() {
    aiChatTranscriptLoadGeneration &+= 1
  }

  public func attachAIChatImages(urls: [URL]) {
    addAIChatAttachments(urls: urls, makeAttachment: Self.aiChatImageAttachment)
  }

  public func attachAIChatFiles(urls: [URL]) {
    addAIChatAttachments(urls: urls, makeAttachment: Self.aiChatAttachment)
  }

  private func addAIChatAttachments(
    urls: [URL],
    makeAttachment: (URL) throws -> AIChatAttachment
  ) {
    var attachments = aiChatPendingAttachments
    for url in urls {
      do {
        let attachment = try makeAttachment(url)
        guard !attachments.contains(where: { $0.hasSameContent(as: attachment) }) else {
          continue
        }
        attachments.append(attachment)
      } catch {
        errorText = error.localizedDescription
        aiChatStatusText = "Could not attach \(url.lastPathComponent)"
      }
    }
    aiChatPendingAttachments = attachments
    if let selectedAIChatThreadID {
      cacheAIChatAttachments(attachments, for: selectedAIChatThreadID)
    }
    if !attachments.isEmpty {
      aiChatStatusText = "\(attachments.count) attachment\(attachments.count == 1 ? "" : "s") ready"
    }
  }

  @discardableResult
  public func attachAIChatAttachment(data: Data, fileName: String, mimeType: String) -> Bool {
    do {
      let attachment = try Self.aiChatAttachment(
        data: data,
        fileName: fileName,
        mimeType: mimeType
      )
      guard !aiChatPendingAttachments.contains(where: {
        $0.hasSameContent(as: attachment)
      }) else { return true }
      aiChatPendingAttachments.append(attachment)
      if let selectedAIChatThreadID {
        cacheAIChatAttachments(aiChatPendingAttachments, for: selectedAIChatThreadID)
      }
      aiChatStatusText = "\(aiChatPendingAttachments.count) attachment\(aiChatPendingAttachments.count == 1 ? "" : "s") ready"
      return true
    } catch {
      errorText = error.localizedDescription
      aiChatStatusText = "Could not attach \(fileName)"
      return false
    }
  }

  public func removeAIChatPendingAttachment(_ attachment: AIChatAttachment) {
    aiChatPendingAttachments.removeAll { $0.id == attachment.id }
    if let selectedAIChatThreadID {
      cacheAIChatAttachments(aiChatPendingAttachments, for: selectedAIChatThreadID)
    }
  }

  public func clearAIChatPendingAttachments() {
    aiChatPendingAttachments = []
    if let selectedAIChatThreadID {
      cacheAIChatAttachments([], for: selectedAIChatThreadID)
    }
  }

  public func sendAIChatMessage() async {
    let text = aiChatDraft.trimmingCharacters(in: .whitespacesAndNewlines)
    let attachments = aiChatPendingAttachments
    guard !text.isEmpty || !attachments.isEmpty else { return }
    ensureAIChatThread()
    guard let threadID = selectedAIChatThreadID else { return }
    let context = captureAIChatCorpusContext()
    let submission = captureAIChatComposerSubmission(
      threadID: threadID,
      draft: aiChatDraft,
      attachments: attachments,
      context: context
    )
    let result = submitAIChatMessage(
      text,
      attachments: attachments,
      in: threadID,
      context: context
    )
    let outcome = await awaitAIChatEnqueueAndImmediateDrain(result)
    if case .enqueued = outcome {
      clearAcceptedAIChatComposerSubmission(submission)
    } else {
      preserveRejectedAIChatComposerSubmission(submission)
    }
  }

  public func sendAIChatMessage(text rawText: String) async {
    let text = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !text.isEmpty else { return }
    ensureAIChatThread()
    guard let threadID = selectedAIChatThreadID else { return }
    let context = captureAIChatCorpusContext()
    let submission = captureAIChatComposerSubmission(
      threadID: threadID,
      draft: rawText,
      attachments: [],
      context: context
    )
    let result = submitAIChatMessage(
      text,
      attachments: [],
      in: threadID,
      context: context
    )
    let outcome = await awaitAIChatEnqueueAndImmediateDrain(result)
    if case .enqueued = outcome {
      clearAcceptedAIChatComposerSubmission(submission)
    } else {
      preserveRejectedAIChatComposerSubmission(submission)
    }
  }

  @discardableResult
  func insertAIChatDictationIntoDraft(_ rawText: String, in threadID: UUID) -> Bool {
    let dictatedText = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !dictatedText.isEmpty,
          aiChatThreads.contains(where: { $0.id == threadID })
    else { return false }

    let updatedDraft = Self.aiChatDraftByAppendingDictation(
      existing: aiChatDraft(for: threadID),
      dictatedText: dictatedText
    )
    cacheAIChatDraft(updatedDraft, for: threadID)
    if selectedAIChatThreadID == threadID {
      aiChatDraft = updatedDraft
    }
    return true
  }

  @discardableResult
  func sendAIChatDictation(
    _ rawText: String,
    to threadID: UUID,
    workspaceContext: AIChatWorkspaceContext? = nil
  ) async -> Bool {
    await sendAIChatDictation(
      rawText,
      to: threadID,
      workspaceContext: workspaceContext,
      context: captureAIChatCorpusContext()
    )
  }

  @discardableResult
  private func sendAIChatDictation(
    _ rawText: String,
    to threadID: UUID,
    workspaceContext: AIChatWorkspaceContext?,
    context: AIChatCorpusContextToken
  ) async -> Bool {
    let contextToken = context
    guard isCurrentAIChatCorpusContext(contextToken) else { return false }
    let dictatedText = rawText.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !dictatedText.isEmpty,
          let thread = aiChatThreads.first(where: { $0.id == threadID }),
          !thread.isSettled
    else { return false }

    let existingDraft = aiChatDraft(for: threadID)
    let text = Self.aiChatDraftByAppendingDictation(
      existing: existingDraft,
      dictatedText: dictatedText
    )
    let submission = captureAIChatComposerSubmission(
      threadID: threadID,
      draft: existingDraft,
      attachments: [],
      context: contextToken
    )
    let context = workspaceContext ?? threadScopedAIChatWorkspaceContext(for: thread)
    let result = submitAIChatMessage(
      text,
      attachments: [],
      in: threadID,
      workspaceContext: context,
      context: contextToken
    )
    let outcome = await awaitAIChatEnqueueAndImmediateDrain(result)
    if case .enqueued = outcome {
      clearAcceptedAIChatComposerSubmission(submission)
      return true
    }
    preserveRejectedAIChatComposerSubmission(submission)
    return false
  }

  private func returnAIChatDictationToOriginComposer(
    _ dictatedText: String,
    origin: AIChatDictationOrigin
  ) {
    let existing = aiChatDraft(for: origin.threadID, context: origin.context)
    let updated = Self.aiChatDraftByAppendingDictation(
      existing: existing,
      dictatedText: dictatedText
    )
    cacheAIChatDraft(updated, for: origin.threadID, context: origin.context)
    if isCurrentAIChatCorpusContext(origin.context),
       selectedAIChatThreadID == origin.threadID {
      aiChatDraft = updated
    }
  }

