  @discardableResult
  public func forkAIChatThread(
    _ id: UUID,
    selectsThread: Bool = true,
    asSharedRoom: Bool? = nil
  ) async -> UUID? {
    guard await hydrateAIChatThreadIfNeeded(id) != nil else { return nil }
    let linkedProjects = projectNotes.filter { $0.contains(id) }
    guard let forkedID = forkHydratedAIChatThread(
      id,
      selectsThread: selectsThread,
      asSharedRoom: asSharedRoom
    ) else { return nil }
    for project in linkedProjects {
      await updateProject(project, threadID: forkedID)
    }
    return forkedID
  }

  private func forkHydratedAIChatThread(
    _ id: UUID,
    selectsThread: Bool = true,
    asSharedRoom: Bool? = nil
  ) -> UUID? {
    guard !unloadedAIChatThreadIDs.contains(id),
          let source = aiChatThreads.first(where: { $0.id == id })
    else {
      return nil
    }
    let sharedRoom = asSharedRoom ?? source.isSharedRoom
    let now = Date()
    let forkedMessages = Self.forkedAIChatMessages(
      source.messages,
      sourceRuntime: source.runtime,
      preservesRoomMetadata: source.isSharedRoom
    )
    let titlePrefix = sharedRoom && !source.isSharedRoom ? "Shared" : "Fork"
    let roomModels: AIChatRoomModelSelection
    let roomModelsByDestination: [String: String]
    let roomReasoningEffortsByDestination: [String: String]
    let roomDestinationIDs: [String]
    let roomDefaultDestinationID: String?
    if source.isSharedRoom {
      roomModels = source.roomModels
      roomModelsByDestination = source.roomModelsByDestination
      roomReasoningEffortsByDestination = source.roomReasoningEffortsByDestination
      roomDestinationIDs = source.roomDestinationIDs
      roomDefaultDestinationID = source.roomDefaultDestinationID
    } else {
      roomModels = AIChatRoomModelSelection().replacingModel(source.model, for: source.runtime)
      roomModelsByDestination = source.model.map { [source.destinationID: $0] } ?? [:]
      roomReasoningEffortsByDestination = source.reasoningEffort.map { [source.destinationID: $0] } ?? [:]
      roomDestinationIDs = [source.destinationID]
      // Pinging another agent from a thread keeps the original agent as
      // the room's default; only that one message goes to the new agent.
      roomDefaultDestinationID = source.destinationID
    }
    let forked = AIChatThread(
      title: Self.normalizedAIChatThreadTitle("\(titlePrefix): \(source.title)"),
      createdAt: now,
      updatedAt: now,
      runtime: source.runtime,
      destinationID: source.destinationID,
      sessionKey: Self.makeOpenClawSessionKey(agentID: openClawAgentID),
      runtimeThreadID: nil,
      model: sharedRoom ? nil : source.model,
      reasoningEffort: sharedRoom ? nil : source.reasoningEffort,
      messages: forkedMessages,
      isPinned: false,
      isArchived: false,
      settledAt: nil,
      unreadMessageCount: 0,
      resource: nil,
      pendingTurn: nil,
      isSharedRoom: sharedRoom,
      roomAudience: .thread,
      roomModels: roomModels,
      roomDestinationIDs: roomDestinationIDs,
      roomModelsByDestination: roomModelsByDestination,
      roomReasoningEffortsByDestination: roomReasoningEffortsByDestination,
      roomDefaultDestinationID: roomDefaultDestinationID,
      roomAgentTurnLimit: source.isSharedRoom ? source.roomAgentTurnLimit : nil,
      agentRef: source.agentRef
    )
    aiChatThreads.insert(forked, at: 0)
    advanceAIChatMessageRevision(
      for: forked.id,
      tracksPersistence: true,
      makesColdPlaceholderAuthoritative: true
    )
    if selectsThread {
      selectAIChatThread(forked.id, persistsSelection: false)
      persistSelectedAIChatThread()
      aiChatStatusText = sharedRoom && !source.isSharedRoom
        ? "Forked into a shared room"
        : "Forked \(source.title)"
    }
    persistAIChatTranscript()
    return forked.id
  }

  nonisolated private static func forkedAIChatMessages(
    _ messages: [AIChatMessage],
    sourceRuntime: AIChatRuntime,
    preservesRoomMetadata: Bool
  ) -> [AIChatMessage] {
    var roundIDs: [UUID: UUID] = [:]
    return messages.map { message in
      let roomRoundID = message.roomRoundID.map { existing in
        if let mapped = roundIDs[existing] { return mapped }
        let mapped = UUID()
        roundIDs[existing] = mapped
        return mapped
      }
      return AIChatMessage(
        role: message.role,
        content: message.content,
        attachments: message.attachments,
        createdAt: message.createdAt,
        changeSummary: message.changeSummary,
        responseTrace: message.responseTrace,
        deliveryStatus: .sent,
        deliveryKind: .turn,
        authorRuntime: message.role == .user
          ? nil
          : (message.authorRuntime ?? sourceRuntime),
        authorLabel: message.authorLabel,
        authorAgentRef: message.authorAgentRef,
        source: message.source,
        audience: preservesRoomMetadata ? message.audience : nil,
        targetRuntime: preservesRoomMetadata ? message.targetRuntime : nil,
        authorDestinationID: message.authorDestinationID,
        audienceDestinationIDs: preservesRoomMetadata ? message.audienceDestinationIDs : [],
        targetDestinationID: preservesRoomMetadata ? message.targetDestinationID : nil,
        isRoomDispatchCopy: preservesRoomMetadata && message.isRoomDispatchCopy,
        roomRoundID: preservesRoomMetadata ? roomRoundID : nil,
        provenance: message.provenance
      )
    }
  }

  private func aiChatDestinationThreadID(
    for text: String,
    sourceThreadID: UUID,
    selectsFork: Bool
  ) -> UUID {
    guard let source = aiChatThreads.first(where: { $0.id == sourceThreadID }),
          !source.isSharedRoom
    else {
      return sourceThreadID
    }
    let routing = AIChatDestinationRouting(
      text,
      destinations: enabledAIChatDestinations
    )
    guard routing.destinationIDs.contains(where: { $0 != source.destinationID }) else {
      return sourceThreadID
    }
    let forkedID = forkHydratedAIChatThread(
      sourceThreadID,
      selectsThread: selectsFork,
      asSharedRoom: true
    ) ?? sourceThreadID
    guard forkedID != sourceThreadID,
          let index = aiChatThreads.firstIndex(where: { $0.id == forkedID })
    else { return forkedID }
    let participants = ([source.destinationID] + routing.destinationIDs).reduce(into: [String]()) {
      if !$0.contains($1) { $0.append($1) }
    }
    aiChatThreads[index] = aiChatThreads[index]
      .replacingAIChatMetadata(roomDestinationIDs: participants)
    persistAIChatTranscript()
    return forkedID
  }

  @discardableResult
  private func createAIChatThread(
    id: UUID = UUID(),
    title: String,
    statusText: String,
    resource: AIChatResourceReference? = nil,
    sessionKey: String? = nil,
    runtime: AIChatRuntime = .openClaw,
    destinationID: String? = nil,
    isSharedRoom: Bool = false,
    roomAudience: AIChatAudience = .thread,
    inheritsChatConfiguration: Bool = true,
    modelOverride: String? = nil,
    reasoningEffortOverride: String? = nil,
    defersPersistence: Bool = false,
    selectsThread: Bool = true
  ) -> AIChatThread {
    let resolvedDestinationID = destinationID
      ?? AIChatDestinationConfiguration.defaultID(for: runtime)
    let lastConfiguration: AIChatLastConfiguration?
    if isSharedRoom {
      lastConfiguration = nil
    } else if inheritsChatConfiguration {
      lastConfiguration = preferredAIChatConfiguration(forDestinationID: resolvedDestinationID)
    } else {
      // Automations use configured destination defaults, not unrelated chat
      // choices that can silently require a live Gateway and prevent fallback.
      let model = modelOverride?.trimmingCharacters(in: .whitespacesAndNewlines)
        ?? aiChatDestination(id: resolvedDestinationID)?.model
      let reasoningEffort = reasoningEffortOverride?
        .trimmingCharacters(in: .whitespacesAndNewlines)
      lastConfiguration = model != nil || reasoningEffort != nil
        ? AIChatLastConfiguration(model: model, reasoningEffort: reasoningEffort)
        : nil
    }
    let initialRoomDestinationIDs = isSharedRoom
      ? enabledAIChatDestinations.map(\.id)
      : []
    let thread = AIChatThread(
      id: id,
      title: title,
      runtime: runtime,
      destinationID: resolvedDestinationID,
      sessionKey: sessionKey ?? Self.makeOpenClawSessionKey(agentID: openClawAgentID),
      model: lastConfiguration?.model,
      reasoningEffort: lastConfiguration?.reasoningEffort,
      resource: resource,
      isSharedRoom: isSharedRoom,
      roomAudience: roomAudience,
      roomDestinationIDs: initialRoomDestinationIDs
    )
    insertNewAIChatThreadIncrementally(thread)
    advanceAIChatMessageRevision(
      for: thread.id,
      tracksPersistence: true,
      makesColdPlaceholderAuthoritative: true
    )
    if selectsThread {
      selectAIChatThread(thread.id, persistsSelection: false)
      persistSelectedAIChatThread()
    }
    if defersPersistence {
      scheduleAIChatTranscriptPersistenceAfterInteraction()
    } else {
      persistAIChatTranscript()
    }
    if selectsThread {
      aiChatStatusText = statusText
    }
    return thread
  }

  private func prepareAIChatThread(mode: AIChatThreadMode, title: String, statusText: String) {
    guard mode == .newThread else {
      ensureAIChatThread()
      return
    }
    let runtime = selectedAIChatThread?.runtime ?? .openClaw
    createAIChatThread(
      title: Self.normalizedAIChatThreadTitle(title),
      statusText: statusText.replacingOccurrences(of: "OpenClaw", with: runtime.title),
      runtime: runtime
    )
  }

  /// A chosen brief harness, model, or reasoning level cannot retarget an
  /// existing conversation, so it always gets its own brief thread.
  public var nodeBriefStartsNewThread: Bool {
    aiChatBriefsStartNewThread || !nodeBriefConfiguration.isDefault
  }

  /// Destination the next brief will run on, after validating the saved one.
  public var nodeBriefDestination: AIChatDestinationConfiguration {
    if let id = nodeBriefConfiguration.destinationID,
       let destination = enabledAIChatDestinations.first(where: { $0.id == id }) {
      return destination
    }
    return selectedAIChatDestination
  }

  /// Models for the brief options picker: cached catalog first, then a live
  /// lookup against the destination. Failures return an empty list so the
  /// user can still type a model ID.
  public func nodeBriefModelOptions(forDestinationID destinationID: String) async -> [AIChatModelOption] {
    if let cached = aiChatConfigurationCatalogCache[destinationID]?.models, !cached.isEmpty {
      return cached
    }
    guard let models = try? await modelsForAIChatDestination(destinationID), !models.isEmpty else {
      return []
    }
    cacheAIChatModelCatalog(destinationID: destinationID, models: models)
    return models
  }

  private func prepareAIChatThreadForNodeBrief(title: String) {
    guard nodeBriefStartsNewThread else { return }
    let configuration = nodeBriefConfiguration
    if !configuration.isDefault {
      let destination = nodeBriefDestination
      createAIChatThread(
        title: Self.normalizedAIChatThreadTitle("Brief: \(title)"),
        statusText: "New \(destination.title) brief chat",
        runtime: destination.runtime,
        destinationID: destination.id,
        inheritsChatConfiguration: configuration.model == nil && configuration.reasoningEffort == nil,
        modelOverride: configuration.model,
        reasoningEffortOverride: configuration.reasoningEffort
      )
      return
    }
    prepareAIChatThread(
      mode: .newThread,
      title: "Brief: \(title)",
      statusText: "New OpenClaw brief chat"
    )
  }

  public func selectAIChatThread(_ id: UUID) {
    guard aiChatThreads.contains(where: { $0.id == id }) else { return }
    sidebarPromotedAIChatThreadID = nil
    if selectedAIChatThreadID != id {
      recordCurrentNavigationDestination()
    }
    selectAIChatThread(id, persistsSelection: true)
  }

  /// Title of an existing chat thread, for rendering a pasted thread ID as a
  /// link. Unknown IDs return nil and stay plain text.
  public func aiChatThreadLinkTitle(_ id: UUID) -> String? {
    guard let thread = aiChatThreads.first(where: { $0.id == id }) else { return nil }
    let title = thread.title.trimmingCharacters(in: .whitespacesAndNewlines)
    return title.isEmpty ? "Untitled chat" : title
  }

  public func openAIChatThreadLink(_ id: UUID) {
    guard aiChatThreads.contains(where: { $0.id == id }) else {
      statusText = "That chat thread is not available on this Mac"
      return
    }
    navigateToSurface(.aiChat)
    selectAIChatThread(id)
  }

  public func selectAIChatSearchResult(_ result: AIChatSearchResult) {
    navigateToSurface(.aiChat)
    selectAIChatThread(result.threadID)
    sidebarPromotedAIChatThreadID = result.threadID
    statusText = "Opened chat thread"
  }

  public func toggleAIChatThreadPin(_ id: UUID) {
    guard let index = aiChatThreads.firstIndex(where: { $0.id == id }) else { return }
    let thread = aiChatThreads[index]
    aiChatThreads[index] = thread.replacingAIChatMetadata(isPinned: !thread.isPinned)
    sortAIChatThreadsForDisplay()
    persistAIChatTranscript()
  }

  public func renameAIChatThread(_ id: UUID, title rawTitle: String) {
    let title = Self.normalizedAIChatThreadTitle(rawTitle)
    guard !title.isEmpty,
          let index = aiChatThreads.firstIndex(where: { $0.id == id })
    else { return }
    let thread = aiChatThreads[index]
    guard thread.title != title else { return }
    aiChatThreads[index] = thread.replacingAIChatMetadata(title: title)
    sortAIChatThreadsForDisplay()
    persistAIChatTranscript()
  }

  /// Whether the open conversation is settled. Drives the chat header's
  /// Settle/Reopen control, which works even when the thread is hard to find
  /// in the sidebar.
  public var selectedAIChatThreadIsSettled: Bool {
    selectedAIChatThread?.isSettled ?? false
  }

  /// Settles or reopens the open conversation from the chat pane. Settling
  /// from the pane keeps the thread open, so the control flips to Reopen
  /// instead of moving to (and risking a second click on) another thread.
  public func toggleSelectedAIChatThreadSettlement(at date: Date = Date()) {
    guard let thread = selectedAIChatThread else { return }
    if thread.isSettled {
      reopenAIChatThread(thread.id)
      aiChatStatusText = "Reopened \(thread.title)"
    } else {
      settleAIChatThread(thread.id, at: date, keepsSelection: true)
      aiChatStatusText = "Settled \(thread.title)"
    }
  }

  public func settleAIChatThread(_ id: UUID, at settledAt: Date = Date(), keepsSelection: Bool = false) {
    let visibleThreadsBeforeArchive = visibleAIChatThreads
    let visibleIndex = visibleThreadsBeforeArchive.firstIndex(where: { $0.id == id })
    let selectedThreadWasSettled = selectedAIChatThreadID.flatMap { selectedID in
      aiChatThreads.first(where: { $0.id == selectedID })?.isSettled
    } ?? false
    guard let index = aiChatThreads.firstIndex(where: { $0.id == id }),
          !aiChatThreads[index].isSettled
    else { return }
    let thread = aiChatThreads[index]
    var threads = aiChatThreads
    threads[index] = thread.replacingAIChatMetadata(
      isArchived: true,
      settledAt: .some(settledAt)
    )
    aiChatThreads = Self.sortedAIChatThreadsForDisplay(threads)
    lastArchivedAIChatThreadID = id
    scheduleAIChatTranscriptPersistenceAfterInteraction()

    if keepsSelection, selectedAIChatThreadID == id { return }
    if selectedAIChatThreadID == id || selectedThreadWasSettled {
      let remainingThreads = visibleAIChatThreads
      let replacementIndex = min(visibleIndex ?? 0, max(remainingThreads.count - 1, 0))
      if remainingThreads.indices.contains(replacementIndex) {
        let next = remainingThreads[replacementIndex]
        selectAIChatThread(next.id, persistsSelection: true)
      } else {
        createAIChatThread(runtime: thread.runtime)
      }
    }
  }

  nonisolated static func isAutomationAIChatThreadTitle(_ title: String) -> Bool {
    title.hasPrefix("Automation:")
  }

  /// Automation threads that "Mark All Automation Threads Read & Settled"
  /// would still change: unsettled ones that are not running, plus any with
  /// unread messages. The sidebar shows its inline settle-all row from this.
  public var actionableAutomationAIChatThreadCount: Int {
    aiChatThreads.reduce(into: 0) { count, thread in
      guard Self.isAutomationAIChatThreadTitle(thread.title) else { return }
      let isRunning = thread.pendingTurn != nil
        || aiChatSendingThreadIDs.contains(thread.id)
        || drainingAIChatThreadIDs.contains(thread.id)
      if (!thread.isSettled && !isRunning) || thread.unreadMessageCount != 0 {
        count += 1
      }
    }
  }

  /// Marks every "Automation: …" thread read and settles those not running,
  /// as one in-memory update with a single receipt write and one debounced
  /// transcript save, regardless of how many threads match.
  @discardableResult
  public func markAllAutomationAIChatThreadsReadAndSettled(at settledAt: Date = Date()) -> Int {
    var threads = aiChatThreads
    var automationThreads: [AIChatThread] = []
    var changedCount = 0
    for index in threads.indices {
      let thread = threads[index]
      guard Self.isAutomationAIChatThreadTitle(thread.title) else { continue }
      automationThreads.append(thread)
      let isRunning = thread.pendingTurn != nil
        || aiChatSendingThreadIDs.contains(thread.id)
        || drainingAIChatThreadIDs.contains(thread.id)
      let settles = !thread.isSettled && !isRunning
      guard settles || thread.unreadMessageCount != 0 else { continue }
      threads[index] = thread.replacingAIChatMetadata(
        isArchived: settles ? true : thread.isArchived,
        settledAt: .some(settles ? settledAt : thread.settledAt),
        unreadMessageCount: 0
      )
      changedCount += 1
    }
    aiChatReadState.markRead(automationThreads, transcriptURL: aiChatTranscriptURL)
    guard changedCount > 0 else {
      aiChatStatusText = automationThreads.isEmpty
        ? "No automation threads"
        : "Automation threads are already read and settled"
      return 0
    }
    aiChatThreads = Self.sortedAIChatThreadsForDisplay(threads)
    scheduleAIChatTranscriptPersistenceAfterInteraction()
    aiChatStatusText = changedCount == 1
      ? "Marked 1 automation thread read and settled"
      : "Marked \(changedCount) automation threads read and settled"
    return changedCount
  }

  public func reopenAIChatThread(_ id: UUID) {
    guard let index = aiChatThreads.firstIndex(where: { $0.id == id }),
          aiChatThreads[index].isSettled
    else { return }
    let thread = aiChatThreads[index]
    var threads = aiChatThreads
    threads[index] = thread.replacingAIChatMetadata(
      isArchived: false,
      settledAt: .some(nil)
    )
    aiChatThreads = Self.sortedAIChatThreadsForDisplay(threads)
    if lastArchivedAIChatThreadID == id {
      lastArchivedAIChatThreadID = nil
    }
    scheduleAIChatTranscriptPersistenceAfterInteraction()
  }

  public func undoLastAIChatThreadArchive() {
    guard let lastArchivedAIChatThreadID else { return }
    reopenAIChatThread(lastArchivedAIChatThreadID)
  }

  public func archiveAIChatThread(_ id: UUID) {
    settleAIChatThread(id)
  }

  public func restoreAIChatThread(_ id: UUID) {
    reopenAIChatThread(id)
  }

  public func setAIChatAutoSettleInterval(_ interval: AIChatAutoSettleInterval) {
    aiChatThreadSettlementSettings = AIChatThreadSettlementSettings(
      autoSettleAfterSeconds: interval.seconds
    )
    autoSettleAIChatThreads(shouldPersist: false)
    persistAIChatTranscript()
  }

  @discardableResult
  public func autoSettleAIChatThreads(
    now: Date = Date(),
    shouldPersist: Bool = true
  ) -> [UUID] {
    let selectedID = selectedAIChatThreadID
    var settledIDs: [UUID] = []
    let updatedThreads = aiChatThreads.map { thread in
      guard Self.canAutoSettleAIChatThread(
        thread,
        settings: aiChatThreadSettlementSettings,
        selectedThreadID: selectedID,
        now: now
      ) else {
        return thread
      }
      settledIDs.append(thread.id)
      return thread.replacingAIChatMetadata(
        isArchived: true,
        settledAt: .some(now)
      )
    }
    if !settledIDs.isEmpty {
      aiChatThreads = Self.sortedAIChatThreadsForDisplay(updatedThreads)
      if shouldPersist {
        scheduleAIChatTranscriptPersistenceAfterInteraction()
      }
    }
    return settledIDs
  }

  nonisolated static func canAutoSettleAIChatThread(
    _ thread: AIChatThread,
    settings: AIChatThreadSettlementSettings,
    selectedThreadID: UUID?,
    now: Date
  ) -> Bool {
    guard let interval = settings.autoSettleAfterSeconds,
          interval > 0,
          !thread.isSettled,
          thread.id != selectedThreadID,
          !thread.isPinned,
          thread.pendingTurn == nil,
          thread.unreadMessageCount == 0,
          !thread.hasUnresolvedLatestDelivery,
          thread.updatedAt <= now.addingTimeInterval(-interval)
    else {
      return false
    }
    return true
  }

  private func selectAIChatThread(_ id: UUID, persistsSelection: Bool) {
    guard let thread = aiChatThreads.first(where: { $0.id == id }) else {
      return
    }
    if let previousID = selectedAIChatThreadID, previousID != id {
      commitPendingAIChatHydration(for: previousID)
    }
    let requiresHydration = unloadedAIChatThreadIDs.contains(thread.id)
    let selectionChanged = selectedAIChatThreadID != thread.id
    saveAIChatComposerForSelectedThread()
    if selectionChanged {
      selectedAIChatThreadID = thread.id
    }
    touchHydratedAIChatThread(thread.id)
    openClawSessionKey = thread.sessionKey
    // Refreshing a hidden selection is not an acknowledgement of its replies.
    if persistsSelection || selectedSurface == .aiChat || isAIChatAssistantPresented {
      markAIChatThreadRead(thread.id)
    }
    restoreAIChatComposer(for: thread.id)
    syncSelectedAIChatSendState()
    aiChatConfigurationGeneration &+= 1
    if !applyCachedAIChatConfiguration(for: thread) {
      if !aiChatModelOptions.isEmpty { aiChatModelOptions = [] }
      if !aiChatReasoningOptions.isEmpty { aiChatReasoningOptions = [] }
      if aiChatEffectiveModel != nil { aiChatEffectiveModel = nil }
      if aiChatDefaultReasoningEffort != nil { aiChatDefaultReasoningEffort = nil }
    }
    let nextStatus = requiresHydration
      ? "Loading conversation…"
      : isSendingAIChatMessage
        ? "\(thread.runtime.title) is working"
        : thread.runtime == .codex
          ? "Ready for a Codex message"
          : Self.aiChatStatusText(settings: currentOpenClawSettings())
    if aiChatStatusText != nextStatus { aiChatStatusText = nextStatus }
    aiChatScrollPosition = aiChatScrollPositionsByThreadID[thread.id]
    aiChatAssistantChatScrollPosition = aiChatAssistantChatScrollPositionsByThreadID[thread.id]
    let messageIdentity = aiChatMessagesIdentity(for: thread.id)
    if publishedAIChatMessagesIdentity != messageIdentity {
      replaceAIChatMessages(thread.messages, shouldPersist: false)
      publishedAIChatMessagesIdentity = messageIdentity
    }
    // Publish the completion token only after the ID, messages, draft, send
    // state, configuration, and per-thread scroll snapshot are coherent.
    if selectionChanged { aiChatSelectionGeneration &+= 1 }
    if requiresHydration {
      hydrateAIChatThread(thread.id)
    } else {
      enforceHydratedAIChatThreadLimit()
    }
    if persistsSelection {
      persistSelectedAIChatThread()
    }
  }

  nonisolated static func prepareInitialAIChatMessagePresentations(
    messages: [AIChatMessage],
    isSharedRoom: Bool
  ) -> [AIChatPreparedMessagePresentation] {
    prepareInitialAIChatMessagePresentations(
      inputs: initialAIChatMessagePresentationInputs(
        messages: messages,
        isSharedRoom: isSharedRoom
      )
    )
  }

  nonisolated private static func initialAIChatMessagePresentationInputs(
    messages: [AIChatMessage],
    isSharedRoom: Bool
  ) -> [AIChatMessagePresentationInput] {
    let window = AIChatTranscriptWindow(
      messages: messages,
      isSharedRoom: isSharedRoom,
      displayLimit: AIChatTranscriptWindow.initialLimit
    )
    var seenMessageIDs = Set<UUID>()
    var inputs: [AIChatMessagePresentationInput] = []
    inputs.reserveCapacity(window.visibleChatBubbleCount)
    for message in window.visibleMessagesForPresentation {
      guard !Task.isCancelled else { return [] }
      guard seenMessageIDs.insert(message.id).inserted else { continue }
      // Project before any preparation so this task never carries attachment
      // values (including legacy inline Data) into the presentation cache.
      inputs.append(AIChatMessagePresentationInput(message))
    }
    return inputs
  }

  nonisolated private static func prepareInitialAIChatMessagePresentations(
    inputs: [AIChatMessagePresentationInput]
  ) -> [AIChatPreparedMessagePresentation] {
    var prepared: [AIChatPreparedMessagePresentation] = []
    prepared.reserveCapacity(inputs.count)
    for input in inputs {
      guard !Task.isCancelled else { return [] }
      prepared.append(AIChatMessagePresentationBuilder.prepare(input))
    }
    return prepared
  }

  private func hydrateAIChatThread(_ id: UUID) {
    guard unloadedAIChatThreadIDs.contains(id),
          aiChatThreadHydrationTasks[id] == nil,
          let metadata = aiChatThreads.first(where: { $0.id == id })
    else { return }
    let transcriptURL = aiChatTranscriptURL.standardizedFileURL
    let transcriptGeneration = aiChatTranscriptLoadGeneration
    let mutationVersion = aiChatThreadMessageMutationVersions[id, default: 0]
    let delay = aiChatThreadHydrationDelayNanosecondsForTesting
    let token = UUID()
    aiChatThreadHydrationTaskTokens[id] = token
    let task = Task { @MainActor [weak self] in
      guard !Task.isCancelled else { return }
      let loaded = await Task.detached(priority: .userInitiated) {
        AIChatTranscriptStore.shared.loadThread(
          id: id,
          metadata: metadata,
          legacyURL: transcriptURL
        )
      }.value
      self?.aiChatThreadHydrationDidLoadForTesting?(id)
      if delay > 0 {
        do {
          try await Task.sleep(nanoseconds: delay)
        } catch {
          return
        }
      }
      guard let self,
            !Task.isCancelled,
            self.aiChatThreadHydrationTaskTokens[id] == token
      else { return }
      defer {
        if self.aiChatThreadHydrationTaskTokens[id] == token {
          self.aiChatThreadHydrationTaskTokens.removeValue(forKey: id)
          self.aiChatThreadHydrationTasks.removeValue(forKey: id)
        }
      }
      guard self.aiChatTranscriptLoadGeneration == transcriptGeneration,
            self.aiChatTranscriptURL.standardizedFileURL.path == transcriptURL.path,
            self.aiChatThreadMessageMutationVersions[id, default: 0] == mutationVersion,
            self.unloadedAIChatThreadIDs.contains(id)
      else { return }
      guard let loaded,
            let index = self.aiChatThreads.firstIndex(where: { $0.id == id })
      else {
        self.errorText = "AI chat conversation \(metadata.title) could not be loaded from storage."
        if self.selectedAIChatThreadID == id {
          self.aiChatStatusText = "Conversation unavailable"
        }
        return
      }
      let hydrated = self.aiChatThreads[index].hydrating(
        messages: Self.settlingAnsweredOpenCodeRemoteTurns(in: [loaded]).threads[0].messages
      )
      AIChatTranscriptStore.shared.recordAdoptedThreads([hydrated], legacyURL: transcriptURL)
      self.unloadedAIChatThreadIDs.remove(id)
      let cachedMessageCount = (hydrated.isSettled
        ? self.archivedAIChatThreadSummaries
        : self.visibleAIChatThreadSummaries)
        .first(where: { $0.id == id })?.messageCount
      self.advanceAIChatMessageRevision(
        for: id,
        tracksPersistence: false,
        makesColdPlaceholderAuthoritative: false
      )
      let publishesSelectedThread = self.selectedAIChatThreadID == id
      if publishesSelectedThread {
        self.replaceAIChatMessages(hydrated.messages, shouldPersist: false)
        self.syncSelectedAIChatSendState()
        self.aiChatStatusText = self.isSendingAIChatMessage
          ? "\(hydrated.runtime.title) is working"
          : hydrated.runtime == .codex
            ? "Ready for a Codex message"
            : Self.aiChatStatusText(settings: self.currentOpenClawSettings())
      }
      if publishesSelectedThread,
         self.selectedSurface == .aiChat || self.isAIChatAssistantPresented {
        // The selected messages are sufficient to update the transcript. Defer
        // mutating the 500+ item observed thread collection until WebKit has
        // acknowledged that DOM update, so sidebar bookkeeping cannot compete
        // with the first visible frame.
        self.deferAIChatHydrationCommit(
          PendingAIChatHydrationCommit(
            thread: hydrated,
            messageCount: cachedMessageCount,
            transcriptPath: transcriptURL.path,
            transcriptGeneration: transcriptGeneration,
            mutationVersion: mutationVersion
          )
        )
      } else {
        self.replaceAIChatThreadIncrementally(
          at: index,
          with: hydrated,
          messageCount: cachedMessageCount
        )
        self.enforceHydratedAIChatThreadLimit()
      }
      // Cold threads skip launch-time interruption repair; apply it now that
      // their messages are loaded.
      self.repairStaleLocalAIChatSends(in: id, transcriptURL: transcriptURL)
      // Presentation enrichment is not required for a readable transcript:
      // AIChatTranscriptDocument immediately publishes a safe plain excerpt.
      // Warm the structured cache only after that first frame can be drawn.
      let presentationInputs = Self.initialAIChatMessagePresentationInputs(
        messages: loaded.messages,
        isSharedRoom: loaded.isSharedRoom
      )
      Task { @MainActor in
        try? await Task.sleep(for: .milliseconds(100))
        guard !Task.isCancelled else { return }
        let presentations = await Task.detached(priority: .utility) {
          Self.prepareInitialAIChatMessagePresentations(
            inputs: presentationInputs
          )
        }.value
        AIChatMessagePresentationCache.install(presentations)
      }
    }
    aiChatThreadHydrationTasks[id] = task
  }

  /// Persists launch-time interruption of this host's stale sends. The
  /// loader marks them in memory only, so a later replica refresh would
  /// otherwise bring back a turn that looks busy but has no driver.
  private func persistStaleLocalAIChatSendRepair(_ threadIDs: Set<UUID>) {
    guard !threadIDs.isEmpty,
          hasAuthoritativeAIChatTranscriptState,
          !aiChatTranscriptWritesBlocked
    else { return }
    let transcriptURL = aiChatTranscriptURL.standardizedFileURL
    for threadID in threadIDs
    where !unloadedAIChatThreadIDs.contains(threadID)
      && !isAIChatThreadRunningOnCurrentHost(threadID) {
      guard aiChatThread(threadID, transcriptURL: transcriptURL) != nil else { continue }
      updateAIChatThread(
        threadID,
        messages: aiChatMessages(for: threadID, transcriptURL: transcriptURL),
        transcriptURL: transcriptURL,
        shouldPersist: true
      )
    }
  }

  /// Marks this host's sends from an earlier OpenOrg process as interrupted
  /// when nothing in this process drives or recovers them. Otherwise the chat
  /// looks busy forever while Stop and Retry have nothing to act on.
  private func repairStaleLocalAIChatSends(in threadID: UUID, transcriptURL: URL) {
    guard !unloadedAIChatThreadIDs.contains(threadID),
          !isAIChatThreadRunningOnCurrentHost(threadID),
          let thread = aiChatThread(threadID, transcriptURL: transcriptURL)
    else { return }
    let messages = aiChatMessages(for: threadID, transcriptURL: transcriptURL)
    let repaired = Self.interruptStaleLocalAIChatSends(
      in: [thread.replacingMessages(messages)],
      processStartedAt: aiChatProcessStartedAt
    )
    guard repaired.changed, let repairedThread = repaired.threads.first else { return }
    updateAIChatThread(
      threadID,
      messages: repairedThread.messages,
      transcriptURL: transcriptURL,
      shouldPersist: true
    )
    dequeueInterruptedAIChatSends(in: repairedThread)
  }

  /// Drops interrupted sends from the in-memory dispatch queue.
  private func dequeueInterruptedAIChatSends(in thread: AIChatThread) {
    for message in thread.messages
    where message.role == .user && message.deliveryStatus == .interrupted {
      aiChatForeignPendingMessageIDs.remove(message.id)
      if aiChatPendingUserMessageIDs(for: thread.id).contains(message.id) {
        removePendingAIChatUserMessage(message.id, in: thread.id)
      }
    }
    if selectedAIChatThreadID == thread.id {
      restoreInterruptedAIChatSendStatusIfNeeded()
    }
  }

  /// Interrupts sends that this host accepted before `processStartedAt`.
  /// Unlike the launch loader, this runs on synchronized replicas too, so it
  /// requires explicit local provenance. Threads with a recoverable pending
  /// turn are left for turn recovery.
  /// Metadata-only (cold) threads are skipped until their messages load.
  nonisolated static func interruptStaleLocalAIChatSends(
    in threads: [AIChatThread],
    processStartedAt: Date,
    isLocalHost: (String) -> Bool = { AIChatLocalHostRegistry.shared.isLocal($0) }
  ) -> (threads: [AIChatThread], changed: Bool) {
    var changed = false
    let repaired = threads.map { thread -> AIChatThread in
      guard thread.storedMessageCount == nil else { return thread }
      if let pendingTurn = thread.pendingTurn,
         thread.messages.contains(where: {
           $0.id == pendingTurn.userMessageID && $0.role == .user && $0.deliveryStatus == .sending
         }) {
        return thread
      }
      var threadChanged = false
      let messages = thread.messages.map { message -> AIChatMessage in
        guard message.role == .user,
              message.deliveryStatus == .sending,
              message.deliveryKind != .steer,
              (message.provenance?.acceptedAt ?? message.createdAt) < processStartedAt
        else { return message }
        // Only a turn this host explicitly accepted is known to be stale. A
        // replica's unattributed send may be another host's live turn, and a
        // hand-off nobody has started is still waiting for its host.
        guard let provenance = message.provenance,
              let executionHostRef = provenance.executionHostRef,
              provenance.acceptedAt != nil,
              isLocalHost(executionHostRef)
        else { return message }
        threadChanged = true
        if message.deliveryIsUnconfirmed {
          return message.replacingDeliveryAttempt(
            message.deliveryAttemptID ?? message.id,
            status: .sending,
            sendFailure: aiChatUnknownSendFailureText,
            attemptState: .unconfirmed
          )
        }
        return message.replacingDeliveryStatus(
          .interrupted,
          sendFailure: aiChatInterruptedSendFailureText
        )
      }
      guard threadChanged else { return thread }
      changed = true
      return thread.replacingMessages(messages)
    }
    return (repaired, changed)
  }

  private func hydrateAIChatThreadIfNeeded(_ id: UUID) async -> AIChatThread? {
    guard aiChatThreads.contains(where: { $0.id == id }) else { return nil }
    if unloadedAIChatThreadIDs.contains(id) {
      hydrateAIChatThread(id)
      if let task = aiChatThreadHydrationTasks[id] { await task.value }
    }
    guard !unloadedAIChatThreadIDs.contains(id) else { return nil }
    return pendingAIChatHydrationCommits[id]?.thread
      ?? aiChatThreads.first(where: { $0.id == id })
  }

  private func deferAIChatHydrationCommit(_ commit: PendingAIChatHydrationCommit) {
    let id = commit.thread.id
    pendingAIChatHydrationCommitTasks.removeValue(forKey: id)?.cancel()
    pendingAIChatHydrationCommits[id] = commit
    pendingAIChatHydrationCommitTasks[id] = Task { @MainActor [weak self] in
      do {
        try await Task.sleep(for: .milliseconds(500))
      } catch {
        return
      }
      guard !Task.isCancelled else { return }
      self?.commitPendingAIChatHydration(for: id)
    }
  }

  private func commitPendingAIChatHydration(for id: UUID) {
    guard let commit = pendingAIChatHydrationCommits.removeValue(forKey: id) else {
      return
    }
    pendingAIChatHydrationCommitTasks.removeValue(forKey: id)?.cancel()
    guard aiChatTranscriptLoadGeneration == commit.transcriptGeneration,
          aiChatTranscriptURL.standardizedFileURL.path == commit.transcriptPath,
          aiChatThreadMessageMutationVersions[id, default: 0] == commit.mutationVersion,
          let index = aiChatThreads.firstIndex(where: { $0.id == id })
    else { return }
    replaceAIChatThreadIncrementally(
      at: index,
      with: commit.thread,
      messageCount: commit.messageCount
    )
    enforceHydratedAIChatThreadLimit()
  }

  private func discardPendingAIChatHydrationCommit(for id: UUID) {
    pendingAIChatHydrationCommits.removeValue(forKey: id)
    pendingAIChatHydrationCommitTasks.removeValue(forKey: id)?.cancel()
  }

  /// Returns a complete thread for detail projections without moving file IO
  /// onto the main actor. Metadata-only chat records remain useful for lists,
  /// while callers that expose message history must cross this async boundary.
  public func hydratedAIChatThreadForDetail(_ id: UUID) async -> AIChatThread? {
    await hydrateAIChatThreadIfNeeded(id)
  }

  public func cacheAIChatComposerDraft(_ draft: String) {
    guard let selectedAIChatThreadID else { return }
    cacheAIChatDraft(draft, for: selectedAIChatThreadID)
  }

  public func publishAIChatComposerDraft(_ draft: String) {
    cacheAIChatComposerDraft(draft)
    guard aiChatDraft != draft else { return }
    aiChatDraft = draft
  }

  private func saveAIChatComposerForSelectedThread() {
    guard let selectedAIChatThreadID else { return }
    let key = aiChatComposerKey(for: selectedAIChatThreadID)
    // The SwiftUI composer caches its local draft independently from
    // attachments. Treating either component as proof that both were cached
    // can discard a draft when an attachment is added before navigation (or
    // discard attachments after only the draft was cached).
    if !aiChatDraftCachedKeys.contains(key) {
      cacheAIChatDraft(aiChatDraft, for: selectedAIChatThreadID)
    }
    if !aiChatAttachmentCachedKeys.contains(key) {
      cacheAIChatAttachments(aiChatPendingAttachments, for: selectedAIChatThreadID)
    }
  }

  private func currentAIChatDraftForSelectedThread() -> String {
    guard let selectedAIChatThreadID else { return aiChatDraft }
    let key = aiChatComposerKey(for: selectedAIChatThreadID)
    guard aiChatDraftCachedKeys.contains(key) else { return aiChatDraft }
    return aiChatDraftsByComposerKey[key] ?? ""
  }

  private func aiChatDraft(
    for threadID: UUID,
    context: AIChatCorpusContextToken? = nil
  ) -> String {
    let key = aiChatComposerKey(for: threadID, context: context)
    if context == nil, selectedAIChatThreadID == threadID {
      return currentAIChatDraftForSelectedThread()
    }
    return aiChatDraftsByComposerKey[key] ?? ""
  }

  private func cacheAIChatDraft(
    _ draft: String,
    for threadID: UUID,
    context: AIChatCorpusContextToken? = nil
  ) {
    let key = aiChatComposerKey(for: threadID, context: context)
    aiChatDraftCachedKeys.insert(key)
    let normalizedDraft = draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
      ? ""
      : draft
    if normalizedDraft.isEmpty {
      aiChatDraftsByComposerKey.removeValue(forKey: key)
    } else {
      aiChatDraftsByComposerKey[key] = normalizedDraft
    }
  }

  private func cacheAIChatAttachments(
    _ attachments: [AIChatAttachment],
    for threadID: UUID,
    context: AIChatCorpusContextToken? = nil
  ) {
    let key = aiChatComposerKey(for: threadID, context: context)
    aiChatAttachmentCachedKeys.insert(key)
    if attachments.isEmpty {
      aiChatAttachmentsByComposerKey.removeValue(forKey: key)
    } else {
      aiChatAttachmentsByComposerKey[key] = attachments
    }
  }

  private func restoreAIChatComposer(for threadID: UUID) {
    let key = aiChatComposerKey(for: threadID)
    aiChatDraft = aiChatDraftsByComposerKey[key] ?? ""
    aiChatPendingAttachments = aiChatAttachmentsByComposerKey[key] ?? []
  }

  private func clearAIChatDraftForSelectedThread() {
    if let selectedAIChatThreadID {
      let key = aiChatComposerKey(for: selectedAIChatThreadID)
      aiChatDraftsByComposerKey.removeValue(forKey: key)
      aiChatDraftCachedKeys.insert(key)
    }
    aiChatDraft = ""
  }

  private func clearAIChatDraft(
    for threadID: UUID,
    context: AIChatCorpusContextToken? = nil
  ) {
    let key = aiChatComposerKey(for: threadID, context: context)
    aiChatDraftsByComposerKey.removeValue(forKey: key)
    aiChatDraftCachedKeys.insert(key)
    if context == nil, selectedAIChatThreadID == threadID {
      aiChatDraft = ""
    }
  }

  private func ensureAIChatThread() {
    if let selectedAIChatThreadID,
       aiChatThreads.contains(where: { $0.id == selectedAIChatThreadID }) {
      return
    }
    let thread = AIChatThread(
      title: Self.aiChatThreadTitle(from: aiChatMessages),
      sessionKey: openClawSessionKey,
      messages: aiChatMessages
    )
    aiChatThreads.insert(thread, at: 0)
    advanceAIChatMessageRevision(
      for: thread.id,
      tracksPersistence: true,
      makesColdPlaceholderAuthoritative: true
    )
    selectedAIChatThreadID = thread.id
  }

  public func markSelectedAIChatThreadRead() {
    guard let selectedAIChatThreadID else { return }
    markAIChatThreadRead(selectedAIChatThreadID)
  }

  public func previewAIChatMessageSound() {
    guard aiChatMessageSound != .off else { return }
    aiChatIncomingMessageSoundPlayer()
  }

  private func markAIChatThreadRead(_ id: UUID) {
    guard let index = aiChatThreads.firstIndex(where: { $0.id == id }) else { return }
    let thread = aiChatThreads[index]
    aiChatReadState.markRead(thread, transcriptURL: aiChatTranscriptURL)
    guard thread.unreadMessageCount != 0 else { return }
    let cachedMessageCount = (thread.isSettled
      ? archivedAIChatThreadSummaries
      : visibleAIChatThreadSummaries)
      .first(where: { $0.id == id })?.messageCount
    replaceAIChatThreadIncrementally(
      at: index,
      with: thread.replacingAIChatMetadata(unreadMessageCount: 0),
      messageCount: cachedMessageCount
    )
  }

  private func updateSelectedAIChatThread(messages: [AIChatMessage]) {
    ensureAIChatThread()
    guard let selectedAIChatThreadID else {
      return
    }
    updateAIChatThread(selectedAIChatThreadID, messages: messages)
  }

  private func updateAIChatThread(
    _ threadID: UUID,
    messages: [AIChatMessage],
    notifiesForNewAssistantMessages: Bool = false,
    transcriptURL: URL? = nil,
    shouldPersist: Bool = false,
    pendingTurnUpdate: AIChatPendingTurnUpdate = .preserve,
    recordsMessageMutation: Bool = true
  ) {
    let targetTranscriptURL = transcriptURL ?? aiChatTranscriptURL
    guard let current = aiChatThread(
      threadID,
      transcriptURL: targetTranscriptURL
    ) else { return }
    let newAssistantMessages = notifiesForNewAssistantMessages
      ? Self.newAssistantMessages(previousMessages: current.messages, currentMessages: messages)
      : []
    let newAssistantMessageCount = newAssistantMessages.count
    let isThreadOpen = isActiveAIChatTranscript(targetTranscriptURL)
      && selectedSurface == .aiChat
      && selectedAIChatThreadID == current.id
    let updated = Self.updatedAIChatThread(
      current,
      messages: messages,
      newAssistantMessageCount: newAssistantMessageCount,
      isThreadOpen: isThreadOpen,
      pendingTurnUpdate: pendingTurnUpdate
    )
    if isThreadOpen {
      aiChatReadState.markRead(updated, transcriptURL: targetTranscriptURL)
    }
    if recordsMessageMutation, isActiveAIChatTranscript(targetTranscriptURL) {
      advanceAIChatMessageRevision(
        for: threadID,
        tracksPersistence: true,
        makesColdPlaceholderAuthoritative: true
      )
    }
    replaceAIChatThread(
      updated,
      transcriptURL: targetTranscriptURL,
      shouldPersist: shouldPersist,
      recordsMessageMutation: recordsMessageMutation
    )
    if recordsMessageMutation,
       isActiveAIChatTranscript(targetTranscriptURL),
       selectedAIChatThreadID == threadID {
      publishedAIChatMessagesIdentity = aiChatMessagesIdentity(for: threadID)
    }
    if newAssistantMessageCount > 0 {
      if aiChatMessageSound != .off {
        aiChatIncomingMessageSoundPlayer()
      }
      aiChatIncomingMessageHandler(updated, newAssistantMessages)
    }
  }

  private static func messageSoundPlayer(
    for sound: AIChatMessageSound
  ) -> @MainActor () -> Void {
    switch sound {
    case .org2:
      return { WorkspaceSound.playBundledNewMessageSound() }
    case .systemAlert:
      return { WorkspaceSound.beep() }
    case .off:
      return {}
    default:
      guard let name = sound.appKitSoundName else { return {} }
      return { WorkspaceSound.play(named: name) }
    }
  }

  nonisolated static func updatedAIChatThread(
    _ current: AIChatThread,
    messages: [AIChatMessage],
    newAssistantMessageCount: Int,
    isThreadOpen: Bool,
    pendingTurnUpdate: AIChatPendingTurnUpdate
  ) -> AIChatThread {
    let unreadMessageCount = isThreadOpen
      ? 0
      : current.unreadMessageCount + newAssistantMessageCount
    let pendingTurn: AIChatPendingTurn?
    switch pendingTurnUpdate {
    case .preserve:
      pendingTurn = current.pendingTurn
    case .replace(let nextPendingTurn):
      pendingTurn = nextPendingTurn
    }
    return AIChatThread(
      id: current.id,
      title: updatedAIChatThreadTitle(current: current, messages: messages),
      createdAt: current.createdAt,
      updatedAt: max(current.updatedAt, messages.last?.createdAt ?? Date()),
      runtime: current.runtime,
      destinationID: current.destinationID,
      sessionKey: current.sessionKey,
      runtimeThreadID: current.runtimeThreadID,
      runtimeThreadIDsByDestination: current.runtimeThreadIDsByDestination,
      model: current.model,
      reasoningEffort: current.reasoningEffort,
      messages: messages,
      isPinned: current.isPinned,
      isArchived: current.isArchived,
      settledAt: current.settledAt,
      unreadMessageCount: unreadMessageCount,
      resource: current.resource,
      pendingTurn: pendingTurn,
      isSharedRoom: current.isSharedRoom,
      roomAudience: current.roomAudience,
      roomModels: current.roomModels,
      roomDestinationIDs: current.roomDestinationIDs,
      roomModelsByDestination: current.roomModelsByDestination,
      roomReasoningEffortsByDestination: current.roomReasoningEffortsByDestination,
      roomDefaultDestinationID: current.roomDefaultDestinationID,
      roomAgentTurnLimit: current.roomAgentTurnLimit,
      agentRef: current.agentRef
    )
  }

  nonisolated private static func newAssistantMessages(
    previousMessages: [AIChatMessage],
    currentMessages: [AIChatMessage]
  ) -> [AIChatMessage] {
    let previousIDs = Set(previousMessages.map(\.id))
    return currentMessages
      .filter { $0.role == .assistant && !previousIDs.contains($0.id) }
  }

  private func sortAIChatThreadsForDisplay() {
    aiChatThreads = Self.sortedAIChatThreadsForDisplay(aiChatThreads)
  }

  nonisolated private static func sortedAIChatThreadsForDisplay(
    _ threads: [AIChatThread]
  ) -> [AIChatThread] {
    threads.sorted { lhs, rhs in
      if lhs.isSettled != rhs.isSettled { return !lhs.isSettled }
      if lhs.isPinned != rhs.isPinned { return lhs.isPinned }
      return lhs.updatedAt > rhs.updatedAt
    }
  }

  nonisolated static func aiChatThreadTitle(
    from messages: [AIChatMessage],
    fallback: String = "New Chat"
  ) -> String {
    guard let firstUserMessage = messages.first(where: { $0.role == .user }) else {
      return fallback
    }
    let title = heuristicAIChatThreadTitle(from: firstUserMessage.content)
    return title.isEmpty ? fallback : title
  }

  nonisolated private static func updatedAIChatThreadTitle(
    current: AIChatThread,
    messages: [AIChatMessage]
  ) -> String {
    let heuristicTitle = aiChatThreadTitle(from: messages, fallback: current.title)
    let currentTitle = normalizedAIChatThreadTitle(current.title)
    let hasExistingUserMessage = current.messages.contains(where: { $0.role == .user })
    if currentTitle == "New Chat"
      || (hasExistingUserMessage && currentTitle == aiChatThreadTitle(from: current.messages, fallback: currentTitle)) {
      return heuristicTitle
    }
    return currentTitle
  }

  nonisolated private static func normalizedAIChatThreadTitle(_ title: String) -> String {
    let clean = Org2Display.cleanInline(title)
      .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
      .trimmingCharacters(in: .whitespacesAndNewlines)
    guard !clean.isEmpty else { return "New Chat" }
    return clean.count <= 80
      ? clean
      : String(clean.prefix(77)).trimmingCharacters(in: .whitespacesAndNewlines) + "..."
  }

  nonisolated private static func heuristicAIChatThreadTitle(from content: String) -> String {
    let normalized = normalizedAIChatTitleSource(content)
    guard !normalized.isEmpty else { return "" }

    let candidates = normalized
      .split(whereSeparator: { ".!?\n".contains($0) })
      .map { cleanedAIChatTitleCandidate(String($0)) }
      .filter { !$0.isEmpty && !isAIChatTitleFiller($0) }

    guard let candidate = candidates.first ?? normalized.split(separator: "\n").first.map(String.init) else {
      return ""
    }

    let words = candidate
      .split(whereSeparator: { $0.isWhitespace })
      .map { titleWord(from: String($0)) }
      .filter { !$0.isEmpty && !aiChatTitleStopWords.contains($0.lowercased()) }

    let selectedWords = Array(words.prefix(6))
    let rawTitle = (selectedWords.isEmpty ? candidate : selectedWords.joined(separator: " "))
      .trimmingCharacters(in: .whitespacesAndNewlines)
    let limitedTitle = rawTitle.count <= 56
      ? rawTitle
      : String(rawTitle.prefix(53)).trimmingCharacters(in: .whitespacesAndNewlines) + "..."
    return sentenceCaseAIChatTitle(limitedTitle)
  }

  nonisolated private static func normalizedAIChatTitleSource(_ content: String) -> String {
    content
      .replacingOccurrences(of: #"https?://\S+"#, with: " ", options: .regularExpression)
      .replacingOccurrences(of: #"\[[^\]]+\]\([^)]+\)"#, with: " ", options: .regularExpression)
      .replacingOccurrences(of: #"<image[^>]*>"#, with: " ", options: .regularExpression)
      .replacingOccurrences(of: #"\s+"#, with: " ", options: .regularExpression)
      .trimmingCharacters(in: .whitespacesAndNewlines)
  }

  nonisolated private static func cleanedAIChatTitleCandidate(_ candidate: String) -> String {
    var clean = candidate
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .trimmingCharacters(in: CharacterSet(charactersIn: "#*-_`\"' "))

    let leadingPatterns = [
      #"(?i)^sure\s+let'?s\s+do\s+that\s+to\s+start\b"#,
      #"(?i)^while\s+you'?re\s+doing\s+that\b"#,
      #"(?i)^also\b"#,
      #"(?i)^can\s+you\b"#,
      #"(?i)^could\s+you\b"#,
      #"(?i)^would\s+you\b"#,
      #"(?i)^please\b"#,
      #"(?i)^i\s+think\b"#,
      #"(?i)^it\s+would\s+be\s+good\s+to\b"#,
      #"(?i)^it\s+would\s+be\s+great\s+to\b"#,
      #"(?i)^let'?s\b"#,
      #"(?i)^we\s+should\b"#,
      #"(?i)^our\b"#
    ]

    var changed = true
    while changed {
      changed = false
      for pattern in leadingPatterns {
        let next = clean
          .replacingOccurrences(of: pattern, with: "", options: .regularExpression)
          .trimmingCharacters(in: .whitespacesAndNewlines)
        if next != clean {
          clean = next
          changed = true
        }
      }
    }
    return clean
  }

  nonisolated private static func isAIChatTitleFiller(_ candidate: String) -> Bool {
    let normalized = candidate
      .lowercased()
      .trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
    return aiChatTitleFillerPhrases.contains(normalized)
  }

  nonisolated private static func titleWord(from raw: String) -> String {
    raw.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
  }

  nonisolated private static func sentenceCaseAIChatTitle(_ title: String) -> String {
    guard let first = title.first else { return title }
    return String(first).uppercased() + String(title.dropFirst())
  }

  nonisolated private static let aiChatTitleFillerPhrases = Set([
    "sure",
    "ok",
    "okay",
    "yes",
    "yeah",
    "thanks",
    "thank you",
    "sounds good",
    "that seems good",
    "lets do that",
    "let's do that",
    "sure lets do that to start",
    "sure let's do that to start"
  ])

  nonisolated private static let aiChatTitleStopWords = Set([
    "a", "able", "an", "and", "are", "as", "at", "be", "can", "could", "do", "does", "doing",
    "for", "from", "how", "i", "in", "is", "it", "just", "me", "my", "of", "on",
    "or", "our", "please", "should", "start", "that", "the", "this", "to", "we",
    "well", "what", "while", "with", "would", "you", "you're", "youre", "your"
  ])

  public nonisolated static func visibleAIChatMessageText(
    _ message: AIChatMessage
  ) -> String {
    AIChatContextPresentation(
      message.content,
      extractsContexts: message.role == .user
    ).clipboardText
  }

  nonisolated static func searchAIChatThreads(
    _ threads: [AIChatThread],
    query rawQuery: String,
    limit: Int
  ) -> [AIChatSearchResult] {
    let query = rawQuery.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !query.isEmpty else { return [] }

    return threads
      .flatMap { thread -> [(AIChatSearchResult, Int)] in
        var matches: [(AIChatSearchResult, Int)] = []
        if let titleScore = fuzzyScore(query: query, candidate: thread.title) {
          matches.append((
            AIChatSearchResult(
              threadID: thread.id,
              messageID: nil,
              matchKind: .threadTitle,
              title: thread.title,
              snippet: chatSearchSnippet(
                message: thread.messages.first.map(visibleAIChatMessageText) ?? thread.title,
                query: query
              ),
              messageCount: thread.messageCount,
              updatedAt: thread.updatedAt
            ),
            titleScore
          ))
        }

        let messageMatches = thread.messages.compactMap {
          message -> (message: AIChatMessage, visibleText: String, score: Int)? in
          let visibleText = visibleAIChatMessageText(message)
          guard let score = fuzzyScore(query: query, candidate: visibleText) else { return nil }
          return (message, visibleText, score)
        }
        if let bestMessage = messageMatches.max(by: { lhs, rhs in lhs.score < rhs.score }) {
          matches.append((
            AIChatSearchResult(
              threadID: thread.id,
              messageID: bestMessage.message.id,
              matchKind: .messageText,
              title: thread.title,
              snippet: chatSearchSnippet(message: bestMessage.visibleText, query: query),
              messageCount: thread.messageCount,
              updatedAt: thread.updatedAt
            ),
            bestMessage.score
          ))
        }

        return matches
      }
      .sorted { lhs, rhs in
        if lhs.0.matchKind != rhs.0.matchKind {
          return lhs.0.matchKind == .threadTitle
        }
        if lhs.1 != rhs.1 { return lhs.1 > rhs.1 }
        return lhs.0.updatedAt > rhs.0.updatedAt
      }
      .prefix(limit)
      .map(\.0)
  }

  nonisolated private static func chatSearchSnippet(message: String, query: String) -> String {
    let collapsed = message
      .split(whereSeparator: { $0.isWhitespace })
      .joined(separator: " ")
    guard !collapsed.isEmpty else { return message }
    guard let range = collapsed.range(of: query, options: [.caseInsensitive, .diacriticInsensitive]) else {
      return String(collapsed.prefix(180))
    }

    let before = collapsed.distance(from: collapsed.startIndex, to: range.lowerBound)
    let startOffset = max(0, before - 72)
    let endOffset = min(collapsed.count, before + query.count + 108)
    let start = collapsed.index(collapsed.startIndex, offsetBy: startOffset)
    let end = collapsed.index(collapsed.startIndex, offsetBy: endOffset)
    let prefix = startOffset > 0 ? "..." : ""
    let suffix = endOffset < collapsed.count ? "..." : ""
    return prefix + String(collapsed[start..<end]) + suffix
  }

  public func aiChatScrollPosition(
    isAssistantPanel: Bool,
    threadID: UUID? = nil
  ) -> Double? {
    let id = threadID ?? selectedAIChatThreadID
    guard let id else { return nil }
    return isAssistantPanel
      ? aiChatAssistantChatScrollPositionsByThreadID[id]
      : aiChatScrollPositionsByThreadID[id]
  }

  public func recordAIChatScrollPosition(
    _ position: Double,
    isAssistantPanel: Bool = false,
    threadID: UUID? = nil
  ) {
    guard let id = threadID ?? selectedAIChatThreadID else { return }
    let normalized = min(1, max(0, position))
    if isAssistantPanel {
      aiChatAssistantChatScrollPositionsByThreadID[id] = normalized
      if id == selectedAIChatThreadID { aiChatAssistantChatScrollPosition = normalized }
    } else {
      aiChatScrollPositionsByThreadID[id] = normalized
      if id == selectedAIChatThreadID { aiChatScrollPosition = normalized }
    }
  }

  public func completeAIChatScrollRestoration(threadID: UUID?) {
    lastCompletedAIChatScrollRestorationThreadID = threadID
    aiChatScrollRestorationCompletionGeneration &+= 1
    guard let threadID, pendingAIChatHydrationCommits[threadID] != nil else { return }
    pendingAIChatHydrationCommitTasks.removeValue(forKey: threadID)?.cancel()
    pendingAIChatHydrationCommitTasks[threadID] = Task { @MainActor [weak self] in
      do {
        // WebKit has applied the DOM mutation. Leave one display interval for
        // that frame to reach the screen before invalidating the large sidebar.
        try await Task.sleep(for: .milliseconds(50))
      } catch {
        return
      }
      guard !Task.isCancelled else { return }
      self?.commitPendingAIChatHydration(for: threadID)
    }
  }

  /// ⌘-click on a workspace link: open the target in a new tab and keep the
  /// current tab where it is.
  public func openChatFileReferenceInNewTab(_ reference: AIChatFileReference) {
    usageLog.record(.linkOpenInNewTab)
    newWorkspaceTab()
    pendingNavigationSource = "link_new_tab"
    openChatFileReference(reference)
  }

  public func openChatFileReference(_ reference: AIChatFileReference) {
    guard let file = localPathForOpenClawReference(reference.path) else {
      let message = "Could not resolve file link: \(reference.path)"
      aiChatStatusText = message
      statusText = message
      return
    }

    if pendingNavigationSource == nil { pendingNavigationSource = "link" }
    if canJumpWithinActivePage(to: file) {
      pendingNavigationSource = nil
      if presentedAgentRunID != nil { presentedAgentRunID = nil }
      if isWorkspaceDetailPaneClosed { isWorkspaceDetailPaneClosed = false }
      if isWorkspaceDetailPaneExpanded { isWorkspaceDetailPaneExpanded = false }
      if let selectedLocation {
        scheduleSelectedDetailFreshnessCheck(
          for: selectedLocation,
          mode: selectedEntrySourceMode
        )
      }
      requestDetailScroll(toSourceLine: reference.line ?? 1)
      statusText = "Jumped to \(relativePath(file))"
      return
    }

    let url = URL(fileURLWithPath: file)
    let thread = AIChatThreadRecord(
      title: url.deletingPathExtension().lastPathComponent,
      file: file,
      line: reference.line ?? 1,
      zone: "chat link",
      modifiedAt: nil,
      idValue: nil
    )
    activateDetailLocation(.aiChatThreadRecord(thread), mode: .page, surface: nil, recordsHistory: true)
    if let line = reference.line {
      requestDetailScroll(toSourceLine: line)
    }
    statusText = "Opened \(relativePath(file))"
  }

  private func canJumpWithinActivePage(to file: String) -> Bool {
    guard selectedEntrySourceMode == .page,
          let source = selectedEntrySource,
          !selectedFileIsCSV
    else {
      return false
    }
    return URL(fileURLWithPath: source.file).standardizedFileURL.path
      == URL(fileURLWithPath: file).standardizedFileURL.path
  }

  public func isPersonalAssignee(_ rawAssignee: String?) -> Bool {
    guard let assignee = rawAssignee?.trimmingCharacters(in: .whitespacesAndNewlines),
          !assignee.isEmpty
    else {
      return true
    }
    return Self.personalAssigneeNames(from: personalAssigneeNamesText)
      .contains(Self.normalizedAssigneeIdentity(assignee))
  }

  public func isAgentAssignee(_ rawAssignee: String?) -> Bool {
    guard let assignee = rawAssignee?.trimmingCharacters(in: .whitespacesAndNewlines),
          !assignee.isEmpty
    else {
      return false
    }
    let normalized = Self.normalizedAssigneeIdentity(assignee)
    let agentNames = [
      agentHandoffAssignee,
      Self.defaultAgentHandoffAssignee
    ]
      .map(Self.normalizedAssigneeIdentity)
      .filter { !$0.isEmpty }
    return Set(agentNames).contains(normalized)
  }

  public func saveOpenClawConfiguration(
    endpoint: String,
    agent: String,
    handoffAssignee: String,
    personalAssigneeNames: String? = nil,
    remoteCorpusPath: String,
    briefsStartNewThread: Bool? = nil,
    autoSettleInterval: AIChatAutoSettleInterval? = nil,
    localEditsEnabled: Bool? = nil,
    token: String,
    clearToken: Bool
  ) -> Bool {
    let rawEndpoint = endpoint.trimmingCharacters(in: .whitespacesAndNewlines)
    guard let normalizedEndpoint = OpenClawGatewaySettings.normalizedEndpointString(rawEndpoint) else {
      aiChatStatusText = "OpenClaw gateway endpoint is invalid"
      return false
    }

    let rawAgent = agent.trimmingCharacters(in: .whitespacesAndNewlines)
    let agent = rawAgent.isEmpty ? "main" : rawAgent
    let rawHandoffAssignee = handoffAssignee.trimmingCharacters(in: .whitespacesAndNewlines)
    let handoffAssignee = rawHandoffAssignee.isEmpty ? Self.defaultAgentHandoffAssignee : rawHandoffAssignee
    let personalAssigneeNames = (personalAssigneeNames ?? personalAssigneeNamesText)
      .trimmingCharacters(in: .whitespacesAndNewlines)
    let remoteCorpusPath = remoteCorpusPath.trimmingCharacters(in: .whitespacesAndNewlines)
    let briefsStartNewThread = briefsStartNewThread ?? aiChatBriefsStartNewThread
    let localEditsEnabled = localEditsEnabled ?? openClawLocalEditsEnabled
    let normalizedToken = OpenClawGatewaySettings.normalizedBearerToken(token)

    do {
      defaults.set(normalizedEndpoint, forKey: openClawEndpointKey)
      defaults.set(agent, forKey: openClawAgentKey)
      defaults.set(handoffAssignee, forKey: agentHandoffAssigneeKey)
      defaults.set(personalAssigneeNames, forKey: personalAssigneeNamesKey)
      defaults.set(remoteCorpusPath, forKey: openClawRemoteCorpusPathKey)
      if let corpusRoot {
        var paths = defaults.dictionary(forKey: openClawRemoteCorpusPathsByCorpusKey) as? [String: String] ?? [:]
        if remoteCorpusPath.isEmpty { paths.removeValue(forKey: corpusRoot.standardizedFileURL.path) }
        else { paths[corpusRoot.standardizedFileURL.path] = remoteCorpusPath }
        defaults.set(paths, forKey: openClawRemoteCorpusPathsByCorpusKey)
      }
      openClawEndpointText = normalizedEndpoint
      openClawAgentID = agent
      agentHandoffAssignee = handoffAssignee
      personalAssigneeNamesText = personalAssigneeNames
      openClawRemoteCorpusPath = remoteCorpusPath
      aiChatBriefsStartNewThread = briefsStartNewThread
      openClawLocalEditsEnabled = localEditsEnabled
      defaults.set(localEditsEnabled, forKey: openClawLocalEditsEnabledKey)
      if let autoSettleInterval {
        setAIChatAutoSettleInterval(autoSettleInterval)
      }

      if clearToken {
        try OpenClawKeychain.deleteToken()
        openClawBearerToken = nil
        openClawHasStoredToken = false
      } else if let token = normalizedToken {
        try OpenClawKeychain.saveToken(token)
        openClawBearerToken = token
        openClawHasStoredToken = true
      } else {
        openClawHasStoredToken = OpenClawKeychain.containsToken()
      }

      removeCachedAIChatConfiguration(
        destinationID: AIChatDestinationConfiguration.openClawID
      )
      aiChatStatusText = Self.aiChatStatusText(settings: currentOpenClawSettings())
      Task { @MainActor [weak self] in
        await self?.refreshAIChatCommands(force: true)
      }
      restartOpenClawLocalEditNode()
      return true
    } catch {
      aiChatStatusText = error.localizedDescription
      return false
    }
  }

  public func meetingReadyAutomationThreads(
    destinationID: String
  ) -> [AIChatThread] {
    aiChatThreads
      .filter { !$0.isSharedRoom && $0.destinationID == destinationID }
      .sorted { lhs, rhs in
        if lhs.isPinned != rhs.isPinned { return lhs.isPinned }
        if lhs.isSettled != rhs.isSettled { return !lhs.isSettled }
        return lhs.updatedAt > rhs.updatedAt
      }
  }

  @discardableResult
  public func saveMeetingReadyAutomationConfiguration(
    isEnabled: Bool,
    destinationID: String,
    threadMode: MeetingReadyAutomationThreadMode,
    threadID: UUID?,
    prompt: String
  ) -> Bool {
    guard corpusRoot != nil else {
      meetingReadyAutomationStatusText = "Choose a corpus before enabling meeting automation"
      return false
    }
    let prompt = prompt.trimmingCharacters(in: .whitespacesAndNewlines)
    if isEnabled {
      guard enabledAIChatDestinations.contains(where: { $0.id == destinationID }) else {
        meetingReadyAutomationStatusText = "Choose an enabled AI destination"
        return false
      }
      guard !prompt.isEmpty else {
        meetingReadyAutomationStatusText = "Enter a meeting-processing prompt"
        return false
      }
      if threadMode == .existingThread {
        guard let threadID,
              aiChatThreads.contains(where: {
                $0.id == threadID && !$0.isSharedRoom && $0.destinationID == destinationID
              })
        else {
          meetingReadyAutomationStatusText = "Choose an existing thread for this destination"
          return false
        }
      }
    }

    meetingReadyAutomationSettings = MeetingReadyAutomationSettings(
      isEnabled: isEnabled,
      destinationID: destinationID,
      threadMode: threadMode,
      threadID: threadMode == .existingThread ? threadID : nil,
      prompt: prompt.isEmpty ? MeetingReadyAutomationSettings.defaultPrompt : prompt
    )
    persistMeetingReadyAutomationSettings()
    if isEnabled {
      meetingReadyAutomationStatusText = "Watching for completed meetings"
    } else {
      meetingReadyAutomationStatusText = "Meeting automation is off"
    }
    return true
  }

  private func restoreMeetingReadyAutomationState(for corpusRoot: URL) {
    let corpusKey = corpusRoot.standardizedFileURL.path
    let settingsByCorpus = Self.decodeDefaultsValue(
      [String: MeetingReadyAutomationSettings].self,
      defaults: defaults,
      key: meetingReadyAutomationSettingsByCorpusKey
    ) ?? [:]
    let deliveriesByCorpus = Self.decodeDefaultsValue(
      [String: [String: MeetingReadyAutomationDeliveryRecord]].self,
      defaults: defaults,
      key: meetingReadyAutomationDeliveriesByCorpusKey
    ) ?? [:]
    meetingReadyAutomationSettings = settingsByCorpus[corpusKey] ?? MeetingReadyAutomationSettings()
    meetingReadyAutomationDeliveries = deliveriesByCorpus[corpusKey] ?? [:]
    meetingReadyAutomationDispatchingEventIDs = []
    meetingReadyAutomationStatusText = meetingReadyAutomationSettings.isEnabled
      ? "Watching for completed meetings"
      : "Meeting automation is off"
  }

  private static func decodeDefaultsValue<T: Decodable>(
    _ type: T.Type,
    defaults: UserDefaults,
    key: String
  ) -> T? {
    guard let data = defaults.data(forKey: key) else { return nil }
    return try? JSONDecoder().decode(type, from: data)
  }

  private func persistMeetingReadyAutomationSettings() {
    guard let corpusRoot else { return }
    let corpusKey = corpusRoot.standardizedFileURL.path
    var settingsByCorpus = Self.decodeDefaultsValue(
      [String: MeetingReadyAutomationSettings].self,
      defaults: defaults,
      key: meetingReadyAutomationSettingsByCorpusKey
    ) ?? [:]
    settingsByCorpus[corpusKey] = meetingReadyAutomationSettings
    if let data = try? JSONEncoder().encode(settingsByCorpus) {
      defaults.set(data, forKey: meetingReadyAutomationSettingsByCorpusKey)
    }
  }

  private func persistMeetingReadyAutomationDeliveries() {
    guard let corpusRoot else { return }
    let corpusKey = corpusRoot.standardizedFileURL.path
    var deliveriesByCorpus = Self.decodeDefaultsValue(
      [String: [String: MeetingReadyAutomationDeliveryRecord]].self,
      defaults: defaults,
      key: meetingReadyAutomationDeliveriesByCorpusKey
    ) ?? [:]
    deliveriesByCorpus[corpusKey] = meetingReadyAutomationDeliveries
    if let data = try? JSONEncoder().encode(deliveriesByCorpus) {
      defaults.set(data, forKey: meetingReadyAutomationDeliveriesByCorpusKey)
    }
  }

  private func meetingReadyAutomationEventID(for item: MeetingWorkspaceItem) -> String {
    if let idValue = item.idValue?.trimmingCharacters(in: .whitespacesAndNewlines),
       !idValue.isEmpty {
      return "meeting-id:\(idValue)"
    }
    return "meeting-file:\(relativePath(item.file))"
  }

  private func meetingReadyAutomationMessageMarker(eventID: String) -> String {
    "#+org2_automation_event_id: meeting-ready:\(eventID)"
  }

  private func meetingTranscriptionDidComplete(_ item: MeetingWorkspaceItem) {
    // This is an event boundary, not a projection reconciliation. Never call it
    // while scanning corpus history: an existing completed meeting is not a new
    // local transcription-completed event.
    guard meetingReadyAutomationSettings.isEnabled else { return }
    guard item.transcriptionStatus?.lowercased() == MeetingTranscriptionStatus.complete.rawValue else {
      return
    }
    dispatchMeetingReadyAutomationIfNeeded(for: item)
  }

  func meetingTranscriptionDidCompleteForTesting(_ item: MeetingWorkspaceItem) {
    meetingTranscriptionDidComplete(item)
  }

  private func dispatchMeetingReadyAutomationIfNeeded(for item: MeetingWorkspaceItem) {
    let context = captureAIChatCorpusContext()
    let eventID = meetingReadyAutomationEventID(for: item)
    if let status = meetingReadyAutomationDeliveries[eventID]?.status,
       status == .baseline || status == .queued {
      return
    }
    guard !meetingReadyAutomationDispatchingEventIDs.contains(eventID) else { return }

    let marker = meetingReadyAutomationMessageMarker(eventID: eventID)
    if let existingDelivery = aiChatThreads.lazy.compactMap({ thread in
      thread.messages.first(where: { $0.role == .user && $0.content.contains(marker) })
        .map { (thread, $0) }
    }).first {
      meetingReadyAutomationDeliveries[eventID] = MeetingReadyAutomationDeliveryRecord(
        eventID: eventID,
        meetingFile: item.file,
        destinationID: existingDelivery.0.destinationID,
        threadID: existingDelivery.0.id,
        status: .queued,
        updatedAt: Date(),
        error: nil
      )
      persistMeetingReadyAutomationDeliveries()
      if existingDelivery.1.deliveryStatus == .failed
        || existingDelivery.1.deliveryStatus == .interrupted {
        meetingReadyAutomationStatusText = "Meeting delivery needs attention: \(item.title)"
      }
      return
    }

    meetingReadyAutomationDispatchingEventIDs.insert(eventID)
    let settings = meetingReadyAutomationSettings
    guard enabledAIChatDestinations.contains(where: { $0.id == settings.destinationID }) else {
      meetingReadyAutomationDispatchingEventIDs.remove(eventID)
      recordMeetingReadyAutomationFailure(
        eventID: eventID,
        item: item,
        threadID: nil,
        error: "The configured AI destination is unavailable"
      )
      return
    }

    let targetThread: AIChatThread?
    switch settings.threadMode {
    case .newThread:
      if let retryThreadID = meetingReadyAutomationDeliveries[eventID]?.threadID,
         let retryThread = aiChatThreads.first(where: { $0.id == retryThreadID }) {
        targetThread = retryThread
      } else {
        targetThread = createAIChatThread(
          title: Self.normalizedAIChatThreadTitle("Meeting: \(item.title)"),
          statusText: "Queued completed meeting",
          runtime: aiChatDestinationRuntime(settings.destinationID),
          destinationID: settings.destinationID,
          selectsThread: false
        )
      }
    case .existingThread:
      targetThread = settings.threadID.flatMap { targetID in
        aiChatThreads.first(where: {
          $0.id == targetID && !$0.isSharedRoom && $0.destinationID == settings.destinationID
        })
      }
    }

    guard let targetThread else {
      meetingReadyAutomationDispatchingEventIDs.remove(eventID)
      recordMeetingReadyAutomationFailure(
        eventID: eventID,
        item: item,
        threadID: settings.threadID,
        error: "The configured meeting thread could not be found"
      )
      return
    }
    if targetThread.isSettled {
      reopenAIChatThread(targetThread.id)
    }

    let pointer = aiChatContextPointer(for: .meeting(item))
    let text = automaticAIChatActionText(
      pointer,
      prompt: settings.prompt + "\n\n" + marker
    )
    let enqueueResult = queueAIChatAutomationMessage(
      text,
      threadID: targetThread.id,
      marker: marker,
      context: context
    )
    switch enqueueResult {
    case .rejected:
      finishMeetingReadyAutomationEnqueue(
        .rejected,
        eventID: eventID,
        item: item,
        threadID: targetThread.id,
        settings: settings,
        context: context
      )
    case .enqueued(let acceptedThreadID, let shouldDrain):
      if shouldDrain {
        Task { @MainActor [weak self] in
          await self?.drainAIChatSendQueue(for: acceptedThreadID)
        }
      }
      finishMeetingReadyAutomationEnqueue(
        .enqueued(threadID: acceptedThreadID, shouldDrain: false),
        eventID: eventID,
        item: item,
        threadID: targetThread.id,
        settings: settings,
        context: context
      )
    case .deferred(let task):
      Task { @MainActor [weak self] in
        guard let self else { return }
        let outcome = await task.value
        self.finishMeetingReadyAutomationEnqueue(
          outcome,
          eventID: eventID,
          item: item,
          threadID: targetThread.id,
          settings: settings,
          context: context
        )
      }
    }
  }

  private func finishMeetingReadyAutomationEnqueue(
    _ outcome: AIChatEnqueueOutcome,
    eventID: String,
    item: MeetingWorkspaceItem,
    threadID: UUID,
    settings: MeetingReadyAutomationSettings,
    context: AIChatCorpusContextToken
  ) {
    guard isCurrentAIChatCorpusContext(context) else {
      let status: MeetingReadyAutomationDeliveryStatus
      let error: String?
      switch outcome {
      case .enqueued:
        status = .queued
        error = nil
      case .rejected, .superseded:
        status = .failed
        error = "Corpus changed before the meeting message could be queued; retry when this corpus is active"
      }
      persistMeetingReadyAutomationDelivery(
        MeetingReadyAutomationDeliveryRecord(
          eventID: eventID,
          meetingFile: item.file,
          destinationID: settings.destinationID,
          threadID: threadID,
          status: status,
          updatedAt: Date(),
          error: error
        ),
        corpusPath: context.corpusRootPath
      )
      meetingReadyAutomationEnqueueDidResolveForTesting?(eventID)
      return
    }
    meetingReadyAutomationDispatchingEventIDs.remove(eventID)
    switch outcome {
    case .enqueued:
      meetingReadyAutomationDeliveries[eventID] = MeetingReadyAutomationDeliveryRecord(
        eventID: eventID,
        meetingFile: item.file,
        destinationID: settings.destinationID,
        threadID: threadID,
        status: .queued,
        updatedAt: Date(),
        error: nil
      )
      persistMeetingReadyAutomationDeliveries()
      meetingReadyAutomationStatusText = "Queued \(item.title) to \(aiChatDestinationTitle(settings.destinationID))"
    case .rejected:
      recordMeetingReadyAutomationFailure(
        eventID: eventID,
        item: item,
        threadID: threadID,
        error: "The meeting message could not be queued"
      )
    case .superseded:
      break
    }
    meetingReadyAutomationEnqueueDidResolveForTesting?(eventID)
  }

  private func persistMeetingReadyAutomationDelivery(
    _ record: MeetingReadyAutomationDeliveryRecord,
    corpusPath: String?
  ) {
    guard let corpusPath else { return }
    var deliveriesByCorpus = Self.decodeDefaultsValue(
      [String: [String: MeetingReadyAutomationDeliveryRecord]].self,
      defaults: defaults,
      key: meetingReadyAutomationDeliveriesByCorpusKey
    ) ?? [:]
    var deliveries = deliveriesByCorpus[corpusPath] ?? [:]
    if let existing = deliveries[record.eventID],
       existing.status == .queued || existing.status == .baseline {
      return
    }
    deliveries[record.eventID] = record
    deliveriesByCorpus[corpusPath] = deliveries
    if let data = try? JSONEncoder().encode(deliveriesByCorpus) {
      defaults.set(data, forKey: meetingReadyAutomationDeliveriesByCorpusKey)
    }
  }

  private func recordMeetingReadyAutomationFailure(
    eventID: String,
    item: MeetingWorkspaceItem,
    threadID: UUID?,
    error: String
  ) {
    meetingReadyAutomationDeliveries[eventID] = MeetingReadyAutomationDeliveryRecord(
      eventID: eventID,
      meetingFile: item.file,
      destinationID: meetingReadyAutomationSettings.destinationID,
      threadID: threadID,
      status: .failed,
      updatedAt: Date(),
      error: error
    )
    persistMeetingReadyAutomationDeliveries()
    meetingReadyAutomationStatusText = "Meeting delivery pending: \(error)"
  }

  private func queueAIChatAutomationMessage(
    _ text: String,
    threadID: UUID,
    marker: String,
    context: AIChatCorpusContextToken
  ) -> AIChatEnqueueResult {
    guard isCurrentAIChatCorpusContext(context) else { return .rejected }
    if unloadedAIChatThreadIDs.contains(threadID) {
      hydrateAIChatThread(threadID)
      let deferred: Task<AIChatEnqueueOutcome, Never> = Task { @MainActor [weak self] in
        guard let self else { return .rejected }
        let hydrated = await self.hydrateAIChatThreadIfNeeded(threadID)
        guard self.isCurrentAIChatCorpusContext(context) else { return .superseded }
        guard let hydrated else { return .rejected }
        if hydrated.messages.contains(where: { $0.role == .user && $0.content.contains(marker) }) {
          return .enqueued(threadID: threadID, shouldDrain: false)
        }
        let retry = self.enqueueAIChatMessage(
          text,
          attachments: [],
          in: threadID,
          deliveryKind: self.isAIChatThreadRunning(threadID) ? .followUp : .turn,
          context: context
        )
        return await self.resolveDeferredAIChatEnqueue(retry)
      }
      return .deferred(deferred)
    }
    if aiChatMessages(for: threadID).contains(where: {
      $0.role == .user && $0.content.contains(marker)
    }) {
      return .enqueued(threadID: threadID, shouldDrain: false)
    }
    return enqueueAIChatMessage(
      text,
      attachments: [],
      in: threadID,
      deliveryKind: isAIChatThreadRunning(threadID) ? .followUp : .turn,
      context: context
    )
  }

  public func requestOpenClawGatewayPairing() async {
    aiChatStatusText = "Requesting Gateway device access…"
    do {
      let client = OpenClawGatewayClient(settings: currentOpenClawSettings(allowKeychainRead: true))
      try await client.prepare()
      if openClawLocalEditsEnabled {
        startOpenClawLocalEditNode()
        aiChatStatusText = "OpenClaw operator access is live; local edit node pairing requested"
      } else {
        aiChatStatusText = "OpenClaw Gateway device is paired and live"
      }
      await refreshAIChatCommands(force: true)
    } catch let error as OpenClawGatewayError {
      aiChatStatusText = error.localizedDescription
    } catch {
      aiChatStatusText = "Gateway pairing failed: \(error.localizedDescription)"
    }
  }

  public var openClawLocalEditNodeDisplayName: String {
    let bundleID = Bundle.main.bundleIdentifier ?? ""
    return bundleID.hasSuffix(".codex")
      ? "Celorga Local Edits (Codex)"
      : "Celorga Local Edits"
  }

  private func localEditBroker() -> AIChatLocalEditBroker {
    if let aiChatLocalEditBroker {
      return aiChatLocalEditBroker
    }
    let broker = AIChatLocalEditBroker(
      documentReader: { [weak self] turnID, path, requestedRoot in
        guard let self else { throw AIChatLocalEditError.inactiveTurn }
        let corpusRoot = try self.authorizedAIChatCorpusRoot(
          turnID: turnID,
          requestedRoot: requestedRoot
        )
        return try self.aiChatLocalEditDocument(at: path, corpusRoot: corpusRoot)
      },
      replacementApplier: { [weak self] turnID, replacements in
        guard let self else { throw AIChatLocalEditError.inactiveTurn }
        let corpusRoot = try self.aiChatLocalEditCorpus(for: turnID)
        return try await self.applyAIChatLocalEditReplacements(
          replacements,
          corpusRoot: corpusRoot
        )
      }
    )
    aiChatLocalEditBroker = broker
    return broker
  }

  private func aiChatLocalEditCorpus(for turnID: String) throws -> URL {
    guard let expectedRoot = aiChatLocalEditCorpusRootsByTurnID[turnID] else {
      throw AIChatLocalEditError.inactiveTurn
    }
    return expectedRoot
  }

  private func startOpenClawLocalEditNode() {
    guard openClawLocalEditsEnabled else {
      openClawLocalEditNodeState = .disabled
      openClawLocalEditNodeDetail = ""
      return
    }
    guard corpusRoot != nil else {
      openClawLocalEditNodeState = .stopped
      openClawLocalEditNodeDetail = "Choose a corpus before starting local edits."
      return
    }
    guard openClawLocalEditNodeTask == nil else { return }

    let node = OpenClawLocalEditNode(
      settings: currentOpenClawSettings(allowKeychainRead: true),
      broker: localEditBroker(),
      displayName: openClawLocalEditNodeDisplayName
    ) { [weak self] state, detail in
      guard let self else { return }
      self.openClawLocalEditNodeState = state
      self.openClawLocalEditNodeDetail = detail ?? ""
    }
    openClawLocalEditNode = node
    openClawLocalEditNodeTask = Task { @MainActor [weak self, node] in
      await node.run()
      guard let self, self.openClawLocalEditNode === node else { return }
      self.openClawLocalEditNodeTask = nil
      self.openClawLocalEditNode = nil
    }
  }

  private func restartOpenClawLocalEditNode() {
    let previousNode = openClawLocalEditNode
    openClawLocalEditNodeTask?.cancel()
    openClawLocalEditNodeTask = nil
    openClawLocalEditNode = nil
    if !openClawLocalEditsEnabled {
      openClawLocalEditNodeState = .disabled
      openClawLocalEditNodeDetail = ""
    }
    Task { @MainActor [weak self] in
      await previousNode?.stop()
      guard let self, self.openClawLocalEditsEnabled else { return }
      self.startOpenClawLocalEditNode()
    }
  }

  func aiChatLocalEditDocument(
    at rawPath: String,
    corpusRoot requestedCorpusRoot: URL? = nil,
    enforcesSnapshotSizeLimit: Bool = true
  ) throws -> AIChatLocalEditDocument {
    // The broker's read callback is intentionally synchronous today. Keep
    // this explicit request path compatible with that cross-file contract;
    // the latency-sensitive multi-file apply preflight below is detached.
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else {
      throw AIChatLocalEditError.invalidRequest("no active corpus")
    }
    let url = try aiChatLocalEditURL(for: rawPath, corpusRoot: corpusRoot)
    let relativePath = Self.relativePath(for: url.path, root: corpusRoot)
    let diskBaseline = try Self.aiChatLocalEditDiskBaseline(at: url)
    return try Self.aiChatLocalEditDocument(
      relativePath: relativePath,
      url: url,
      diskBaseline: diskBaseline,
      overlay: aiChatLocalEditOverlay(for: corpusRoot),
      enforcesSnapshotSizeLimit: enforcesSnapshotSizeLimit
    )
  }

  private func aiChatLocalEditOverlay(for requestedCorpusRoot: URL) -> AIChatLocalEditOverlay? {
    guard corpusRoot?.standardizedFileURL.path == requestedCorpusRoot.standardizedFileURL.path,
          let source = selectedEntrySource
    else { return nil }
    let file = URL(fileURLWithPath: source.file).standardizedFileURL.path
    let selectedFile = selectedEntrySource?.file ?? selectedLocation?.file
    guard selectedFile.map({
      URL(fileURLWithPath: $0).standardizedFileURL.path == file
    }) == true else { return nil }

    if isLiveFileEditorSelected {
      guard source.startLine == 1, !source.isSubtree else {
        return .invalidWholeFile(file: file)
      }
      return .wholeFile(
        file: file,
        text: editableEntryText,
        isDirty: liveFileEditorHasUnsavedChanges
      )
    }
    if isEditingEntry {
      return .sourceRange(
        file: file,
        source: source,
        replacement: sourceEditorLocalDraftText ?? editableEntryText,
        isDirty: entryEditorHasUnsavedChanges
      )
    }
    if let block = activeEditingBlock, transientDraftBlock == nil {
      let sourceBlock = activeBlockOriginals[block.id] ?? block
      return .sourceRange(
        file: file,
        source: EntrySource(
          file: source.file,
          startLine: sourceBlock.startLine,
          endLineExclusive: sourceBlock.endLineExclusive,
          text: sourceBlock.rawText,
          isSubtree: false
        ),
        replacement: saveReplacementText(for: block),
        isDirty: true
      )
    }
    return nil
  }

  private func aiChatLocalEditPreparationIdentity() -> AIChatLocalEditPreparationIdentity {
    AIChatLocalEditPreparationIdentity(
      corpusSessionGeneration: corpusSessionGeneration,
      selectedSourceID: selectedEntrySource?.id,
      sourceDraftGeneration: sourceEditorDraftGeneration,
      liveDraftGeneration: liveFileEditorDraftGeneration
    )
  }

  nonisolated private static func aiChatLocalEditDocument(
    relativePath: String,
    url: URL,
    diskBaseline: AIChatLocalEditDiskBaseline,
    overlay: AIChatLocalEditOverlay?,
    enforcesSnapshotSizeLimit: Bool
  ) throws -> AIChatLocalEditDocument {
    guard diskBaseline.existed else {
      return AIChatLocalEditDocument(relativePath: relativePath, text: "", origin: .missing)
    }
    let diskText = diskBaseline.text
    guard !enforcesSnapshotSizeLimit
      || diskText.utf8.count <= Self.aiChatChangeSnapshotMaxFileBytes
    else {
      throw AIChatLocalEditError.oversizedRequest
    }

    guard let overlay,
          WorkspaceDocumentMutationLane.canonicalPath(overlay.file)
            == WorkspaceDocumentMutationLane.canonicalPath(url.path)
    else {
      return AIChatLocalEditDocument(
        relativePath: relativePath,
        text: diskText,
        origin: .disk
      )
    }

    switch overlay {
    case .invalidWholeFile:
      throw AIChatLocalEditError.invalidRequest(
        "the selected file editor is not a whole-file editor"
      )
    case .wholeFile(_, let text, let isDirty):
      return AIChatLocalEditDocument(
        relativePath: relativePath,
        text: text,
        origin: isDirty ? .editor : .disk
      )
    case .sourceRange(_, let source, let replacement, let isDirty):
      guard source.file == overlay.file else {
        throw AIChatLocalEditError.invalidRequest("the selected file editor is not a whole-file editor")
      }
      let effective = try Self.aiChatEffectiveFileText(
        diskText: diskText,
        source: source,
        replacement: replacement
      )
      return AIChatLocalEditDocument(
        relativePath: relativePath,
        text: effective,
        origin: isDirty ? .editor : .disk
      )
    }
  }

  nonisolated private static func aiChatLocalEditDiskBaseline(
    at url: URL
  ) throws -> AIChatLocalEditDiskBaseline {
    guard FileManager.default.fileExists(atPath: url.path) else {
      return AIChatLocalEditDiskBaseline(existed: false, text: "")
    }
    return AIChatLocalEditDiskBaseline(
      existed: true,
      text: try String(contentsOf: url, encoding: .utf8)
    )
  }

  nonisolated private static func prepareAIChatLocalEdits(
    _ replacements: [AIChatLocalEditReplacement],
    corpusRoot: URL,
    overlay: AIChatLocalEditOverlay?
  ) throws -> PreparedAIChatLocalEdits {
    var documents: [String: AIChatLocalEditDocument] = [:]
    var urls: [String: URL] = [:]
    var diskBaselines: [String: AIChatLocalEditDiskBaseline] = [:]
    var changes: [AIChatCorpusFileChange] = []
    documents.reserveCapacity(replacements.count)
    urls.reserveCapacity(replacements.count)
    diskBaselines.reserveCapacity(replacements.count)
    changes.reserveCapacity(replacements.count)

    for replacement in replacements {
      let url = try aiChatLocalEditURL(
        for: replacement.relativePath,
        corpusRoot: corpusRoot
      )
      let relativePath = Self.relativePath(for: url.path, root: corpusRoot)
      let diskBaseline = try aiChatLocalEditDiskBaseline(at: url)
      let document = try aiChatLocalEditDocument(
        relativePath: relativePath,
        url: url,
        diskBaseline: diskBaseline,
        overlay: overlay,
        enforcesSnapshotSizeLimit: true
      )
      if replacement.createsFile {
        guard document.origin == .missing else {
          throw AIChatLocalEditError.staleDocument(document.relativePath)
        }
      } else {
        guard document.origin != .missing,
              document.sha256 == replacement.expectedSHA256
        else {
          throw AIChatLocalEditError.staleDocument(document.relativePath)
        }
      }
      documents[replacement.relativePath] = document
      urls[replacement.relativePath] = url
      diskBaselines[replacement.relativePath] = diskBaseline
      if let change = AIChatLocalEditBroker.fileChange(
        path: document.relativePath,
        before: replacement.createsFile ? nil : document.text,
        after: replacement.replacementText
      ) {
        changes.append(change)
      }
    }
    return PreparedAIChatLocalEdits(
      documents: documents,
      urls: urls,
      diskBaselines: diskBaselines,
      changes: changes
    )
  }

  func applyAIChatLocalEditReplacements(
    _ replacements: [AIChatLocalEditReplacement],
    corpusRoot requestedCorpusRoot: URL? = nil
  ) async throws -> AIChatLocalEditApplyResult {
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else {
      throw AIChatLocalEditError.invalidRequest("no active corpus")
    }
    let isActiveCorpus = self.corpusRoot?.standardizedFileURL.path
      == corpusRoot.standardizedFileURL.path
    let overlay = isActiveCorpus ? aiChatLocalEditOverlay(for: corpusRoot) : nil
    let preparationIdentity = aiChatLocalEditPreparationIdentity()
    let prepared = try await Task.detached(priority: .userInitiated) {
      try Self.prepareAIChatLocalEdits(
        replacements,
        corpusRoot: corpusRoot,
        overlay: overlay
      )
    }.value
    if isActiveCorpus,
       preparationIdentity != aiChatLocalEditPreparationIdentity() {
      throw AIChatLocalEditError.staleDocument(
        URL(fileURLWithPath: overlay?.file ?? corpusRoot.path).lastPathComponent
      )
    }
    let documents = prepared.documents
    let urls = prepared.urls
    let diskBaselines = prepared.diskBaselines
    let changes = prepared.changes

    let selectedPath = isActiveCorpus ? selectedEntrySource.map {
      URL(fileURLWithPath: $0.file).standardizedFileURL.path
    } : nil
    if replacements.contains(where: { urls[$0.relativePath]?.standardizedFileURL.path == selectedPath }) {
      cancelLiveFileEditorAutosave(resetStatus: false)
    }

    guard let mutationContext = captureDocumentCorpusContext(mutationRoot: corpusRoot) else {
      throw AIChatLocalEditError.inactiveTurn
    }
    let preparedURLs = urls
    let preparedDocuments = documents
    let preparedDiskBaselines = diskBaselines
    let resourcePaths = preparedURLs.values.map(\.path)
    try await performDocumentMutation(
      context: mutationContext,
      files: resourcePaths
    ) { execution in
      var snapshots: [String: WorkspaceDocumentSnapshot] = [:]
      for replacement in replacements {
        guard let url = preparedURLs[replacement.relativePath],
              let document = preparedDocuments[replacement.relativePath],
              let baseline = preparedDiskBaselines[replacement.relativePath]
        else {
          throw AIChatLocalEditError.invalidRequest("missing prepared replacement")
        }
        let snapshot = try await execution.readSnapshot(at: url, allowMissing: true)
        guard snapshot.existed == baseline.existed,
              snapshot.text == baseline.text
        else {
          throw AIChatLocalEditError.staleDocument(document.relativePath)
        }
        snapshots[replacement.relativePath] = snapshot
      }

      var committed: [(AIChatLocalEditReplacement, WorkspaceDocumentSnapshot)] = []
      do {
        for replacement in replacements {
          guard let snapshot = snapshots[replacement.relativePath] else {
            throw AIChatLocalEditError.invalidRequest("missing prepared replacement")
          }
          try await execution.commit(replacement.replacementText, over: snapshot) {
            text, url, previous in
            _ = try Self.aiChatLocalEditURL(
              for: replacement.relativePath,
              corpusRoot: corpusRoot
            )
            if replacement.createsFile {
              try FileManager.default.createDirectory(
                at: url.deletingLastPathComponent(),
                withIntermediateDirectories: true
              )
            }
            try Self.commitDocumentText(
              text,
              url: url,
              previousText: previous,
              operation: "AI local edit"
            )
          }
          committed.append((replacement, snapshot))
        }
      } catch {
        for (replacement, original) in committed.reversed() {
          guard let current = try? await execution.readSnapshot(at: original.url) else { continue }
          guard current.text == replacement.replacementText else { continue }
          if original.existed {
            try? await execution.commit(original.text, over: current) { text, url, previous in
              try Self.commitDocumentText(
                text,
                url: url,
                previousText: previous,
                operation: "AI local edit rollback",
                allowDestructiveReplacement: true
              )
            }
          } else {
            try? await execution.commit("", over: current) { _, url, _ in
              try FileManager.default.removeItem(at: url)
            }
          }
        }
        throw error
      }
    }

    let refreshedCorpusFiles: [String: CorpusFile]
    if isActiveCorpus {
      let preparedURLs = urls
      refreshedCorpusFiles = await Task.detached(priority: .utility) {
        Dictionary(uniqueKeysWithValues: preparedURLs.values.map { url in
          (
            url.standardizedFileURL.path,
            Self.corpusFileOffMain(for: url, corpusRoot: corpusRoot)
          )
        })
      }.value
    } else {
      refreshedCorpusFiles = [:]
    }

    for replacement in replacements {
      guard let document = documents[replacement.relativePath],
            let url = urls[replacement.relativePath]
      else { continue }
      if isActiveCorpus {
        recordWorkspaceUndo(
          .fileSnapshot(
            file: url.standardizedFileURL.path,
            previous: replacement.createsFile ? nil : document.text,
            next: replacement.replacementText
          )
        )
        invalidateCanonicalDocumentCache(for: url.path)
        if let file = refreshedCorpusFiles[url.standardizedFileURL.path] {
          upsertCorpusFile(file)
        }
      }
    }

    if isActiveCorpus,
       let selectedLocation,
       let selectedReplacement = replacements.first(where: {
         urls[$0.relativePath]?.standardizedFileURL.path
           == URL(fileURLWithPath: selectedLocation.file).standardizedFileURL.path
       }) {
      isEditingEntry = false
      resetBlockState()
      await loadEntrySource(for: selectedLocation)
      if isLiveFileEditorSelected, selectedEntrySourceMode == .page {
        if let selectedEntrySource {
          self.selectedEntrySource = Self.entrySource(
            selectedEntrySource,
            replacingText: selectedReplacement.replacementText
          )
        }
        replaceEditableEntryTextFromModel(selectedReplacement.replacementText)
        liveFileEditorStatusText = "Saved by AI"
      }
    }
    if isActiveCorpus {
      scheduleAgendaRefresh(preserveSelection: true)
    } else {
      invalidateCachedCorpusWorkspace(
        at: corpusRoot.path,
        surfaces: Set(WorkspaceSurface.allCases.filter { $0 != .home })
      )
    }

    return AIChatLocalEditApplyResult(
      summary: AIChatCorpusChangeSummary(files: changes)
    )
  }

  private func aiChatLocalEditURL(
    for rawPath: String,
    corpusRoot requestedCorpusRoot: URL? = nil
  ) throws -> URL {
    guard let corpusRoot = requestedCorpusRoot ?? corpusRoot else {
      throw AIChatLocalEditError.invalidRequest("no active corpus")
    }
    return try Self.aiChatLocalEditURL(for: rawPath, corpusRoot: corpusRoot)
  }

  nonisolated private static func aiChatLocalEditURL(
    for rawPath: String,
    corpusRoot: URL
  ) throws -> URL {
    let path = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !path.isEmpty,
          !path.hasPrefix("/"),
          !path.split(separator: "/").contains(where: { $0 == ".." })
    else {
      throw AIChatLocalEditError.invalidRequest("path must be relative to the active corpus")
    }
    let root = corpusRoot.standardizedFileURL.resolvingSymlinksInPath()
    let candidate = root.appendingPathComponent(path).standardizedFileURL
    let resolvedParent = candidate.deletingLastPathComponent().resolvingSymlinksInPath()
    guard resolvedParent.path == root.path || resolvedParent.path.hasPrefix(root.path + "/") else {
      throw AIChatLocalEditError.invalidRequest("path escapes the active corpus")
    }
    // Missing parents are valid for read/preview; only apply creates them.
    // Check the nearest existing ancestor without following a dangling link.
    var ancestor = candidate.deletingLastPathComponent()
    var isDirectory: ObjCBool = false
    while !FileManager.default.fileExists(atPath: ancestor.path, isDirectory: &isDirectory) {
      if (try? FileManager.default.destinationOfSymbolicLink(atPath: ancestor.path)) != nil {
        throw AIChatLocalEditError.invalidRequest("parent directory is a dangling symlink")
      }
      let parent = ancestor.deletingLastPathComponent()
      guard parent.path != ancestor.path else {
        throw AIChatLocalEditError.invalidRequest("no existing parent directory")
      }
      ancestor = parent
    }
    guard isDirectory.boolValue else {
      throw AIChatLocalEditError.invalidRequest("parent path is not a directory")
    }
    let resolvedAncestor = ancestor.resolvingSymlinksInPath()
    guard resolvedAncestor.path == root.path || resolvedAncestor.path.hasPrefix(root.path + "/") else {
      throw AIChatLocalEditError.invalidRequest("path escapes the active corpus")
    }
    if FileManager.default.fileExists(atPath: candidate.path) {
      let resolved = candidate.resolvingSymlinksInPath()
      guard resolved.path.hasPrefix(root.path + "/") else {
        throw AIChatLocalEditError.invalidRequest("path escapes the active corpus")
      }
    }
    guard Self.aiChatChangeSnapshotAllowedExtensions.contains(candidate.pathExtension.lowercased()) else {
      throw AIChatLocalEditError.invalidRequest("unsupported file type")
    }
    return candidate
  }

  nonisolated private static func aiChatEffectiveFileText(
    diskText: String,
    source: EntrySource,
    replacement: String
  ) throws -> String {
    let normalizedDisk = normalizeLineEndings(diskText)
    var lines = normalizedDisk
      .split(separator: "\n", omittingEmptySubsequences: false)
      .map(String.init)
    let startIndex = source.startLine - 1
    let endIndex = source.endLineExclusive - 1
    guard startIndex >= 0,
          startIndex <= lines.count,
          endIndex >= startIndex,
          endIndex <= lines.count
    else {
      throw AIChatLocalEditError.invalidRequest("the selected editor range is no longer valid")
    }
    let currentSource = lines[startIndex..<endIndex].joined(separator: "\n")
    guard currentSource == normalizeLineEndings(source.text) else {
      throw AIChatLocalEditError.staleDocument(
        URL(fileURLWithPath: source.file).lastPathComponent
      )
    }
    let normalizedReplacement = normalizeLineEndings(replacement)
    let replacementLines = normalizedReplacement.isEmpty
      ? []
      : normalizedReplacement
        .split(separator: "\n", omittingEmptySubsequences: false)
        .map(String.init)
    lines.replaceSubrange(startIndex..<endIndex, with: replacementLines)
    var output = lines.joined(separator: "\n")
    if normalizedDisk.hasSuffix("\n"), !output.isEmpty, !output.hasSuffix("\n") {
      output += "\n"
    }
    return output
  }

  public var aiChatAvailableSlashCommands: [AIChatSlashCommand] {
    AIChatSlashCommands.merged(
      with: openClawGatewayCommands,
      corpusSkills: corpusAgentSkillCommands
    )
  }

  public var activeAIChatGatewayCommands: [AIChatSlashCommand] {
    selectedAIChatRuntime == .openClaw ? openClawGatewayCommands : []
  }

  public func refreshCorpusAgentSkills(force: Bool = false) {
    guard let root = corpusRoot?.standardizedFileURL else {
      corpusAgentSkillRefreshGeneration &+= 1
      corpusAgentSkillRefreshTask?.cancel()
      corpusAgentSkillCommands = []
      workspaceSkills = []
      selectedWorkspaceSkillID = nil
      corpusAgentSkillRefreshTask = nil
      corpusAgentSkillLoadedCorpusPath = nil
      corpusAgentSkillRefreshCorpusPath = nil
      return
    }
    let rootPath = root.path
    if !force,
       corpusAgentSkillLoadedCorpusPath == rootPath
        || (corpusAgentSkillRefreshTask != nil
          && corpusAgentSkillRefreshCorpusPath == rootPath) {
      return
    }
    corpusAgentSkillRefreshGeneration &+= 1
    let generation = corpusAgentSkillRefreshGeneration
    corpusAgentSkillRefreshTask?.cancel()
    corpusAgentSkillRefreshCorpusPath = rootPath
    let sessionGeneration = corpusSessionGeneration
    let observer = corpusAgentSkillDiscoveryForTesting
    corpusAgentSkillRefreshTask = Task { @MainActor [weak self] in
      async let preparedCommands = CorpusAgentSkillCatalog.prepareCommands(
        in: root,
        force: force,
        discoveryThreadObserver: observer
      )
      async let preparedSkills = Task.detached(priority: .utility) {
        WorkspaceSkillCatalog.discover(in: root)
      }.value
      let (commands, skills) = await (preparedCommands, preparedSkills)
      guard let self,
            !Task.isCancelled,
            self.corpusAgentSkillRefreshGeneration == generation,
            self.isCurrentCorpusSession(root: root, generation: sessionGeneration)
      else { return }
      self.corpusAgentSkillCommands = commands
      self.workspaceSkills = skills
      self.corpusAgentSkillLoadedCorpusPath = rootPath
      self.corpusAgentSkillRefreshCorpusPath = nil
      if let selectedID = self.selectedWorkspaceSkillID,
         !skills.contains(where: { $0.id == selectedID }) {
        self.selectedWorkspaceSkillID = nil
      }
      self.corpusAgentSkillRefreshTask = nil
    }
  }

  func waitForCorpusAgentSkillRefreshForTesting() async {
    while let task = corpusAgentSkillRefreshTask {
      let generation = corpusAgentSkillRefreshGeneration
      await task.value
      await Task.yield()
      if corpusAgentSkillRefreshGeneration == generation,
         corpusAgentSkillRefreshTask == nil {
        return
      }
    }
  }

  public func selectWorkspaceSkill(_ skill: WorkspaceSkillItem) {
    selectedWorkspaceSkillID = skill.id
    openWorkspaceSkillFile(at: URL(fileURLWithPath: skill.sourcePath))
  }

  private func openWorkspaceSkillFile(at rawURL: URL) {
    let url = rawURL.standardizedFileURL
    let values = try? url.resourceValues(forKeys: [.contentModificationDateKey, .fileSizeKey])
    selectCorpusFile(CorpusFile(
      path: url.path,
      relativePath: relativePath(url.path),
      modifiedAt: values?.contentModificationDate,
      byteCount: values?.fileSize.map(Int64.init)
    ), surface: .skills)
  }

  @discardableResult
  public func createWorkspaceSkill(name rawName: String, description: String) -> Bool {
    guard let corpusRoot else { return false }
    let rawName = rawName.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
    let name = WorkspaceSkillCatalog.normalizedSkillName(rawName)
    guard !name.isEmpty, name == rawName else {
      errorText = "Use lowercase letters, digits, and hyphens for the skill name."
      statusText = "Invalid skill name"
      return false
    }
    guard name != "org2" else {
      errorText = "The name org2 is reserved for Celorga's built-in operating guidance."
      statusText = "Reserved skill name"
      return false
    }
    let summary = description
      .split(whereSeparator: { $0.isWhitespace })
      .joined(separator: " ")
    guard !summary.isEmpty else {
      errorText = "Add a short description of when the skill should be used."
      statusText = "Skill description required"
      return false
    }
    let skillsRoot = corpusRoot
      .appendingPathComponent(".agents", isDirectory: true)
      .appendingPathComponent("skills", isDirectory: true)
    let directory = skillsRoot.appendingPathComponent(name, isDirectory: true)
    let destination = directory.appendingPathComponent("SKILL.md")
    do {
      try assertSafeWorkspaceSkillParents(corpusRoot: corpusRoot, target: skillsRoot)
      guard !FileManager.default.fileExists(atPath: destination.path) else {
        errorText = "A workspace skill named \(name) already exists."
        statusText = "Skill already exists"
        return false
      }
      try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
      try assertSafeWorkspaceSkillParents(corpusRoot: corpusRoot, target: directory)
      let source = WorkspaceSkillCatalog.newSkillSource(name: name, description: summary)
      try Data(source.utf8).write(to: destination, options: .withoutOverwriting)
      selectedWorkspaceSkillID = destination.standardizedFileURL.path
      openWorkspaceSkillFile(at: destination)
      refreshCorpusAgentSkills(force: true)
      statusText = "Created /\(name)"
      return true
    } catch {
      errorText = error.localizedDescription
      statusText = "Could not create the skill"
      return false
    }
  }

  public func moveWorkspaceSkillToTrash(_ skill: WorkspaceSkillItem) async {
    guard let corpusRoot else { return }
    let skillsRoot = corpusRoot
      .appendingPathComponent(".agents", isDirectory: true)
      .appendingPathComponent("skills", isDirectory: true)
      .standardizedFileURL
    let skillFile = URL(fileURLWithPath: skill.sourcePath).standardizedFileURL
    let directory = skillFile.deletingLastPathComponent()
    guard skillFile.lastPathComponent == "SKILL.md",
          directory.deletingLastPathComponent() == skillsRoot
    else {
      errorText = "Only top-level workspace skill folders can be removed."
      statusText = "Skill could not be removed"
      return
    }
    do {
      let removesSelectedDetail = selectedLocation?.file == skillFile.path
      if removesSelectedDetail {
        persistLiveFileEditorDraftBeforeNavigation()
        guard await awaitPendingEditorPersistence() else {
          statusText = "Save the current skill before removing it"
          return
        }
      }
      var resultingURL: NSURL?
      try FileManager.default.trashItem(at: directory, resultingItemURL: &resultingURL)
      if removesSelectedDetail {
        clearDetailForNavigation()
      }
      if selectedWorkspaceSkillID == skill.id { selectedWorkspaceSkillID = nil }
      if removesSelectedDetail {
        isWorkspaceSurfacePaneClosed = false
        isWorkspaceDetailPaneClosed = true
        activeWorkspacePane = .surface
      }
      refreshCorpusAgentSkills(force: true)
      statusText = "Moved /\(skill.name) to Trash"
    } catch {
      errorText = error.localizedDescription
      statusText = "Could not move the skill to Trash"
    }
  }

  private func assertSafeWorkspaceSkillParents(corpusRoot: URL, target: URL) throws {
    let root = corpusRoot.standardizedFileURL
    let target = target.standardizedFileURL
    guard target.path.hasPrefix(root.path + "/.agents") else {
      throw CocoaError(.fileWriteNoPermission, userInfo: [NSFilePathErrorKey: target.path])
    }
    var current = root
    let components = target.pathComponents.dropFirst(root.pathComponents.count)
    for component in components {
      current.appendPathComponent(component, isDirectory: true)
      guard FileManager.default.fileExists(atPath: current.path) else { continue }
      let values = try current.resourceValues(forKeys: [.isDirectoryKey, .isSymbolicLinkKey])
      guard values.isDirectory == true, values.isSymbolicLink != true else {
        throw CocoaError(.fileWriteNoPermission, userInfo: [NSFilePathErrorKey: current.path])
      }
    }
  }

  public var aiChatCommandDiscoveryID: String {
    let agentID = OpenClawChatClient.openClawAgentHeaderValue(for: openClawAgentID)
    return "\(openClawEndpointText.trimmingCharacters(in: .whitespacesAndNewlines))#\(agentID)"
  }

  public func refreshAIChatCommands(force: Bool = false) async {
    // Documentation screenshots use a synthetic corpus and must remain fully
    // deterministic. In particular, do not let SwiftUI's chat-view task prompt
    // for the developer's real Keychain token or contact a live Gateway while
    // the offscreen renderer is taking a snapshot.
    if CelorgaNames.environment("ORG2_WORKSPACE_SCREENSHOT_CORPUS") != nil {
      openClawGatewayCommands = []
      isRefreshingAIChatCommands = false
      return
    }

    let discoveryID = aiChatCommandDiscoveryID
    let now = Date()
    if aiChatActiveCommandDiscoveryID != discoveryID {
      aiChatActiveCommandDiscoveryID = discoveryID
      openClawGatewayCommands = aiChatCommandCache[discoveryID]?.commands ?? []
    }
    if !force,
       let cached = aiChatCommandCache[discoveryID],
       now.timeIntervalSince(cached.refreshedAt) < 300 {
      openClawGatewayCommands = cached.commands
      return
    }

    aiChatCommandDiscoveryGeneration += 1
    let generation = aiChatCommandDiscoveryGeneration
    isRefreshingAIChatCommands = true
    defer {
      if generation == aiChatCommandDiscoveryGeneration {
        isRefreshingAIChatCommands = false
      }
    }

    do {
      let settings = currentOpenClawSettings(allowKeychainRead: true)
      let agentID = OpenClawChatClient.openClawAgentHeaderValue(for: openClawAgentID)
      let commands = try await OpenClawGatewayClient(settings: settings).listCommands(agentID: agentID)
      aiChatCommandCache[discoveryID] = (commands, now)
      guard generation == aiChatCommandDiscoveryGeneration,
            discoveryID == aiChatCommandDiscoveryID
      else { return }
      openClawGatewayCommands = commands
    } catch {
      // Discovery is an enhancement. Keep a previously fetched catalog when the
      // Gateway is temporarily unavailable and let command execution report its
      // own authoritative error when the user actually sends one.
    }
  }

  public func saveOrgCryptConfiguration(
    encryptOnSave: Bool,
    recipientsText: String,
    recipientFilesText: String,
    useDefaultGpgKey: Bool,
    gpgProgram: String,
    passphrase: String,
    clearPassphrase: Bool
  ) -> Bool {
    let recipients = OrgCryptSettings.splitListText(recipientsText)
    let recipientFiles = OrgCryptSettings.splitListText(recipientFilesText)
    let normalizedGpgProgram = gpgProgram.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
      ? "gpg"
      : gpgProgram.trimmingCharacters(in: .whitespacesAndNewlines)

    do {
      defaults.set(encryptOnSave, forKey: orgCryptEncryptOnSaveKey)
      defaults.set(recipients, forKey: orgCryptRecipientsKey)
      defaults.set(recipientFiles, forKey: orgCryptRecipientFilesKey)
      defaults.set(useDefaultGpgKey, forKey: orgCryptUseDefaultGpgKeyKey)
      defaults.set(normalizedGpgProgram, forKey: orgCryptGpgProgramKey)

      orgCryptEncryptOnSave = encryptOnSave
      orgCryptRecipientsText = OrgCryptSettings.listText(recipients)
      orgCryptRecipientFilesText = OrgCryptSettings.listText(recipientFiles)
      orgCryptUseDefaultGpgKey = useDefaultGpgKey
      orgCryptGpgProgram = normalizedGpgProgram

      if clearPassphrase {
        try OrgCryptKeychain.deletePassphrase()
        orgCryptHasStoredPassphrase = false
      } else if !passphrase.isEmpty {
        try OrgCryptKeychain.savePassphrase(passphrase)
        orgCryptHasStoredPassphrase = true
      } else {
        orgCryptHasStoredPassphrase = OrgCryptKeychain.containsPassphrase()
      }

      orgCryptStatusText = orgCryptStatusText(settings: currentOrgCryptSettings())
      statusText = "Encryption settings saved"
      return true
    } catch {
      orgCryptStatusText = error.localizedDescription
      errorText = error.localizedDescription
      return false
    }
  }

  public var orgCryptPublicKeysDirectoryURL: URL? {
    corpusRoot?.appendingPathComponent(Self.orgCryptPublicKeysDirectoryName, isDirectory: true)
  }

  public func refreshOrgCryptManagedRecipientFiles() {
    orgCryptRecipientRefreshGeneration &+= 1
    let generation = orgCryptRecipientRefreshGeneration
    orgCryptRecipientRefreshTask?.cancel()
    guard let corpusRoot else {
      orgCryptManagedRecipientFiles = []
      orgCryptRecipientRefreshTask = nil
      return
    }
    let root = corpusRoot.standardizedFileURL
    let sessionGeneration = corpusSessionGeneration
    let observer = orgCryptRecipientScanForTesting
    orgCryptRecipientRefreshTask = Task { @MainActor [weak self] in
      let result = await Task.detached(priority: .utility) {
        observer?(Self.currentThreadIsMainForTesting())
        do {
          return OrgCryptRecipientScanResult.success(
            try Self.scanOrgCryptManagedRecipientFiles(corpusRoot: root)
          )
        } catch {
          return .failure(error.localizedDescription)
        }
      }.value
      guard let self,
            !Task.isCancelled,
            self.orgCryptRecipientRefreshGeneration == generation,
            self.isCurrentCorpusSession(root: root, generation: sessionGeneration)
      else { return }
      switch result {
      case .success(let files):
        self.orgCryptManagedRecipientFiles = files
      case .failure(let message):
        self.orgCryptManagedRecipientFiles = []
        self.orgCryptStatusText = message
      }
      self.orgCryptRecipientRefreshTask = nil
    }
  }

  func waitForOrgCryptRecipientRefreshForTesting() async {
    await orgCryptRecipientRefreshTask?.value
  }

  nonisolated public static func scanOrgCryptManagedRecipientFiles(corpusRoot: URL) throws -> [OrgCryptRecipientFile] {
    let root = corpusRoot.standardizedFileURL
    let directory = root.appendingPathComponent(orgCryptPublicKeysDirectoryName, isDirectory: true)
    let fileManager = FileManager.default
    var isDirectory: ObjCBool = false
    guard fileManager.fileExists(atPath: directory.path, isDirectory: &isDirectory), isDirectory.boolValue else {
      return []
    }

    return try fileManager.contentsOfDirectory(
      at: directory,
      includingPropertiesForKeys: [.isRegularFileKey],
      options: [.skipsHiddenFiles]
    )
    .filter { url in
      (try? url.resourceValues(forKeys: [.isRegularFileKey]).isRegularFile) == true
    }
    .map { url in
      let standardized = url.standardizedFileURL
      return OrgCryptRecipientFile(
        path: standardized.path,
        relativePath: Self.relativePath(for: standardized.path, root: root)
      )
    }
    .sorted { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }
  }

  @discardableResult
  public func importOrgCryptAgentPublicKey(from sourceURL: URL) throws -> OrgCryptRecipientFile {
    guard let corpusRoot else {
      throw OrgCryptPublicKeyImportError.missingCorpusRoot
    }

    let fileManager = FileManager.default
    let source = sourceURL.standardizedFileURL
    var isDirectory: ObjCBool = false
    guard fileManager.fileExists(atPath: source.path, isDirectory: &isDirectory), !isDirectory.boolValue else {
      throw OrgCryptPublicKeyImportError.invalidSource
    }

    let destinationDirectory = corpusRoot.standardizedFileURL
      .appendingPathComponent(Self.orgCryptPublicKeysDirectoryName, isDirectory: true)
    try fileManager.createDirectory(at: destinationDirectory, withIntermediateDirectories: true)
    let destination = destinationDirectory.appendingPathComponent(source.lastPathComponent, isDirectory: false).standardizedFileURL

    if source.path != destination.path {
      if fileManager.fileExists(atPath: destination.path) {
        try fileManager.removeItem(at: destination)
      }
      try fileManager.copyItem(at: source, to: destination)
    }

    let imported = OrgCryptRecipientFile(
      path: destination.path,
      relativePath: Self.relativePath(for: destination.path, root: corpusRoot.standardizedFileURL)
    )
    if !orgCryptManagedRecipientFiles.contains(where: { $0.path == imported.path }) {
      orgCryptManagedRecipientFiles.append(imported)
      orgCryptManagedRecipientFiles.sort { $0.relativePath.localizedStandardCompare($1.relativePath) == .orderedAscending }
    }
    refreshOrgCryptManagedRecipientFiles()
    orgCryptStatusText = "Added \(imported.name) to public keys"
    return imported
  }

  public func chooseOrgCryptAgentPublicKey() -> OrgCryptRecipientFile? {
    let panel = NSOpenPanel()
    panel.canChooseFiles = true
    panel.canChooseDirectories = false
    panel.allowsMultipleSelection = false
    panel.prompt = "Add"
    panel.message = "Choose an agent public key to copy into public-keys"

    guard panel.runModal() == .OK, let url = panel.url else { return nil }
    do {
      return try importOrgCryptAgentPublicKey(from: url)
    } catch {
      orgCryptStatusText = error.localizedDescription
      errorText = error.localizedDescription
      return nil
    }
  }

  public func normalizedOrgCryptRecipientFilePath(_ rawPath: String) -> String {
    let trimmed = rawPath.trimmingCharacters(in: .whitespacesAndNewlines)
    guard !trimmed.isEmpty else { return "" }
    if NSString(string: trimmed).isAbsolutePath {
      return URL(fileURLWithPath: trimmed).standardizedFileURL.path
    }
    guard let corpusRoot else { return trimmed }
    return corpusRoot.standardizedFileURL.appendingPathComponent(trimmed).standardizedFileURL.path
  }

  public func selectedManagedOrgCryptRecipientFilePaths(in recipientFilesText: String) -> Set<String> {
    let managed = Set(orgCryptManagedRecipientFiles.map(\.path))
    return Set(OrgCryptSettings.splitListText(recipientFilesText)
      .map { normalizedOrgCryptRecipientFilePath($0) }
      .filter { managed.contains($0) })
  }

  public func manualOrgCryptRecipientFilesText(from recipientFilesText: String) -> String {
    let managed = Set(orgCryptManagedRecipientFiles.map(\.path))
    let manual = OrgCryptSettings.splitListText(recipientFilesText)
      .filter { !managed.contains(normalizedOrgCryptRecipientFilePath($0)) }
    return OrgCryptSettings.listText(manual)
  }

  public func combinedOrgCryptRecipientFilesText(
    manualText: String,
    selectedManagedPaths: Set<String>
  ) -> String {
    var seen = Set<String>()
    var values: [String] = []
    for value in OrgCryptSettings.splitListText(manualText) {
      if seen.insert(normalizedOrgCryptRecipientFilePath(value)).inserted {
        values.append(value)
      }
    }
    for path in selectedManagedPaths.sorted() {
      let normalized = normalizedOrgCryptRecipientFilePath(path)
      if !normalized.isEmpty, seen.insert(normalized).inserted {
        values.append(normalized)
      }
    }
    return OrgCryptSettings.listText(values)
  }

  public func presentOrgCryptConfiguration() {
    isOrgCryptConfigurationPresented = true
  }

  /// Decrypts the armored block at `line` into a temporary sheet without
  /// modifying the document, so nothing ever needs to be re-encrypted.
  public func peekOrgCrypt(line explicitLine: Int? = nil) async {
    guard let file = selectedEntrySource?.file ?? selectedLocation?.file else {
      statusText = "Open a file before viewing encrypted text"
      return
    }
    let line = explicitLine ?? selectedBlock?.startLine ?? selectedLocation?.lineForEditor ?? 1

    let text: String
    let baseLine: Int
    if let source = selectedEntrySource,
       source.file == file,
       line >= source.startLine,
       !source.isSubtree || line < source.endLineExclusive {
      text = source.text
      baseLine = source.startLine
    } else if let diskText = try? String(contentsOfFile: NSString(string: file).expandingTildeInPath, encoding: .utf8) {
      text = diskText
      baseLine = 1
    } else {
      statusText = "Could not read \(relativePath(file))"
      return
    }

    guard let target = OrgCrypt.peekTarget(in: text, line: line, baseLine: baseLine) else {
      statusText = "No encrypted text found at \(relativePath(file)):\(line)"
      return
    }

    let peek = OrgCryptPeek(file: file, headingLine: target.headingLine, title: target.title, state: .decrypting)
    orgCryptPeek = peek
    let settings = await currentOrgCryptSettingsForOperation()
    let armor = target.armor
    let result: Result<String, Error> = await Task.detached(priority: .userInitiated) {
      Result { try OrgCrypt.decryptArmor(armor, settings: settings) }
    }.value
    // The sheet may have been closed (or replaced) while gpg was running;
    // in that case discard the plaintext instead of resurrecting it.
    guard orgCryptPeek?.id == peek.id else { return }
    switch result {
    case .success(let plaintext):
      orgCryptPeek?.state = .decrypted(plaintext)
    case .failure(let error):
      orgCryptPeek?.state = .failed(error.localizedDescription)
    }
  }

  public func dismissOrgCryptPeek() {
    orgCryptPeek = nil
  }

  /// Escape hatch from the peek sheet for when the user really does want to
  /// edit: the old in-file decrypt, which re-encrypts on save.
  public func decryptPeekedSubtreeInFile() async {
    guard let peek = orgCryptPeek else { return }
    orgCryptPeek = nil
    _ = await runOrgCrypt(.decrypt, line: peek.headingLine)
  }

  @discardableResult
  public func runOrgCrypt(_ action: OrgCryptAction, line explicitLine: Int? = nil) async -> OrgCryptRunResult {
    guard let file = selectedEntrySource?.file ?? selectedLocation?.file else {
      let message = "Open a file before running encryption"
      statusText = message
      return .failure(message: message)
    }

    let line = explicitLine ?? selectedBlock?.startLine ?? selectedLocation?.lineForEditor ?? 1
    let settings = await currentOrgCryptSettingsForOperation()
    orgCryptStatusText = "\(action.title) running \(relativePath(file)):\(line)"
    statusText = orgCryptStatusText
    var arguments = [
      "crypt",
      action.rawValue,
      "--file",
      file,
      "--line",
      "\(line)",
      "--gpg-program",
      settings.gpgProgram,
      "--gpg-timeout",
      "\(settings.gpgTimeout)",
      "--format",
      "json",
      "--apply"
    ]
    if let passphrase = settings.passphrase {
      arguments += ["--passphrase", passphrase]
    }
    if settings.useDefaultGpgKey {
      arguments += ["--default-recipient-self"]
    }
    for recipient in settings.recipients {
      arguments += ["--recipient", recipient]
    }
    for recipientFile in settings.recipientFiles {
      arguments += ["--recipient-file", recipientFile]
    }

    do {
      guard let context = captureDocumentCorpusContext(forFile: file) else {
        throw WorkspaceDocumentMutationError.outsideCorpus(
          file: file,
          root: corpusRoot?.path ?? "(none)"
        )
      }
      let cli = self.cli
      let cryptArguments = arguments
      let result = try await performDocumentMutation(context: context, files: [file]) { _ in
        try await cli.runJSON(cryptArguments, as: OrgCryptCLIPayload.self)
      }
      guard isCurrentDocumentCorpusContext(context) else {
        return .failure(message: "The active corpus changed", headingLine: line)
      }
      invalidateCanonicalDocumentCache(for: file)
      resetBlockEditing()
      isEditingEntry = false
      let succeeded = action == .decrypt ? result.changed : true
      orgCryptStatusText = "\(action.title) \(result.changed ? "updated" : "made no changes") \(relativePath(file)):\(result.headingLine)"
      statusText = orgCryptStatusText
      if let selectedLocation {
        await loadEntrySource(for: selectedLocation)
      }
      scheduleAgendaRefresh(preserveSelection: true)
      if succeeded {
        return .success(changed: result.changed, headingLine: result.headingLine, message: orgCryptStatusText)
      }
      return .failure(message: orgCryptStatusText, headingLine: result.headingLine)
    } catch {
      errorText = error.localizedDescription
      orgCryptStatusText = error.localizedDescription
      statusText = error.localizedDescription
      return .failure(message: error.localizedDescription, headingLine: line)
    }
  }

  private func rebuildAgendaDisplayCache() {
    agendaDisplaySections = Self.makeAgendaDisplaySections(
      agenda: agenda,
      mode: agendaMode,
      overdueOrder: agendaOverdueOrder,
      filter: agendaFilter,
      dateFilter: agendaDateFilter,
      assigneeFilter: agendaAssigneeFilter,
      statusFilter: agendaStatusFilter,
      priorityFilter: agendaPriorityFilter,
      topicFilter: agendaTopicFilter,
      buckets: agendaDisplayBuckets,
      filterTextByItemID: agendaFilterTextByItemID
    )
    visibleAgendaItems = agendaDisplaySections.flatMap(\.items)
  }

  /// Corpus-scale run projection building is deliberately detached from
  /// observation publication. A large run archive otherwise turns assigning
  /// one CLI response (and each filter keystroke) into a long MainActor stall.
  private func scheduleAgentRunProjectionRefresh(debounce: Bool = false) {
    agentRunProjectionGeneration &+= 1
    let generation = agentRunProjectionGeneration
    agentRunProjectionTask?.cancel()

    // Keep tiny fixtures and single-run lifecycle mutations immediately
    // coherent without paying task scheduling overhead. Real archives use the
    // detached path below.
    guard agentRuns.count > 256 else {
      publishAgentRunProjection(Self.agentRunProjection(
        runs: agentRuns,
        filterTerms: agentRunFilterTerms
      )!)
      agentRunProjectionTask = nil
      return
    }

    let runs = agentRuns
    let terms = agentRunFilterTerms
    let revision = agentRunsRevision
    // A filter keystroke over an unchanged archive reuses the per-run indexes;
    // only the cheap term match and section grouping run again.
    let indexes = agentRunProjectionIndexes?.revision == revision
      ? agentRunProjectionIndexes?.box
      : nil
    let preparation = agentRunProjectionPreparationForTesting
    let didBuild = agentRunProjectionDidBuildForTesting
    agentRunProjectionTask = Task { @MainActor [weak self] in
      if debounce {
        do {
          try await Task.sleep(nanoseconds: 80_000_000)
        } catch {
          return
        }
      }
      let build = Task.detached(priority: .userInitiated) { () -> AgentRunProjectionBox? in
        if let preparation { await preparation() }
        let projection: AgentRunProjectionBox?
        if let indexes {
          projection = Self.agentRunProjection(reusing: indexes, filterTerms: terms, checksCancellation: true)
        } else {
          projection = Self.agentRunProjection(runs: runs, filterTerms: terms, checksCancellation: true)
        }
        guard let projection else { return nil }
        didBuild?(projection.wasBuiltOnMainThread)
        return projection
      }
      // Superseded keystrokes cancel their build instead of competing with
      // the current one for CPU.
      let projection = await withTaskCancellationHandler {
        await build.value
      } onCancel: {
        build.cancel()
      }
      guard let self,
            let projection,
            !Task.isCancelled,
            self.agentRunProjectionGeneration == generation,
            self.agentRunsRevision == revision,
            self.agentRunFilterTerms == terms
      else { return }
      self.publishAgentRunProjection(projection, runsRevision: revision)
      self.agentRunProjectionTask = nil
    }
  }

  /// Builds the complete projection. Returns nil only when `checksCancellation`
  /// is set and the surrounding task is canceled.
  nonisolated private static func agentRunProjection(
    runs: [AgentRunItem],
    filterTerms: [String],
    checksCancellation: Bool = false
  ) -> AgentRunProjectionBox? {
    var filterTextByID: [AgentRunItem.ID: String] = [:]
    var runsByID: [AgentRunItem.ID: AgentRunItem] = [:]
    var countByGoalRef: [String: Int] = [:]
    var countByAgentRef: [String: Int] = [:]
    filterTextByID.reserveCapacity(runs.count)
    runsByID.reserveCapacity(runs.count)
    for (index, run) in runs.enumerated() {
      if checksCancellation, index % 256 == 0, Task.isCancelled { return nil }
      filterTextByID[run.id] = run.runFilterText
      runsByID[run.id] = run
      if let goalRef = run.goalRef { countByGoalRef[goalRef, default: 0] += 1 }
      if let agentRef = run.agentRef { countByAgentRef[agentRef, default: 0] += 1 }
    }

    var scopeCounts: [AgentRunScope: Int] = [:]
    var scopeEntries: [AgentRunScope: [AgentRunScopeEntry]] = [:]
    let sourceMeetingContexts = RunCenterPresentation.sourceMeetingContextsByRunID(in: runs)
    var runIDsBySourceMeetingReference: [String: [AgentRunItem.ID]] = [:]
    runIDsBySourceMeetingReference.reserveCapacity(min(sourceMeetingContexts.count, 32))
    for run in runs {
      guard let context = sourceMeetingContexts[run.id] else { continue }
      let reference = context.fileReference ?? context.ref
      runIDsBySourceMeetingReference[reference, default: []].append(run.id)
    }

    for scope in AgentRunScope.allCases {
      let entries = scope.entries(in: runs)
      scopeEntries[scope] = entries
      scopeCounts[scope] = entries.count
    }

    let indexes = AgentRunProjectionBox(
      filterTextByID: filterTextByID,
      runsByID: runsByID,
      countByGoalRef: countByGoalRef,
      countByAgentRef: countByAgentRef,
      scopeCounts: scopeCounts,
      scopeEntries: scopeEntries,
      filteredScopeEntries: [:],
      filteredScopeIDs: [:],
      filteredScopeIDSets: [:],
      sectionsByScope: [:],
      sourceMeetingContextsByID: sourceMeetingContexts,
      runIDsBySourceMeetingReference: runIDsBySourceMeetingReference,
      wasBuiltOnMainThread: Thread.isMainThread
    )
    guard let projection = agentRunProjection(
      reusing: indexes,
      filterTerms: filterTerms,
      checksCancellation: checksCancellation
    ) else {
      return nil
    }
    projection.reusedRunIndexes = false
    return projection
  }

  /// Applies `filterTerms` to run-derived indexes that are already built.
  /// Returns nil only when `checksCancellation` is set and the surrounding
  /// task is canceled.
  nonisolated private static func agentRunProjection(
    reusing indexes: AgentRunProjectionBox,
    filterTerms: [String],
    checksCancellation: Bool = false
  ) -> AgentRunProjectionBox? {
    var filteredEntries: [AgentRunScope: [AgentRunScopeEntry]] = [:]
    var filteredIDs: [AgentRunScope: [AgentRunItem.ID]] = [:]
    var filteredIDSets: [AgentRunScope: Set<AgentRunItem.ID>] = [:]
    var sectionsByScope: [AgentRunScope: [RunCenterSection]] = [:]

    for scope in AgentRunScope.allCases {
      if checksCancellation, Task.isCancelled { return nil }
      let entries = indexes.scopeEntries[scope] ?? []
      let visibleEntries = filterTerms.isEmpty
        ? entries
        : entries.filter { entry in
          let text = indexes.filterTextByID[entry.id] ?? entry.run.runFilterText
          return filterTerms.allSatisfy { text.contains($0) }
        }
      filteredEntries[scope] = visibleEntries
      let visibleIDs = visibleEntries.map(\.id)
      filteredIDs[scope] = visibleIDs
      filteredIDSets[scope] = Set(visibleIDs)
      sectionsByScope[scope] = RunCenterPresentation.sections(
        for: visibleEntries,
        sourceMeetingContexts: indexes.sourceMeetingContextsByID
      )
    }

    let projection = AgentRunProjectionBox(
      filterTextByID: indexes.filterTextByID,
      runsByID: indexes.runsByID,
      countByGoalRef: indexes.countByGoalRef,
      countByAgentRef: indexes.countByAgentRef,
      scopeCounts: indexes.scopeCounts,
      scopeEntries: indexes.scopeEntries,
      filteredScopeEntries: filteredEntries,
      filteredScopeIDs: filteredIDs,
      filteredScopeIDSets: filteredIDSets,
      sectionsByScope: sectionsByScope,
      sourceMeetingContextsByID: indexes.sourceMeetingContextsByID,
      runIDsBySourceMeetingReference: indexes.runIDsBySourceMeetingReference,
      wasBuiltOnMainThread: Thread.isMainThread
    )
    projection.reusedRunIndexes = true
    return projection
  }

  private func publishAgentRunProjection(
    _ projection: AgentRunProjectionBox,
    runsRevision: UInt64? = nil
  ) {
    agentRunProjectionIndexes = (runsRevision ?? agentRunsRevision, projection)
    if projection.reusedRunIndexes {
      agentRunProjectionIndexReuseCountForTesting &+= 1
    }
    agentRunProjectionBuildCountForTesting &+= 1
    if projection.wasBuiltOnMainThread {
      agentRunProjectionMainThreadBuildCountForTesting &+= 1
    }
    agentRunFilterTextByID = projection.filterTextByID
    agentRunsByID = projection.runsByID
    agentRunCountByGoalRef = projection.countByGoalRef
    agentRunCountByAgentRef = projection.countByAgentRef
    agentRunScopeCounts = projection.scopeCounts
    agentRunScopeEntriesByScope = projection.scopeEntries
    filteredAgentRunScopeEntries = projection.filteredScopeEntries
    filteredAgentRunScopeIDs = projection.filteredScopeIDs
    filteredAgentRunScopeIDSets = projection.filteredScopeIDSets
    agentRunSectionsByScope = projection.sectionsByScope
    agentRunSourceMeetingContextsByID = projection.sourceMeetingContextsByID
    agentRunIDsBySourceMeetingReference = projection.runIDsBySourceMeetingReference
    agentRunDisplayRevision &+= 1
  }

  func waitForAgentRunProjectionForTesting() async {
    await agentRunProjectionTask?.value
  }

  private func rebuildAgendaSearchIndex() {
    guard let agenda else {
      agendaFilterTextByItemID = [:]
      agendaDisplayBuckets = AgendaDisplayBuckets()
      rebuildAgendaFilterOptions()
      return
    }
    let next7End = Self.isoDate(
      Calendar(identifier: .gregorian).date(
        byAdding: .day,
        value: 7,
        to: Self.dateFromISO(agenda.range.start) ?? Date()
      ) ?? Date()
    )
    agendaDisplayBuckets = AgendaDisplayBuckets(
      overdue: agenda.overdue.flatMap(\.items),
      today: agenda.days.filter { $0.date == agenda.range.start }.flatMap(\.items),
      next7: agenda.days
        .filter { $0.date > agenda.range.start && $0.date <= next7End }
        .flatMap(\.items),
      later: agenda.days
        .filter { $0.date > next7End }
        .flatMap(\.items)
    )
    var index: [AgendaItem.ID: String] = [:]
    let items = agendaDisplayBuckets.overdue
      + agendaDisplayBuckets.today
      + agendaDisplayBuckets.next7
      + agendaDisplayBuckets.later
    index.reserveCapacity(items.count)
    for item in items {
      index[item.id] = item.agendaFilterText
    }
    agendaFilterTextByItemID = index
    rebuildAgendaFilterOptions()
  }

  private func rebuildAgendaFilterOptions() {
    let agendaItems = agendaDisplayBuckets.overdue
      + agendaDisplayBuckets.today
      + agendaDisplayBuckets.next7
      + agendaDisplayBuckets.later
    let agendaAssignees = agendaItems.compactMap {
      Self.propertyValue("ASSIGNEE", in: $0.properties)
    }
    let agendaStatuses = agendaItems.flatMap { item in
      [item.todo, Self.propertyValue("STATUS", in: item.properties)].compactMap { $0 }
    }
    let agendaPriorities = agendaItems.compactMap { item in
      item.priority ?? Self.propertyValue("PRIORITY", in: item.properties)
    }
    let assignedStatuses = assignedWorkItems.flatMap { item in
      [item.todo, item.status, Self.propertyValue("STATUS", in: item.properties)].compactMap { $0 }
    }
    let assignedPriorities = assignedWorkItems.compactMap {
      Self.propertyValue("PRIORITY", in: $0.properties)
    }

    agendaAssigneeFilterOptions = Self.sortedUniqueFacetValues(
      agendaAssignees + assignedWorkItems.map(\.assignee)
    )
    agendaStatusFilterOptions = Self.sortedUniqueFacetValues(agendaStatuses + assignedStatuses)
    agendaPriorityFilterOptions = Self.sortedUniqueFacetValues(agendaPriorities + assignedPriorities)
    agendaTopicFilterOptions = Self.sortedUniqueFacetValues(
      agendaItems.flatMap(\.tags) + assignedWorkItems.flatMap(\.tags)
    )
  }

  nonisolated private static func sortedUniqueFacetValues(_ values: [String]) -> [String] {
    var displayByNormalizedValue: [String: String] = [:]
    for value in values {
      let display = value.trimmingCharacters(in: .whitespacesAndNewlines)
      guard !display.isEmpty else { continue }
      let normalized = display.lowercased()
      if displayByNormalizedValue[normalized] == nil {
        displayByNormalizedValue[normalized] = display
      }
    }
    return displayByNormalizedValue.values.sorted {
      $0.localizedCaseInsensitiveCompare($1) == .orderedAscending
    }
  }

  nonisolated private static func propertyValue(
    _ key: String,
    in properties: [String: String]
  ) -> String? {
    properties.first { $0.key.caseInsensitiveCompare(key) == .orderedSame }?.value
  }

  private static func makeAgendaDisplaySections(
    agenda: AgendaPayload?,
    mode: AgendaMode,
    overdueOrder: AgendaOverdueOrder,
    filter: String,
    dateFilter: AgendaDateFilter,
    assigneeFilter: String,
    statusFilter: String,
    priorityFilter: String,
    topicFilter: String,
    buckets: AgendaDisplayBuckets,
    filterTextByItemID: [AgendaItem.ID: String]
  ) -> [AgendaDisplaySection] {
    guard agenda != nil else { return [] }
    let terms = filterTerms(from: filter)
    let matchesFilter: (AgendaItem) -> Bool = { item in
      guard matchesAgendaStructuredFilters(
        item,
        assignee: assigneeFilter,
        status: statusFilter,
        priority: priorityFilter,
        topic: topicFilter
      ) else { return false }
      guard !terms.isEmpty else { return true }
      let searchText = filterTextByItemID[item.id] ?? item.agendaFilterText
      return terms.allSatisfy { searchText.contains($0) }
    }
    let overdue = sortedOverdueItems(
      (dateFilter == .any || dateFilter == .overdue ? buckets.overdue : []).filter(matchesFilter),
      order: overdueOrder
    )
    let today = (dateFilter == .any || dateFilter == .today ? buckets.today : []).filter(matchesFilter)
    let next7 = (dateFilter == .any || dateFilter == .next7 ? buckets.next7 : []).filter(matchesFilter)
    let later = (dateFilter == .any || dateFilter == .later ? buckets.later : []).filter(matchesFilter)

    switch mode {
    case .focus:
      let todayActionable = today.filter(\.isActionable)
      let overdueActionable = overdue.filter(\.isActionable)
      let doneToday = today.filter { !$0.isActionable }
      return [
        AgendaDisplaySection(id: "focus-today", label: "Today", items: todayActionable, hint: "today"),
        AgendaDisplaySection(id: "focus-overdue", label: "Overdue", items: overdueActionable, hint: "overdue"),
        AgendaDisplaySection(id: "focus-closed", label: "Done or canceled", items: doneToday, hint: "today")
      ].filter { !$0.items.isEmpty }
    case .today:
      return [
        AgendaDisplaySection(id: "today", label: "Today", items: today, hint: "today"),
        AgendaDisplaySection(id: "overdue", label: "Overdue", items: overdue, hint: "overdue")
      ].filter { !$0.items.isEmpty }
    case .range:
      return [
        AgendaDisplaySection(id: "overdue", label: "Overdue", items: overdue, hint: "overdue"),
        AgendaDisplaySection(id: "today", label: "Today", items: today, hint: "today"),
        AgendaDisplaySection(id: "next-7-days", label: "Next 7 days", items: next7, hint: "upcoming"),
        AgendaDisplaySection(id: "later", label: "Later", items: later, hint: "upcoming")
      ].filter { !$0.items.isEmpty }
    case .assigned:
      return []
    }
  }

  nonisolated private static func matchesAgendaStructuredFilters(
    _ item: AgendaItem,
    assignee: String,
    status: String,
    priority: String,
    topic: String
  ) -> Bool {
    let itemAssignee = propertyValue("ASSIGNEE", in: item.properties)?
      .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    if assignee == agendaUnassignedFilter {
      guard itemAssignee.isEmpty else { return false }
    } else if !assignee.isEmpty,
              itemAssignee.caseInsensitiveCompare(assignee) != .orderedSame {
      return false
    }

    let todo = item.todo?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
    let propertyStatus = propertyValue("STATUS", in: item.properties) ?? ""
    if status == agendaOpenStatusFilter {
      guard item.isActionable else { return false }
    } else if status == agendaCompletedStatusFilter {
      guard !item.isActionable else { return false }
    } else if !status.isEmpty,
              todo.caseInsensitiveCompare(status) != .orderedSame,
              propertyStatus.caseInsensitiveCompare(status) != .orderedSame {
      return false
    }

    let itemPriority = item.priority ?? propertyValue("PRIORITY", in: item.properties) ?? ""
    if priority == agendaNoPriorityFilter {
      guard itemPriority.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { return false }
    } else if !priority.isEmpty,
              itemPriority.caseInsensitiveCompare(priority) != .orderedSame {
      return false
    }

    if !topic.isEmpty,
       !item.tags.contains(where: { $0.caseInsensitiveCompare(topic) == .orderedSame }) {
      return false
    }
    return true
  }

  nonisolated static func sortedOverdueItems(
    _ items: [AgendaItem],
    order: AgendaOverdueOrder
  ) -> [AgendaItem] {
    guard order == .priority else { return items }

    return items.enumerated().sorted { left, right in
      let leftRank = agendaPriorityRank(left.element.priority)
      let rightRank = agendaPriorityRank(right.element.priority)
      if leftRank != rightRank {
        return leftRank < rightRank
      }
      return left.offset < right.offset
    }.map(\.element)
  }

  nonisolated private static func agendaPriorityRank(_ rawPriority: String?) -> Int {
    guard var priority = rawPriority?.trimmingCharacters(in: .whitespacesAndNewlines),
          !priority.isEmpty
    else {
      return Int.max
    }
    if priority.hasPrefix("[#"), priority.hasSuffix("]"), priority.count == 4 {
      priority = String(priority.dropFirst(2).dropLast())
    }
    guard let scalar = priority.uppercased().unicodeScalars.first,
          priority.unicodeScalars.count == 1
    else {
      return Int.max - 1
    }
    switch scalar.value {
    case 65...90:
      return Int(scalar.value - 65)
    case 48...57:
      return 26 + Int(scalar.value - 48)
    default:
      return Int.max - 1
    }
  }

  private static func filterTerms(from query: String) -> [String] {
    query
      .trimmingCharacters(in: .whitespacesAndNewlines)
      .lowercased()
      .split(whereSeparator: { $0.isWhitespace })
      .map(String.init)
  }

  public var visibleAgendaItemCount: Int {
    visibleAgendaItems.count
  }

  public var bulkAgendaSelectionCount: Int {
    let visibleIDs = Set(visibleAgendaItems.map(\.id))
    return bulkSelectedAgendaItemIDs.intersection(visibleIDs).count
  }

  public var hasBulkAgendaSelection: Bool {
    bulkAgendaSelectionCount > 0
  }

  public func isAgendaItemBulkSelected(_ item: AgendaItem) -> Bool {
    bulkSelectedAgendaItemIDs.contains(item.id)
  }

  public func toggleAgendaItemBulkSelection(_ item: AgendaItem) {
    guard isResultInActiveCorpus(item.corpus) else {
      statusText = "Open \(item.corpus?.name ?? "the corpus") before editing this item"
      return
    }
    var ids = bulkSelectedAgendaItemIDs
    if ids.contains(item.id) {
      ids.remove(item.id)
    } else {
      ids.insert(item.id)
    }
    bulkSelectedAgendaItemIDs = ids
    updateAgendaBulkSelectionStatusText()
  }

  public func selectAllVisibleAgendaItemsForBulkAction() {
    let ids = Set(visibleAgendaItems.filter { isResultInActiveCorpus($0.corpus) }.map(\.id))
    bulkSelectedAgendaItemIDs = ids
    if ids.isEmpty {
      statusText = "No visible agenda items"
    } else {
      statusText = ids.count == 1 ? "1 agenda item selected" : "\(ids.count) agenda items selected"
    }
  }

  public func clearAgendaBulkSelection() {
    guard !bulkSelectedAgendaItemIDs.isEmpty else { return }
    bulkSelectedAgendaItemIDs = []
    statusText = "Agenda selection cleared"
  }

  public func handleAgendaItemClick(_ item: AgendaItem, modifiers: NSEvent.ModifierFlags = []) {
    if modifiers.intersection([.command]).contains(.command) {
      toggleAgendaItemBulkSelection(item)
      selectAgendaItem(item)
    } else {
      selectAgendaItem(item)
    }
  }

  public func extendAgendaBulkSelection(by delta: Int) {
    let items = visibleAgendaItems
    guard !items.isEmpty else {
      statusText = "No visible agenda items"
      return
    }

    let currentIndex = selectedAgendaItemID.flatMap { id in items.firstIndex(where: { $0.id == id }) }
    let nextIndex: Int
    if let currentIndex {
      nextIndex = max(0, min(items.count - 1, currentIndex + delta))
    } else {
      nextIndex = delta < 0 ? items.count - 1 : 0
    }

    var ids = bulkSelectedAgendaItemIDs
    if let currentIndex {
      ids.insert(items[currentIndex].id)
    }
    ids.insert(items[nextIndex].id)
    bulkSelectedAgendaItemIDs = ids
    selectAgendaItem(items[nextIndex])
    updateAgendaBulkSelectionStatusText()
  }

  public func selectAgendaItem(_ item: AgendaItem) {
    deactivateAgendaFilterFocus()
    suppressNextAgendaSelectionActivation = false
    if activateCorpusIfNeeded(for: item.corpus, location: .agenda(item), surface: .agenda) {
      return
    }
    select(.agenda(item), surface: .agenda)
  }

  private func selectAgendaItemWithoutActivatingEntry(_ item: AgendaItem) {
    suppressNextAgendaSelectionActivation = true
    selectedSurface = .agenda
    selectedAgendaItemID = item.id
    agendaSelectionAnchor = AgendaSelectionAnchor(item: item)
  }

  public func moveAgendaSelection(by delta: Int) {
    if agendaMode == .assigned {
      moveAssignedAgendaSelection(by: delta)
      return
    }
    let items = visibleAgendaItems
    guard !items.isEmpty else { return }

    let currentIndex = selectedAgendaItemID.flatMap { id in items.firstIndex(where: { $0.id == id }) }
    let nextIndex: Int
    if let currentIndex {
      nextIndex = max(0, min(items.count - 1, currentIndex + delta))
    } else {
      nextIndex = delta < 0 ? items.count - 1 : 0
    }
    selectAgendaItem(items[nextIndex])
  }

